#!/usr/bin/env python3
r"""Telegram Cloud Vault - single file (server.py).

Run:  python server.py   ->  http://127.0.0.1:8080
Backend (Flask + Telethon + sqlite) and the whole web UI live in this one file. Data goes to ./storage.
Everything needed (Flask, Telethon, Pillow, ffmpeg, HEIC + PDF tools) installs itself on the first start.
"""
import asyncio, base64, concurrent.futures, copy, gzip, hashlib, hmac, http.client, importlib.util, io, itertools, json, mimetypes, os, queue
import re, secrets, shutil, socket, sqlite3, subprocess, sys, threading, time, zipfile, zlib
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path
from urllib.parse import urlparse


# ----------------------------------------------------------------------------------------------
# AUTO-INSTALL  - everything the app needs is fetched automatically on the first start.
#   Termux : pkg  -> python-pillow, ffmpeg, libheif tools (HEIC), poppler (PDF)   |  pip -> flask, telethon, waitress
#   Others : pip  -> flask, telethon, Pillow, pillow-heif, cryptg
# Only missing things are installed, so later starts are instant. Optional parts never stop the server.
# ----------------------------------------------------------------------------------------------
IS_TERMUX = "com.termux" in os.environ.get("PREFIX", "") or Path("/data/data/com.termux/files/usr").exists()
_DEVNULL = subprocess.DEVNULL
_APT_UPDATED = False


def _has_module(name):
    importlib.invalidate_caches()
    try:
        return importlib.util.find_spec(name) is not None
    except Exception:
        return False


def _quiet(cmd, timeout=1800):
    try:
        env = dict(os.environ, DEBIAN_FRONTEND="noninteractive", PIP_DISABLE_PIP_VERSION_CHECK="1")
        return subprocess.run(cmd, stdout=_DEVNULL, stderr=_DEVNULL, stdin=_DEVNULL, timeout=timeout, env=env).returncode == 0
    except Exception:
        return False


def ensure(module, pip_name=None, required=True, only_binary=False):
    """pip-install a Python package if missing. Quiet: prints one line, and the error tail only if it is required."""
    if _has_module(module):
        return True
    if os.environ.get("VAULT_ANDROID") == "1":      # ANDROID PATCH: all packages are bundled in the APK, never install at runtime
        return False
    name = pip_name or module
    print(f"Installing {name} ...", flush=True)
    cmd = [sys.executable, "-m", "pip", "install", "-q", "--disable-pip-version-check"] + (["--only-binary=:all:"] if only_binary else []) + [name]
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, stdin=_DEVNULL, timeout=1800)
        ok = r.returncode == 0 and _has_module(module)
        err = (r.stderr or "").strip().splitlines()[-3:]
    except Exception as e:
        ok, err = False, [str(e)]
    if not ok:
        if required:
            print("\n".join("  " + x for x in err))
            sys.exit(f"{module} is required and could not be installed. Check your internet and run again.")
        print(f"  {name}: skipped (optional)", flush=True)
    return ok


def _pkg_install(*names):
    """Termux package manager. Retries once after refreshing the package lists."""
    global _APT_UPDATED
    if _quiet(["pkg", "install", "-y", *names]):
        return True
    if not _APT_UPDATED:
        _APT_UPDATED = True
        _quiet(["pkg", "update", "-y"])
        return _quiet(["pkg", "install", "-y", *names])
    return False


def _termux_tools():
    if not shutil.which("pkg"):
        return
    specs = [                                        # (label, "is it installed?", [Termux package names to try])
        ("Pillow (thumbnails)",   lambda: _has_module("PIL"),                                  ["python-pillow"]),
        ("ffmpeg (video/photo)",  lambda: bool(shutil.which("ffmpeg")),                        ["ffmpeg"]),
        ("HEIC tools",            lambda: bool(shutil.which("heif-dec") or shutil.which("heif-convert")), ["libheif-progs", "libheif"]),
        ("PDF tools",             lambda: bool(shutil.which("pdftoppm")),                      ["poppler"]),
        ("OCR (tesseract)",       lambda: bool(shutil.which("tesseract")),                     ["tesseract"]),     # text inside photos -> searchable
    ]
    for label, present, pkgs in specs:
        if present():
            continue
        print(f"Installing {label} ...", flush=True)
        for p in pkgs:
            _pkg_install(p)
            if present():
                break
        else:
            print(f"  {label}: skipped (optional)", flush=True)


ensure("flask")
ensure("telethon", required=False)
if os.environ.get("VAULT_WAITRESS", "1") != "0":
    ensure("waitress", required=False)                  # light, fast web server (pure python); if it cannot be installed the normal server is used
if IS_TERMUX:
    _termux_tools()                                  # Pillow comes from pkg here (pip cannot compile it on Android)
else:
    ensure("PIL", "Pillow", required=False)
    ensure("pillow_heif", "pillow-heif", required=False, only_binary=True)   # HEIC thumbnails
def _cryptg_setup():
    """cryptg = much faster Telegram upload/download. Installed automatically; never stops the server."""
    if _has_module("cryptg"):
        return
    if ensure("cryptg", required=False, only_binary=True):          # ready-made wheel (computers, most phones)
        return
    if ensure("cryptg", required=False):                            # build from source if a compiler is there
        return
    if IS_TERMUX and shutil.which("pkg"):                           # Termux: needs Rust to build it
        print("Installing Rust to build cryptg (one time, can take several minutes) ...", flush=True)
        _pkg_install("rust", "binutils", "clang", "make")
        if ensure("cryptg", "cryptg", required=False):
            print("cryptg installed - restart the server for full speed.", flush=True)


if os.environ.get("VAULT_NO_CRYPTG") != "1":
    if IS_TERMUX:
        threading.Thread(target=_cryptg_setup, daemon=True, name="cryptg-setup").start()   # slow build: server starts meanwhile
    else:
        _cryptg_setup()

try:                                                 # HEIC through Pillow when pillow-heif is present
    if _has_module("pillow_heif"):
        import pillow_heif
        pillow_heif.register_heif_opener()
except Exception:
    pass

