def ensure_dirs():
    for p in (CONFIG_DIR, CACHE, THUMBS, PREVIEWS, TMP):
        p.mkdir(parents=True, exist_ok=True)
    # ".nomedia": Android Gallery / media scanner skips these folders, so thumbs, previews, bg, avatar, chatview and cache pictures
    # never show up in the phone's Gallery (the files keep their normal names, the website works exactly as before).
    for p in (STORAGE, CONFIG_DIR, CACHE, THUMBS, PREVIEWS, TMP, STORAGE / "chatview"):
        try:
            if p.is_dir() and not (p / ".nomedia").exists():
                (p / ".nomedia").write_bytes(b"")
        except OSError:
            pass


ensure_dirs()


# ── Encrypted personal files ───────────────────────────────────────────────────────────────────────────────────────────────
# settings.json, lock.json, locked_keep.json, ftp / LAN / share state, favorites, download log and sticky_ip.txt are stored ENCRYPTED
# (stream cipher from SHAKE-256 + HMAC-SHA256 tag, all standard library). The key lives in the private Termux home (NOT in the
# shared storage folder that file managers can open): ~/.vault_key  (change with VAULT_KEY_FILE). KEEP A COPY OF THAT KEY FILE:
# without it these files cannot be read any more.
_VMAGIC = b"VLT1"
_VKEY = [None]


def _vkey():
    if _VKEY[0]:
        return _VKEY[0]
    cands = []
    if os.environ.get("VAULT_KEY_FILE"):
        cands.append(Path(os.environ["VAULT_KEY_FILE"]))
    try:
        cands.append(Path.home() / ".vault_key")
    except Exception:
        pass
    cands.append(STORAGE / ".vault_key")                 # last resort only (shared storage): used when the home folder is not writable
    for c in cands:
        try:
            raw = c.read_bytes()
            if len(raw) >= 32:
                _VKEY[0] = raw[:32]
                return _VKEY[0]
        except OSError:
            continue
    key = secrets.token_bytes(32)
    for c in cands:
        try:
            c.parent.mkdir(parents=True, exist_ok=True)
            fd = os.open(str(c), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            with os.fdopen(fd, "wb") as f:
                f.write(key)
            _VKEY[0] = key
            return key
        except OSError:
            continue
    _VKEY[0] = key                                       # cannot save the key: works until restart only
    return key


def vseal(data, key=None):
    key, nonce = key or _vkey(), secrets.token_bytes(16)
    n = len(data)
    ks = hashlib.shake_256(b"enc" + key + nonce).digest(n) if n else b""
    ct = (int.from_bytes(data, "big") ^ int.from_bytes(ks, "big")).to_bytes(n, "big") if n else b""
    tag = hmac.new(key, _VMAGIC + nonce + ct, hashlib.sha256).digest()
    return _VMAGIC + nonce + ct + tag


def vopen(blob, key=None):
    if not blob.startswith(_VMAGIC):
        return blob                                      # older plain file: still readable (it is encrypted at the next save / start)
    key = key or _vkey()
    nonce, ct, tag = blob[4:20], blob[20:-32], blob[-32:]
    if len(blob) < 52 or not hmac.compare_digest(hmac.new(key, _VMAGIC + nonce + ct, hashlib.sha256).digest(), tag):
        raise ValueError("encrypted file cannot be opened (wrong or missing key)")
    n = len(ct)
    ks = hashlib.shake_256(b"enc" + key + nonce).digest(n) if n else b""
    return (int.from_bytes(ct, "big") ^ int.from_bytes(ks, "big")).to_bytes(n, "big") if n else b""


def sec_read(path):
    """Text of a (possibly encrypted) personal file."""
    return vopen(Path(path).read_bytes()).decode("utf-8")


def sec_write(path, text):
    """Write encrypted text (the caller does the os.replace of its own tmp file)."""
    path = Path(path)
    path.write_bytes(vseal(text.encode("utf-8")))
    try:
        os.chmod(path, 0o600)
    except OSError:
        pass


def sec_migrate():
    """Start-up: every personal file that is still plain text is replaced by its encrypted version."""
    try:
        files = [CONFIG_FILE, FAV_KEEP, CONFIG_DIR / "lock.json", CONFIG_DIR / "lock.json.bak", CONFIG_DIR / "locked_keep.json",
                 CONFIG_DIR / "download_log.json", CONFIG_DIR / "ftp_state.json", CONFIG_DIR / "sticky_ip.txt"]
        for sub in ("lan", ):
            files += [f for f in (CONFIG_DIR / sub).rglob("*.json")] if (CONFIG_DIR / sub).is_dir() else []
        for f in files:
            try:
                if f.is_file():
                    raw = f.read_bytes()
                    if raw and not raw.startswith(_VMAGIC):
                        tmp = f.with_name(f.name + ".mig")
                        sec_write(tmp, raw.decode("utf-8"))
                        os.replace(tmp, f)
            except Exception:
                continue
        _cfg_cache[0] = None
    except Exception:
        pass


