# UTIL  (was vault/util.py)
# ============================================================================
IMAGE_EXT = {".jpg", ".jpeg", ".png", ".gif", ".webp", ".bmp", ".heic", ".heif", ".avif", ".tif", ".tiff"}
VIDEO_EXT = {".mp4", ".mov", ".mkv", ".webm", ".avi", ".3gp", ".m4v", ".mpg", ".mpeg", ".ts"}


def now():
    return datetime.now(timezone.utc).astimezone().isoformat(timespec="seconds")


def iso_from_ts(ts):
    return datetime.fromtimestamp(ts, timezone.utc).astimezone().isoformat(timespec="seconds")


def human_size(n):
    n = float(n or 0)
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if n < 1024 or unit == "TB":
            return f"{int(n)} B" if unit == "B" else f"{n:.1f} {unit}"
        n /= 1024


def sha256_file(path, chunk=1024 * 1024, check=None):
    h, size = hashlib.sha256(), 0
    with open(path, "rb") as f:
        for block in iter(lambda: f.read(chunk), b""):
            if check:
                check()
            h.update(block)
            size += len(block)
    return h.hexdigest(), size


def kind_for(name, mime=None):
    ext = Path(name or "").suffix.lower()
    if (mime or "").startswith("image/") or ext in IMAGE_EXT:
        return "image"
    if (mime or "").startswith("video/") or ext in VIDEO_EXT:
        return "video"
    return "other"


def safe_name(name):
    name = (name or "file").replace("\\", "/").split("/")[-1]
    name = re.sub(r"[^\w.\- ()\[\]]+", "_", name, flags=re.UNICODE).strip(" .")
    return (name or "file")[:120]


def battery():
    """(percent, charging) - best effort on Linux/Android(Termux); (None, None) if unknown."""
    base = Path("/sys/class/power_supply")
    try:
        for d in base.iterdir():
            cap = d / "capacity"
            if cap.exists() and (d / "type").exists() and (d / "type").read_text().strip() == "Battery":
                pct = int(cap.read_text().strip())
                st = (d / "status").read_text().strip().lower() if (d / "status").exists() else ""
                return pct, st in ("charging", "full")
    except Exception:
        pass
    return None, None


_WIFI_CACHE = [0.0, None]
_WIFI_NAMES = ("wlan", "wl", "eth", "en", "swlan")
_MOBILE_NAMES = ("rmnet", "ccmni", "pdp", "ppp", "wwan", "v4-rmnet", "r_rmnet", "seth_lte")


def on_wifi():
    """True = Wi-Fi / Ethernet, False = mobile data (or no network), None = cannot tell (then nothing is blocked).
    Best effort on Linux / Android (Termux). Result is cached for 8 seconds."""
    if time.time() - _WIFI_CACHE[0] < 8:
        return _WIFI_CACHE[1]
    res = None
    try:                                                    # 1) interface of the default route
        for line in Path("/proc/net/route").read_text().splitlines()[1:]:
            p = line.split()
            if len(p) > 3 and p[1] == "00000000" and int(p[3], 16) & 2:
                n = p[0].lower()
                if n.startswith(_MOBILE_NAMES):
                    res = False
                elif n.startswith(_WIFI_NAMES):
                    res = True
                if res is not None:
                    break
    except Exception:
        pass
    if res is None:                                         # 2) Termux:API (if installed)
        try:
            out = subprocess.run(["termux-wifi-connectioninfo"], capture_output=True, text=True, timeout=4).stdout
            j = json.loads(out or "{}")
            if j:
                res = bool(j.get("supplicant_state") == "COMPLETED" and str(j.get("ip", "0.0.0.0")) not in ("", "0.0.0.0"))
        except Exception:
            pass
    if res is None:                                         # 3) interface state
        try:
            w = Path("/sys/class/net/wlan0/operstate")
            if w.exists():
                res = w.read_text().strip() == "up"
        except Exception:
            pass
    _WIFI_CACHE[0], _WIFI_CACHE[1] = time.time(), res
    return res


def backup_block_reason(d=None):
    """"" when backup may run now, otherwise the reason it must wait (low battery / not charging / no Wi-Fi)."""
    d = d or cfg_load()
    if d.get("paused"):
        return "Backup is paused (Settings -> Pause backup) - it continues when you switch the pause off."
    pct, charging = battery()
    if d.get("charging_only") and pct is not None and not charging:
        return f"Charging only is ON and the phone is not charging (battery {pct}%) - paused, it continues when you plug in the charger."
    if d.get("pause_low_battery") and pct is not None and not charging and pct < 20:
        return f"Battery {pct}% - paused (plug in the charger or turn off 'Pause on low battery')."
    if d.get("wifi_only") and on_wifi() is False:
        return "Wi-Fi only is ON and Wi-Fi is not connected (mobile data) - paused, it continues when Wi-Fi is back."
    return ""


