EDITABLE = set(DEFAULTS) - {"vault_code"}


_cfg_cache = [None, {}]      # [(mtime_ns, size), parsed settings] - avoids re-reading the file on every call


def _cfg_read():
    try:
        st = CONFIG_FILE.stat()
        sig = (st.st_mtime_ns, st.st_size)
        if _cfg_cache[0] != sig:
            data = json.loads(sec_read(CONFIG_FILE))
            _cfg_cache[:] = [sig, data if isinstance(data, dict) else {}]
        return copy.deepcopy(_cfg_cache[1])
    except Exception:
        return {}


def _cfg_write(data):
    ensure_dirs()
    tmp = CONFIG_FILE.with_suffix(".tmp")
    sec_write(tmp, json.dumps(data, indent=2, ensure_ascii=False))
    os.replace(tmp, CONFIG_FILE)
    _cfg_cache[0] = None


def cfg_load():
    with _cfg_lock:
        d = dict(DEFAULTS)
        d.update({k: v for k, v in _cfg_read().items() if k in DEFAULTS})
        return d


def cfg_get(key):
    return cfg_load()[key]


HEX_RE = re.compile(r"^#[0-9a-fA-F]{6}$")
BG_NAME_RE = re.compile(r"^bg_[0-9a-f]{12}\.(jpg|png|webp)$")


def cfgimg(rel):
    """Disk path of a config picture: <name>.json (bg_xxx.jpg -> bg_xxx.jpg.json, avatar.jpg -> avatar.jpg.json). Other config files are unchanged."""
    rel = str(rel)
    return CONFIG_DIR / (rel + ".json") if (rel == "avatar.jpg" or BG_NAME_RE.match(rel)) else CONFIG_DIR / rel


def _migrate_cfg_images():
    """Old installs: avatar.jpg / bg_xxx.jpg in config get the ".json" ending once."""
    try:
        for p in list(CONFIG_DIR.glob("avatar.jpg")) + [x for x in CONFIG_DIR.glob("bg_*") if BG_NAME_RE.match(x.name)]:
            q = p.with_name(p.name + ".json")
            if q.exists():
                p.unlink(missing_ok=True)
            else:
                os.replace(p, q)
    except OSError:
        pass


_migrate_cfg_images()


def _clean_custom_theme(val):
    """Custom theme: accent colour, background colour, optional text colour, optional background photo."""
    val = val if isinstance(val, dict) else {}
    out = {}
    for k in ("primary", "bg", "text"):
        v = str(val.get(k, "")).strip()
        if HEX_RE.match(v):
            out[k] = v.lower()
    img = str(val.get("image", "")).strip()
    if BG_NAME_RE.match(img) and cfgimg(img).exists():
        out["image"] = img
    try:
        out["dim"] = max(0, min(90, int(val.get("dim", 45))))
    except (TypeError, ValueError):
        out["dim"] = 45
    if val.get("drag"):
        out["drag"] = True              # wallpaper pans sideways while you move between pages
    return out


def _cfg_clean(key, val):
    if key in ("strip_location", "pause_low_battery", "fast_upload", "fast_scroll", "autohide_nav", "notify_task", "auto_clear_local", "wifi_only", "charging_only", "paused", "trash_auto_delete", "group_bursts", "ocr_search", "onboarded", "daily_summary", "liquid", "lyr_tr", "lyr_show"):
        return bool(val)
    if key in ("lyr_prov", "lyr_url", "lyr_key", "lyr_model", "lyr_lang"):
        return str(val or "").strip()[:300]
    if key == "lyr_mode":
        return "manual" if val == "manual" else "auto"
    if key == "liquid_level":
        try:
            return max(0, min(100, int(val)))
        except (TypeError, ValueError):
            return 50
    if key == "theme":
        return val if val in ("system", "light", "dark", "custom") else "system"
    if key == "ui_style":
        return "classic" if val == "classic" else "modern"
    if key == "custom_theme":
        return _clean_custom_theme(val)
    if key == "view_chat":
        return str(val or "").strip()[:200]
    if key in ("bot_token", "chat_id", "api_id", "api_hash", "phone"):
        v = str(val or "").strip()
        return re.sub(r"[\s-]", "", v) if key == "phone" else v
    if key == "bot_pool":
        out, seen = [], set()
        for b in val if isinstance(val, list) else []:
            t = str((b or {}).get("token", "")).strip()
            if t and t not in seen:
                seen.add(t)
                out.append({"name": str(b.get("name", "")).strip()[:60] or "Bot", "token": t})
        return out
    if key in ("grid_cols", "haptic_level"):
        try:
            n = int(val)
        except (TypeError, ValueError):
            n = 0 if key == "grid_cols" else 2
        if key == "grid_cols":
            return n if 2 <= n <= 5 else 0
        return max(0, min(4, n))
    if key == "excluded_folders":
        out = []
        for p in val if isinstance(val, list) else []:
            p = str(p or "").strip().rstrip("/") if str(p or "").strip() != "/" else ""
            if p and p not in out:
                out.append(p[:500])
        return out[:200]
    if key == "folders":
        out, seen = [], set()
        for f in val if isinstance(val, list) else []:
            p = str((f or {}).get("path", "")).strip()
            if p and p not in seen:
                seen.add(p)
                out.append({"path": p, "enabled": bool(f.get("enabled", True))})
        return out
    if key == "profile":
        return {k: str(v)[:120] for k, v in (val or {}).items() if k in ("name", "username", "phone")}
    return val


def cfg_update(patch):
    with _cfg_lock:
        d = cfg_load()
        for k, v in (patch or {}).items():
            if k in EDITABLE:
                d[k] = _cfg_clean(k, v)
        _cfg_write(d)
    try:
        setbk_kick()                                     # the settings travel into the Telegram lock backup
    except Exception:
        pass
    return d


def cfg_set_code(code):
    with _cfg_lock:
        d = cfg_load()
        d["vault_code"] = code
        _cfg_write(d)
    try:
        setbk_kick()
    except Exception:
        pass


def cfg_restore(data):
    """Fill ONLY empty server values from the browser copy (never overwrite what the server has)."""
    with _cfg_lock:
        d = cfg_load()
        for k, v in (data or {}).items():
            if k not in DEFAULTS:
                continue
            if k == "vault_code":
                if not d["vault_code"] and isinstance(v, str) and VALID.match(v.upper()):
                    d["vault_code"] = v.upper()
            elif k in EDITABLE and not d[k] and v not in (None, "", [], {}):
                d[k] = _cfg_clean(k, v)
        _cfg_write(d)
        return d


def cfg_bots():
    """All sending bots: the primary one first, then the pool (duplicates removed)."""
    d = cfg_load()
    out, seen = [], set()
    if d["bot_token"]:
        out.append({"name": "Primary", "token": d["bot_token"]})
        seen.add(d["bot_token"])
    for b in d["bot_pool"]:
        if b["token"] not in seen:
            seen.add(b["token"])
            out.append(b)
    return out


# ============================================================================
# VAULT CODE  (was vault/vault_code.py)
# ============================================================================
# ONE vault code for the whole app.
#
# It is generated once (Settings -> Vault code) and then written under EVERY backed-up file
# (Telegram caption). Sync later searches the Telegram channel for exactly this code.

CODE_RE = re.compile(r"CODE:\s*(TV-[0-9A-Fa-f]{12})")
NAME_RE = re.compile(r"^NAME:\s*(.+)$", re.M)
HASH_RE = re.compile(r"^HASH:\s*([0-9a-fA-F]{64})\s*$", re.M)
PART_RE = re.compile(r"^PART:\s*(\d+)\s*/\s*(\d+)\s*$", re.M)
TOTAL_RE = re.compile(r"^TOTAL:\s*(\d+)\s*$", re.M)
VALID = re.compile(r"^TV-[0-9A-F]{12}$")


def vc_generate():
    return "TV-" + secrets.token_hex(6).upper()


def vc_normalize(s):
    s = re.sub(r"[^0-9A-Za-z]", "", s or "").upper()
    if s.startswith("TV"):
        s = s[2:]
    code = "TV-" + s
    return code if VALID.match(code) else None


def make_caption(code, name, sha=None, part=None, total=None):
    """Caption written under every uploaded message. Big files carry PART: i/n (+ TOTAL: size) so Sync can rebuild them."""
    lines = ["VAULT BACKUP", f"CODE: {code}"]
    if part:
        lines.append(f"PART: {part[0]}/{part[1]}")
        if total:
            lines.append(f"TOTAL: {int(total)}")
    lines.append(f"NAME: {name}")
    if sha:
        lines.append(f"HASH: {sha}")
    return "\n".join(lines)[:1024]


def parse_caption(text, code):
    """Return {name, sha, part, total} if the caption carries OUR code, else None."""
    text = text or ""
    if text.lstrip().upper().startswith("VAULT LOCK BACKUP"):      # the lock/settings backup (vault_lock.bin) is not a library file
        return None
    if re.search(r"^VT\s*\d+\s*$", text, re.M):          # thumb.jpg message (carries the file's CODE/NAME/HASH + 'VT <id>') is not a file
        return None
    m = CODE_RE.search(text)
    if not m or m.group(1).upper() != code.upper():
        return None
    n, h = NAME_RE.search(text), HASH_RE.search(text)
    p, t = PART_RE.search(text), TOTAL_RE.search(text)
    part = (int(p.group(1)), int(p.group(2))) if p and 1 <= int(p.group(1)) <= int(p.group(2)) else None
    return {"name": n.group(1).strip() if n else "", "sha": h.group(1).lower() if h else None,
            "part": part, "total": int(t.group(1)) if t else None}


# ============================================================================
# DATABASE  (was vault/database.py)
# ============================================================================
SCHEMA = """
CREATE TABLE IF NOT EXISTS files(
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL, kind TEXT NOT NULL, mime TEXT, size INTEGER NOT NULL DEFAULT 0,
  sha256 TEXT NOT NULL UNIQUE,
  source_path TEXT, cache_name TEXT, folder TEXT, mtime REAL,
  taken_at TEXT NOT NULL, added_at TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  chat_id TEXT, message_id INTEGER, bot_name TEXT, error TEXT,
  tries INTEGER NOT NULL DEFAULT 0, backed_at TEXT);
CREATE INDEX IF NOT EXISTS ix_files_status ON files(status);
CREATE INDEX IF NOT EXISTS ix_files_taken ON files(taken_at);
CREATE INDEX IF NOT EXISTS ix_files_kind ON files(kind);
CREATE TABLE IF NOT EXISTS kv(key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE IF NOT EXISTS ocr(file_id INTEGER PRIMARY KEY, text TEXT NOT NULL DEFAULT '', at TEXT);
CREATE TABLE IF NOT EXISTS parts(
  file_id INTEGER NOT NULL, idx INTEGER NOT NULL, pos INTEGER NOT NULL, plen INTEGER NOT NULL,
  message_id INTEGER, bot_name TEXT, PRIMARY KEY(file_id, idx));
"""
_db_guard = threading.Lock()
_db_ready = False


def _bk_kick():
    try:
        setbk_kick()
    except Exception:
        pass


def _db_ensure():
    """Self-healing: recreate folders + schema whenever storage/ was deleted while running."""
    global _db_ready
    if _db_ready and DB.exists():
        return
    with _db_guard:
        if not DB.exists():          # brand-new / deleted index: file ids start again from 1, so old id-named previews are stale
            for d in (THUMBS, PREVIEWS):
                shutil.rmtree(d, ignore_errors=True)
        ensure_dirs()
        con = sqlite3.connect(DB, timeout=30)
        try:
            try:
                con.execute("PRAGMA journal_mode=WAL")     # many bot threads write at once: readers never block writers
            except sqlite3.OperationalError:
                pass
            con.executescript(SCHEMA)
            for _col in ("locked INTEGER NOT NULL DEFAULT 0", "skip INTEGER NOT NULL DEFAULT 0", "thumb_file_id TEXT", "thumb_message_id INTEGER", "trashed_at TEXT", "fav INTEGER NOT NULL DEFAULT 0", "uploader TEXT", "rot INTEGER NOT NULL DEFAULT 0"):
                try:
                    con.execute("ALTER TABLE files ADD COLUMN " + _col)
                except sqlite3.OperationalError:
                    pass
            con.commit()
        finally:
            con.close()
        _db_ready = True


@contextmanager
def db():
    _db_ensure()
    con = sqlite3.connect(DB, timeout=30)
    con.row_factory = sqlite3.Row
    try:
        con.execute("PRAGMA synchronous=NORMAL")      # WAL + NORMAL: far fewer fsyncs (big win on phone storage), still crash-safe
        con.execute("PRAGMA temp_store=MEMORY")
        con.execute("PRAGMA cache_size=-8192")        # 8 MB page cache per connection
        yield con
        con.commit()
    except Exception:
        con.rollback()
        raise
    finally:
        con.close()


def kv_get(key, default=None):
    with db() as c:
        r = c.execute("SELECT value FROM kv WHERE key=?", (key,)).fetchone()
    return r["value"] if r else default


def kv_set(key, value):
    with db() as c:
        c.execute("INSERT INTO kv(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                  (key, str(value)))


# ============================================================================
# TELEGRAM BOT API  (was vault/telegram_api.py)
# ============================================================================
# Telegram Bot API (uploads). Plain http.client, streamed multipart: low memory on phones.


class TgRetry(RuntimeError):
    def __init__(self, msg, retry_after):
        super().__init__(msg)
        self.retry_after = retry_after


def tgapi_call(token, method, fields=None, file_path=None, upload_name=None, timeout=90, progress=None, job=None, file_range=None):
    path = f"/bot{token}/{method}"
    job_check(job)
    conn = http.client.HTTPSConnection("api.telegram.org", timeout=timeout)
    io_add(job, "conns", conn)
    try:
        if file_path:
            p = Path(file_path)
            off, length = file_range if file_range else (0, p.stat().st_size)     # (offset, bytes): one PART of a big file
            boundary = "----VaultBoundary" + os.urandom(12).hex()
            head = bytearray()
            for k, v in (fields or {}).items():
                head += f'--{boundary}\r\nContent-Disposition: form-data; name="{k}"\r\n\r\n{v}\r\n'.encode("utf-8")
            fname = (upload_name or p.name).replace('"', "'").replace("\r", " ").replace("\n", " ")
            mime = mimetypes.guess_type(fname)[0] or "application/octet-stream"
            head += (f'--{boundary}\r\nContent-Disposition: form-data; name="document"; filename="{fname}"\r\n'
                     f'Content-Type: {mime}\r\n\r\n').encode("utf-8")
            tail = f"\r\n--{boundary}--\r\n".encode()
            conn.putrequest("POST", path)
            conn.putheader("Content-Type", f"multipart/form-data; boundary={boundary}")
            conn.putheader("Content-Length", str(len(head) + length + len(tail)))
            conn.endheaders()
            conn.send(bytes(head))
            with open(p, "rb") as fh:                      # read straight from the original file: no temp copy of the part
                fh.seek(off)
                left = length
                while left > 0:
                    chunk = fh.read(min(512 * 1024, left))
                    if not chunk:
                        raise RuntimeError("The file changed while it was being uploaded")
                    conn.send(chunk)
                    left -= len(chunk)
                    if progress:
                        progress(len(chunk))
            conn.send(tail)
        else:
            conn.request("POST", path, json.dumps(fields or {}).encode(), {"Content-Type": "application/json"})
        resp = conn.getresponse()
        raw = resp.read()
    except (OSError, http.client.HTTPException) as e:
        job_check(job)                                       # cut by Stop -> report "stopped", not a network error
        raise RuntimeError("Network error: " + str(e).replace(token, "***"))
    finally:
        io_del(job, "conns", conn)
        conn.close()
    try:
        data = json.loads(raw.decode("utf-8", "replace"))
    except ValueError:
        raise RuntimeError(f"Telegram HTTP {resp.status}: {raw[:200].decode('utf-8', 'replace')}")
    if data.get("ok"):
        return data["result"]
    desc = data.get("description", "Telegram API error")
    retry = (data.get("parameters") or {}).get("retry_after")
    if retry:
        raise TgRetry(desc, int(retry))
    raise RuntimeError(f"Telegram: {desc} (HTTP {resp.status})")


def tgapi_verify(token, chat_id):
    """Check token, chat access and admin rights. Returns (ok, message, info)."""
    me = tgapi_call(token, "getMe")
    chat = tgapi_call(token, "getChat", {"chat_id": chat_id})
    title = chat.get("title") or chat.get("username") or str(chat_id)
    note = ""
    try:
        m = tgapi_call(token, "getChatMember", {"chat_id": chat_id, "user_id": me["id"]})
        if chat.get("type") == "channel" and m.get("status") not in ("administrator", "creator"):
            note = " (warning: add this bot as channel ADMIN with 'Post messages')"
    except RuntimeError:
        pass
    return f"Connected - @{me.get('username', 'bot')} -> {title}{note}", {"username": me.get("username"), "title": title}


# ============================================================================
# JOBS  (was vault/jobs.py)
# ============================================================================
# Background job queue: exactly one job runs at a time (safe for Telegram rate limits).

JOBS, LOCK, TASKS, _seq = {}, threading.Lock(), queue.Queue(), [0]


class Cancelled(Exception):
    pass


class FileCancelled(Exception):
    """Only ONE file's upload was cancelled by the user (the rest of the backup continues)."""


def job_log(job, msg):
    if job is None:
        return
    with LOCK:
        job["log"].append(str(msg))
        del job["log"][:-300]


def job_pct(job, start, end, p):
    """REAL overall progress of a job: this phase owns start..end percent of the bar, p (0-100) is how far the phase is."""
    if job is None:
        return
    v = start + (end - start) * max(0.0, min(100.0, float(p))) / 100.0
    with LOCK:
        job["pct"] = round(max(job.get("pct") or 0, v), 1)       # never goes backwards


def job_check(job):
    if job and job.get("cancel"):
        raise Cancelled()


def job_nap(job, secs):
    """Sleep that ends the moment the job is stopped (raises Cancelled)."""
    end = time.time() + secs
    while time.time() < end:
        job_check(job)
        time.sleep(min(0.2, max(0.0, end - time.time())))


# network handles (open sockets / Telethon futures) of running jobs, so Stop can cut them instantly
JOB_IO, _IO = {}, threading.Lock()


def io_add(job, kind, obj):
    if job is not None:
        with _IO:
            JOB_IO.setdefault(job["id"], {"conns": set(), "futs": set()})[kind].add(obj)


def io_del(job, kind, obj):
    if job is not None:
        with _IO:
            JOB_IO.get(job["id"], {}).get(kind, set()).discard(obj)


def job_abort_io(jid):
    with _IO:
        h = JOB_IO.get(jid) or {}
        conns, futs = list(h.get("conns", ())), list(h.get("futs", ()))
    for c in conns:
        try:
            if c.sock:
                c.sock.shutdown(socket.SHUT_RDWR)          # the blocked send/receive fails at once
        except Exception:
            pass
    for f in futs:
        f.cancel()                                          # Telethon upload / scan / download


def job_submit(kind, label, fn, *args):
    """Queue a job. If the same kind is already queued/running, return that one (no duplicates)."""
    with LOCK:
        for j in JOBS.values():
            if j["kind"] == kind and j["status"] in ("queued", "running") and j["label"] == label:
                return j
        _seq[0] += 1
        job = {"id": _seq[0], "kind": kind, "label": label, "status": "queued", "done": 0, "total": 0, "pct": 0,
               "log": [], "live": None, "error": None, "result": None, "cancel": False, "created": now(), "finished": None}
        JOBS[job["id"]] = job
        for jid in sorted(JOBS)[:-60]:
            if JOBS[jid]["status"] in ("done", "error", "cancelled"):
                del JOBS[jid]
    TASKS.put((job, fn, args))
    return job


def _worker():
    while True:
        job, fn, args = TASKS.get()
        if job["cancel"]:
            job["status"] = "cancelled"
            job["finished"] = now()
            TASKS.task_done()
            continue
        job["status"] = "running"
        try:
            fn(job, *args)
            job["status"] = "error" if job["error"] else "done"
            if job["error"]:
                log_problem("Job", f"{job.get('label') or job.get('title') or job.get('kind') or 'job'}: {job['error']}")
        except Cancelled:
            job["status"] = "cancelled"
            job_log(job, "Stopped.")
        except Exception as e:
            job["error"] = job["error"] or str(e)
            log_problem("Job", f"{job.get('label') or job.get('title') or job.get('kind') or 'job'}: {e}")
            job_log(job, f"ERROR: {e}")
            job["status"] = "error"
        finally:
            job["finished"] = now()
            with _IO:
                JOB_IO.pop(job["id"], None)
            TASKS.task_done()


def job_start():
    threading.Thread(target=_worker, daemon=True, name="vault-worker").start()


def job_get(job_id):
    with LOCK:
        j = JOBS.get(job_id)
        if not j:
            return None
        live = json.loads(json.dumps(j.get("live")))
        if live:
            w = live.pop("_w", None)
            if w and time.time() - w[-1][0] > 4:
                live["speed"] = 0
        return dict(j, log=list(j["log"][-120:]), live=live)


def job_active():
    with LOCK:
        run = next((j for j in JOBS.values() if j["status"] == "running"), None)
        queued = [j for j in JOBS.values() if j["status"] == "queued"]
        if not run and not queued:
            return None
        j = run or queued[0]
        return {"id": j["id"], "kind": j["kind"], "label": j["label"], "status": j["status"],
                "done": j["done"], "total": j["total"], "pct": j.get("pct", 0), "queued": len(queued)}


def job_cancel_slot(job_id, key):
    """Cancel just one running upload (the 'x' next to it). Returns True if that upload was found."""
    with LOCK:
        j = JOBS.get(job_id)
        slot = ((j or {}).get("live") or {}).get("active", {}).get(str(key))
        if not slot:
            return False
        slot["cancel"] = True
    return True                                  # the upload stops at its next chunk (<= 256 KB)


def job_cancel(job_id):
    with LOCK:
        j = JOBS.get(job_id)
        if j and j["status"] in ("queued", "running"):
            j["cancel"] = True
            running = j["status"] == "running"
            j["status"], j["finished"] = "cancelled", now()      # show "stopped" right now; the threads wind down in the background
        else:
            return False
    if running:
        job_abort_io(job_id)
    return True


# ============================================================================
# TELETHON SERVICE  (was vault/telethon_service.py)
# ============================================================================
# Telethon = your own Telegram account. Needed for: login/profile, searching the channel history by
# vault code (Sync / recovery), downloading files back and uploading files larger than 50 MB.

try:
    from telethon import TelegramClient
    from telethon.errors import SessionPasswordNeededError
    TL_HAVE = True
    TL_IMPORT_ERROR = ""
except Exception as _e:                      # noqa
    TL_HAVE, TL_IMPORT_ERROR = False, str(_e)

_st = {"loop": None, "client": None, "client_key": None, "hash": {}, "ok": False, "t": 0.0}
BIG_BUSY = [0]                                   # >0 while a big Telegram-account transfer is running (keeps the main connection free)


def cryptg_active():
    """True when Telethon really uses the fast AES (cryptg). Without it every upload part is encrypted in pure Python
    on one CPU core - that is what makes account uploads crawl at ~100-300 KB/s (typical on phones / Termux)."""
    try:
        import telethon.crypto.aes as _aes
        return getattr(_aes, "cryptg", None) is not None
    except Exception:
        return False
_tl_guard = threading.Lock()
DL_SEM = threading.BoundedSemaphore(4)


def _loop():
    with _tl_guard:
        if _st["loop"] is None:
            loop = asyncio.new_event_loop()
            threading.Thread(target=lambda: (asyncio.set_event_loop(loop), loop.run_forever()),
                             daemon=True, name="telethon-loop").start()
            _st["loop"] = loop
        return _st["loop"]


def tl_run(coro, timeout=60, job=None):
    if not TL_HAVE:
        coro.close()
        raise RuntimeError("Telethon is not installed. Run: pip install telethon  (then restart run.py)")
    if job is not None and job.get("cancel"):
        coro.close()
        raise Cancelled()
    fut = asyncio.run_coroutine_threadsafe(coro, _loop())
    io_add(job, "futs", fut)
    try:
        return fut.result(timeout)
    except concurrent.futures.TimeoutError:
        fut.cancel()
        raise RuntimeError("Telegram did not respond in time (check the internet connection).")
    except concurrent.futures.CancelledError:
        raise Cancelled()
    finally:
        io_del(job, "futs", fut)


def tl_creds():
    d = cfg_load()
    aid = os.environ.get("VAULT_API_ID") or d["api_id"]
    ah = os.environ.get("VAULT_API_HASH") or d["api_hash"]
    try:
        return (int(aid), ah) if aid and ah else None
    except ValueError:
        return None


async def _client():
    cr = tl_creds()
    if not cr:
        raise RuntimeError("API ID / API hash are not set (Settings -> Telegram account).")
    if _st["client"] is not None and _st["client_key"] != cr:
        await _drop()
    if _st["client"] is None:
        ensure_dirs()
        _st["client"] = TelegramClient(str(SESSION), cr[0], cr[1], connection_retries=3, retry_delay=2,
                                       request_retries=3, timeout=30, flood_sleep_threshold=120)
        _st["client_key"] = cr
    if not _st["client"].is_connected():
        await _st["client"].connect()
    return _st["client"]


async def _drop():
    c, _st["client"] = _st["client"], None
    if c is not None:
        try:
            await c.disconnect()
        except Exception:
            pass


async def _is_auth():
    return await (await _client()).is_user_authorized()


def tl_ready(force=False):
    """Installed + configured + logged in (cached for 30 s)."""
    if not TL_HAVE or not tl_creds():
        return False
    if not force and time.time() - _st["t"] < 30:
        return _st["ok"]
    if not force and BIG_BUSY[0] and _st["t"]:
        return _st["ok"]                          # big upload running: never queue a check behind it, trust the last answer
    try:
        ok = bool(tl_run(_is_auth(), 6 if BIG_BUSY[0] else 25))
    except Exception:
        ok = False
    _st["ok"], _st["t"] = ok, time.time()
    return ok


def tl_mark(ok):
    _st["ok"], _st["t"] = ok, time.time()


# ── login ────────────────────────────────────────────────────────────────
async def _send_code(phone):
    c = await _client()
    if await c.is_user_authorized():
        return "already"
    sent = await c.send_code_request(phone)
    _st["hash"][phone] = sent.phone_code_hash
    return "sent"


async def _sign_in(phone, code, password):
    c = await _client()
    try:
        await c.sign_in(phone=phone, code=code, phone_code_hash=_st["hash"].get(phone))
    except SessionPasswordNeededError:
        if not password:
            return "password"
        await c.sign_in(password=password)
    return "ok"


async def _logout():
    c = await _client()
    try:
        await c.log_out()
    finally:
        _st["client"] = None


async def _profile():
    c = await _client()
    me = await c.get_me()
    name = " ".join(x for x in (me.first_name, me.last_name) if x) or (me.username or str(me.id))
    try:
        await c.download_profile_photo("me", file=str(AVATAR))
    except Exception:
        pass
    return {"name": name, "username": me.username or "", "phone": ("+" + me.phone) if me.phone else ""}


def tl_send_code(phone):
    r = tl_run(_send_code(phone), 40)
    tl_mark(r == "already")
    return r


def tl_sign_in(phone, code, password=None):
    r = tl_run(_sign_in(phone, code, password), 40)
    if r == "ok":
        tl_mark(True)
    return r


def tl_logout():
    try:
        tl_run(_logout(), 20)
    except Exception:
        pass
    tl_mark(False)
    for p in (SESSION.with_suffix(".session"), SESSION.with_suffix(".session-journal"), AVATAR):
        try:
            p.unlink()
        except OSError:
            pass


def tl_profile():
    return tl_run(_profile(), 40)


# ── chat access ──────────────────────────────────────────────────────────
async def _entity(c, chat_id):
    key = str(chat_id).strip()
    try:
        key = int(key)
    except ValueError:
        key = re.sub(r"^https?://t\.me/", "", key)
    try:
        return await c.get_entity(key)
    except Exception:
        await c.get_dialogs()
        try:
            return await c.get_entity(key)
        except Exception as e:
            raise RuntimeError(f"The logged-in Telegram account cannot see chat {chat_id}. "
                               f"Join that channel/group with this same account. ({e})")


SCAN_PAR = max(1, min(24, int(os.environ.get("VAULT_SCAN_PAR", "12"))))       # parallel history readers for Sync / Full scan


async def _scan(chat_id, code, min_id, progress, search=True, pct=None):
    """Walk the channel history and collect every media message whose caption carries OUR code.
    FAST: no 1-second pause between pages (wait_time=0) and the id range is cut into SCAN_PAR slices
    that are read at the same time."""
    c = await _client()
    ent = await _entity(c, chat_id)
    min_id = int(min_id or 0)
    out, seen, top = [], [0], [min_id]
    # search=True: the logged-in account asks Telegram to find OUR code on the server side, so only the messages that carry the
    # code are sent to this phone (no thumb.jpg messages, no other chatter) = far fewer MB and far faster.
    # search=False: every single message of the channel is read (VAULT_FULL_WALK=1, slow, uses many MB).
    kw = {"search": code[3:] if code.upper().startswith("TV-") else code} if search else {}

    covered = {}                                             # slice -> how many ids of it were already passed (REAL progress)

    def _cover(lo, hi, mid):
        if not pct:
            return
        top_id = hi or newest
        width = max(top_id - lo, 1)
        covered[(lo, hi)] = max(covered.get((lo, hi), 0), min(width, max(0, top_id - mid)))
        pct(min(99.0, sum(covered.values()) * 100.0 / max(span, 1)))

    async def walk(lo, hi):                                  # ids strictly between lo and hi (hi=0 -> no upper limit)
        async for m in c.iter_messages(ent, min_id=lo, max_id=hi, limit=None, wait_time=0, **kw):
            seen[0] += 1
            top[0] = max(top[0], m.id)
            _cover(lo, hi, m.id)
            if progress and seen[0] % 300 == 0:
                progress(seen[0])
            if not (getattr(m, "document", None) or getattr(m, "photo", None)):
                continue
            info = parse_caption(m.message, code)
            if not info:
                continue
            f = m.file
            info.update(message_id=m.id, date=m.date.astimezone().isoformat(timespec="seconds"),
                        size=int(getattr(f, "size", 0) or 0) if f else 0, mime=(f.mime_type if f else None))
            if not info["name"]:
                info["name"] = (f.name if f and f.name else f"photo_{m.id}.jpg")
            out.append(info)

    last = await c.get_messages(ent, limit=1)
    newest = last[0].id if last else 0
    span = max(newest - min_id, 1)
    if search:
        top[0] = max(top[0], newest)                         # a search only sees matches, so the next sync starts after the newest message
    span = max(newest - min_id, 1)
    if SCAN_PAR <= 1 or span < 2000:
        await walk(min_id, 0)
    else:
        step = -(-span // SCAN_PAR)
        slices = [(min_id + k * step, min_id + (k + 1) * step + 1) for k in range(SCAN_PAR)]
        slices[-1] = (slices[-1][0], 0)                      # last slice has no upper limit (new messages while scanning)
        await asyncio.gather(*(walk(lo, hi) for lo, hi in slices))
    if pct:
        pct(100.0)
    out.sort(key=lambda i: i["message_id"], reverse=True)    # newest first, like before
    return out, top[0], seen[0]


def tl_scan(chat_id, code, min_id=0, progress=None, job=None, search=True, pct=None):
    return tl_run(_scan(chat_id, code, min_id, progress, search, pct), 3600, job)


BIG_DL = 10 * 1024 * 1024                                       # files above this are pulled in several parallel streams
DL_STREAMS = max(1, min(16, int(os.environ.get("VAULT_DL_STREAMS", "8"))))


ACC_CONNS = max(1, min(12, int(os.environ.get("VAULT_ACCOUNT_CONNS", "6"))))     # extra Telegram connections for ONE big transfer
ACC_INFLIGHT = max(2, min(16, int(os.environ.get("VAULT_ACCOUNT_INFLIGHT", "6"))))  # requests in flight on each connection


async def _borrow(c, dc_id, n):
    """Extra MTProto connections to the same data centre (each one adds its own speed). Failures are ignored."""
    out = []
    for _ in range(n):
        try:
            out.append(await c._borrow_exported_sender(dc_id))
        except Exception:
            break
    return out


async def _give_back(c, senders):
    for s_ in senders:
        try:
            await c._return_exported_sender(s_)
        except Exception:
            pass


async def _download_fast(c, m, dest, size, progress=None):
    """MB/s download: 1 MB requests, many connections, many requests in flight at once, written straight to disk."""
    from telethon import utils
    from telethon.tl.functions.upload import GetFileRequest
    got = utils.get_input_location(m.document)
    dc_id, loc = got if isinstance(got, tuple) else (getattr(m.document, "dc_id", None), got)
    RS = 1024 * 1024
    n = -(-size // RS)
    callers = []
    if dc_id is None or dc_id == c.session.dc_id:
        callers.append(lambda r: c(r))
    senders = await _borrow(c, dc_id or c.session.dc_id, ACC_CONNS)
    callers += [(lambda r, s_=s_: c._call(s_, r)) for s_ in senders]
    if not callers:
        raise RuntimeError("no connection for fast download")
    todo = asyncio.Queue()
    for i in range(n):
        todo.put_nowait(i)
    done = [0]
    f = open(dest, "wb")
    try:
        f.truncate(size)

        async def worker(call):
            while True:
                try:
                    i = todo.get_nowait()
                except asyncio.QueueEmpty:
                    return
                off = i * RS
                want = min(RS, size - off)
                for attempt in range(4):
                    try:
                        r = await call(GetFileRequest(loc, offset=off, limit=RS))
                        data = r.bytes
                        if len(data) < want:
                            raise RuntimeError("short block")
                        break
                    except Exception:
                        if attempt == 3:
                            raise
                        await asyncio.sleep(1 + attempt)
                f.seek(off)
                f.write(data[:want])
                done[0] += want
                if progress:
                    progress(done[0], size)
        tasks = [asyncio.ensure_future(worker(cl)) for cl in callers for _ in range(ACC_INFLIGHT)]
        try:
            await asyncio.gather(*tasks)
        except BaseException:
            for t in tasks:
                t.cancel()
            raise
    finally:
        f.close()
        await _give_back(c, senders)
    if done[0] != size:
        raise RuntimeError(f"Download incomplete ({done[0]} of {size} bytes)")
    return str(dest)


async def _download_big(c, m, dest, size, progress=None):
    try:
        return await _download_fast(c, m, dest, size, progress)
    except Exception:                                              # anything unusual: the older, safe method below
        Path(dest).unlink(missing_ok=True)
    return await _download_big_old(c, m, dest, size)


async def _download_big_old(c, m, dest, size):
    """Own account, one file split in DL_STREAMS ranges that download at the same time (512 KB requests)."""
    RS = 512 * 1024
    total_req = -(-size // RS)
    per = -(-total_req // DL_STREAMS)
    written = [0]
    with open(dest, "wb") as f:
        f.truncate(size)

    async def part(i):
        first = i * per
        n = min(per, total_req - first)
        if n <= 0:
            return
        off = first * RS
        with open(dest, "r+b") as f:
            async for chunk in c.iter_download(m.document, offset=off, limit=n, request_size=RS, file_size=size):
                f.seek(off)
                f.write(chunk)
                off += len(chunk)
                written[0] += len(chunk)
    await asyncio.gather(*(part(i) for i in range(DL_STREAMS)))
    if written[0] != size:
        raise RuntimeError(f"Download incomplete ({written[0]} of {size} bytes) - try again")
    return str(dest)


async def _download(chat_id, mid, dest, thumb=None, progress=None):
    c = await _client()
    ent = await _entity(c, chat_id)
    m = await c.get_messages(ent, ids=int(mid))
    if not m or not (getattr(m, "document", None) or getattr(m, "photo", None)):
        raise RuntimeError("That Telegram message no longer exists in the channel.")
    if thumb is None and getattr(m, "document", None) and int(getattr(m.file, "size", 0) or 0) > BIG_DL:
        return await _download_big(c, m, dest, int(m.file.size), progress)
    out = await (c.download_media(m, file=str(dest), thumb=thumb) if thumb is not None
                 else c.download_media(m, file=str(dest), progress_callback=progress))
    if not out:
        raise RuntimeError("Telegram returned no data.")
    return str(out)


def tl_download(chat_id, mid, dest, thumb=None, timeout=3600, job=None, progress=None):
    dest = Path(dest)
    part = dest.with_name(dest.name + ".part")
    part.unlink(missing_ok=True)
    with DL_SEM:
        got = Path(tl_run(_download(chat_id, mid, part, thumb, progress), timeout, job))
    os.replace(got, dest)


async def _upload_fast(c, path, progress, name):
    """MB/s upload: 512 KB parts, many connections, many parts in flight at once. Returns an InputFileBig."""
    from telethon.tl.functions.upload import SaveBigFilePartRequest
    from telethon.tl.types import InputFileBig
    size = os.path.getsize(path)
    RS = 512 * 1024
    n = -(-size // RS)
    if n > 8000:
        raise RuntimeError("File is too big for Telegram (max 4 GB with Premium, 2 GB without).")
    fid = int.from_bytes(os.urandom(8), "big", signed=True)
    senders = await _borrow(c, c.session.dc_id, ACC_CONNS)
    # Own connections only: the main one stays free so thumbnails / login checks / downloads are not stuck behind big parts.
    callers = [(lambda r, s_=s_: c._call(s_, r)) for s_ in senders] or [lambda r: c(r)]
    todo = asyncio.Queue()
    for i in range(n):
        todo.put_nowait(i)
    f = open(path, "rb")
    try:
        async def worker(call):
            while True:
                try:
                    i = todo.get_nowait()
                except asyncio.QueueEmpty:
                    return
                f.seek(i * RS)
                data = f.read(RS)
                if not data:
                    raise RuntimeError("The file changed while it was being uploaded")
                for attempt in range(4):
                    try:
                        ok = await call(SaveBigFilePartRequest(file_id=fid, file_part=i, file_total_parts=n, bytes=data))
                        if not ok:
                            raise RuntimeError("Telegram refused a part")
                        break
                    except Exception:
                        if attempt == 3:
                            raise
                        await asyncio.sleep(1 + attempt)
                if progress:
                    progress(len(data))
                await asyncio.sleep(0)            # let other Telegram work (thumbnails) run between parts
        tasks = [asyncio.ensure_future(worker(cl)) for cl in callers for _ in range(ACC_INFLIGHT)]
        try:
            await asyncio.gather(*tasks)
        except BaseException:
            for t in tasks:
                t.cancel()
            raise
    finally:
        f.close()
        await _give_back(c, senders)
    return InputFileBig(id=fid, parts=n, name=name)


async def _send_big(chat_id, path, name, caption, progress=None):
    from telethon.tl.types import DocumentAttributeFilename
    c = await _client()
    ent = await _entity(c, chat_id)
    try:
        from telethon.tl.types import InputMediaUploadedDocument
        from telethon.errors import RPCError
        big = await _upload_fast(c, path, progress, name)
        mime = mimetypes.guess_type(name)[0] or "application/octet-stream"
        media = InputMediaUploadedDocument(file=big, mime_type=mime, attributes=[DocumentAttributeFilename(name)], force_file=True)
        msg = await c.send_file(ent, media, caption=caption)
        return msg.id
    except Exception as e:
        if "Cancelled" in type(e).__name__ or isinstance(e, (Cancelled, FileCancelled)):
            raise
    last = [0]

    def cb(cur, tot):
        if progress:
            progress(cur - last[0])
        last[0] = cur
    msg = await c.send_file(ent, str(path), caption=caption, force_document=True,
                            attributes=[DocumentAttributeFilename(name)], progress_callback=cb, part_size_kb=512)
    return msg.id


def tl_send_big(chat_id, path, name, caption, progress=None, job=None):
    BIG_BUSY[0] += 1
    try:
        return tl_run(_send_big(chat_id, path, name, caption, progress), 7200, job)
    finally:
        BIG_BUSY[0] = max(0, BIG_BUSY[0] - 1)


async def _delete_msgs(chat_id, ids):
    c = await _client()
    ent = await _entity(c, chat_id)
    await c.delete_messages(ent, [int(i) for i in ids])


def tl_delete(chat_id, ids):
    return tl_run(_delete_msgs(chat_id, ids), 120)


async def _msg_exists(chat_id, mid):
    c = await _client()
    ent = await _entity(c, chat_id)
    m = await c.get_messages(ent, ids=int(mid))
    return m is not None and type(m).__name__ != "MessageEmpty" and bool(getattr(m, "id", 0))


def tl_exists(chat_id, mid):
    """True / False = the message is still / no longer in the chat (asked through the logged-in account)."""
    return tl_run(_msg_exists(chat_id, mid), 60)


async def _find_thumb_msgs(chat_id, mids, span=30):
    """Finds the 'thumb.jpg' messages (caption 'VT <file message id>') that sit right after the given file messages.
    Used when the library does not know a thumbnail's message id (synced / older files): they are deleted together with the file."""
    c = await _client()
    ent = await _entity(c, chat_id)
    want = {int(m) for m in mids}
    cand = set()
    for m in want:
        cand.update(range(m + 1, m + 1 + span))
    ids = sorted(cand - want)
    out = {}
    for i in range(0, len(ids), 100):
        try:
            msgs = await c.get_messages(ent, ids=ids[i:i + 100])
        except Exception:
            continue
        for m in msgs or []:
            if not m or type(m).__name__ == "MessageEmpty" or not getattr(m, "id", 0):
                continue
            mt = re.search(r"VT\s*(\d+)", getattr(m, "message", "") or "")
            if mt and int(mt.group(1)) in want:
                out.setdefault(int(mt.group(1)), []).append(int(m.id))
    return out


def tl_find_thumbs(chat_id, mids):
    return tl_run(_find_thumb_msgs(chat_id, mids), 180)


async def _purge_msgs(chat_id, ids):
    """FAST path: the logged-in account deletes up to 100 messages per request, then ONE call checks which survived."""
    c = await _client()
    ent = await _entity(c, chat_id)
    ids = [int(i) for i in ids]
    left = set()
    for i in range(0, len(ids), 100):
        chunk = ids[i:i + 100]
        try:
            await c.delete_messages(ent, chunk)
        except Exception:
            pass                                          # leftovers are caught by the check below
        try:
            got = await c.get_messages(ent, ids=chunk)
            for mid, m in zip(chunk, got):
                if m is not None and type(m).__name__ != "MessageEmpty" and bool(getattr(m, "id", 0)):
                    left.add(mid)
        except Exception:
            left.update(chunk)
    return left


def tl_purge(chat_id, ids):
    """Returns the set of message ids that are STILL in the chat after the batch delete."""
    return tl_run(_purge_msgs(chat_id, ids), 600)


# ============================================================================
# FILES  (was vault/files.py)
# ============================================================================
# File records: JSON shape, local copy lookup, thumbnails, restore-from-Telegram.

_locks, _files_guard = {}, threading.Lock()


def local_path(row):
    """A usable local copy (original location first, then our cache) or None."""
    sp = row["source_path"]
    if sp and Path(sp).is_file():
        return Path(sp)
    if row["cache_name"]:
        p = CACHE / row["cache_name"]
        if p.is_file():
            return p
    return None


def thumb_path(fid):
    return THUMBS / f"{fid}.jpg"


ORPHAN_PFX = "cloud:orphanthumb:"


def _thumb_missing(row):
    """Backed-up photo / video / apk that has no thumb.jpg message in Telegram (viewer Options -> 'Restore thumbnail')."""
    try:
        return bool(row["status"] == "backed_up" and not row["thumb_message_id"] and row["message_id"] and not row["trashed_at"]
                    and not str(row["sha256"]).startswith(ORPHAN_PFX)
                    and (row["kind"] in ("image", "video") or str(row["name"]).lower().endswith(".apk")))
    except Exception:
        return False


def _thumb_restorable(row):
    """EVERY backed-up photo / video / apk can get its thumbnail rebuilt and posted again (viewer 'Restore thumbnail'), even if one exists."""
    try:
        return bool(row["status"] == "backed_up" and row["message_id"] and not row["trashed_at"]
                    and not str(row["sha256"]).startswith(ORPHAN_PFX)
                    and (row["kind"] in ("image", "video") or str(row["name"]).lower().endswith(".apk")))
    except Exception:
        return False


def _is_orphan(row):
    """Thumbnail is in Telegram but the real file was never uploaded (no local copy either): waits in Pending as 'File is not available'."""
    try:
        return (str(row["sha256"]).startswith(ORPHAN_PFX) and not row["source_path"] and not row["cache_name"]
                and row["status"] == "pending" and not row["trashed_at"])
    except Exception:
        return False


TEMP_CACHE = {}      # file id -> time it was pulled back from Telegram (cleaned after 30 min)


def cache_janitor():
    while True:
        time.sleep(60)
        try:
            stream_prune()
        except Exception:
            pass
        try:
            for fid, t in list(TEMP_CACHE.items()):
                if time.time() - t < 1800:
                    continue
                TEMP_CACHE.pop(fid, None)
                with db() as c:
                    r = c.execute("SELECT cache_name, source_path FROM files WHERE id=? AND status='backed_up'", (fid,)).fetchone()
                    if r and r["cache_name"] and not (r["source_path"] and Path(r["source_path"]).is_file()):
                        (CACHE / r["cache_name"]).unlink(missing_ok=True)
                        c.execute("UPDATE files SET cache_name=NULL WHERE id=?", (fid,))
        except Exception:
            pass


def preview_path(fid):
    return PREVIEWS / f"{fid}.jpg"


def _rot_of(row):
    """Saved rotation of a picture (0 / 90 / 180 / 270, clockwise). Only the app's pictures are turned - the original file is never touched."""
    try:
        return int(row["rot"] or 0) % 360
    except (KeyError, IndexError, TypeError, ValueError):
        return 0


def rot_image(src, fid, tag, rot, maxpx=0):
    """The thumbnail / preview turned by the saved rotation (cached as previews/rot<id>_<tag>_<deg>.jpg). Falls back to the unturned picture."""
    rot = int(rot or 0) % 360
    if not rot:
        return src
    out = PREVIEWS / f"rot{fid}_{tag}_{rot}.jpg"
    try:
        if out.exists() and out.stat().st_mtime >= Path(src).stat().st_mtime:
            return out
        from PIL import Image, ImageOps
        ensure_dirs()
        with Image.open(src) as im:
            im = ImageOps.exif_transpose(im)
            if maxpx:
                im.thumbnail((maxpx, maxpx))
            im = im.rotate(-rot, expand=True)          # Pillow turns counter-clockwise, our saved value is clockwise
            tmp = out.with_suffix(".tmp.jpg")
            im.convert("RGB").save(tmp, "JPEG", quality=75, optimize=True)
            os.replace(tmp, out)
        return out
    except Exception:
        return src


def make_preview(row):
    # Medium size (max 1600px) cached picture for the viewer. Cloud-only files are downloaded to tmp, shrunk, tmp deleted.
    out = preview_path(row["id"])
    if out.exists():
        return out
    ensure_dirs()
    src, tmp = local_path(row), None
    try:
        if not src:
            if not (row["chat_id"] and row["message_id"]) or not tl_ready() or done_parts(row):
                return None
            tmp = TMP / f"pv_{row['id']}_{time.time_ns()}{Path(row['name']).suffix}"
            tl_download(row["chat_id"], row["message_id"], tmp)
            src = tmp
        try:
            from PIL import Image, ImageOps
            with Image.open(src) as im:
                im = ImageOps.exif_transpose(im)
                im.thumbnail((1080, 1080))
                im.convert("RGB").save(out, "JPEG", quality=62, optimize=True, progressive=True)
        except Exception:               # no Pillow, or Pillow cannot read it (HEIC): ffmpeg / libheif tools
            out.unlink(missing_ok=True)
            ok = bool(shutil.which("ffmpeg") and subprocess.run(
                ["ffmpeg", "-y", "-loglevel", "error", "-i", str(src), "-frames:v", "1",
                 "-vf", "scale='min(1080,iw)':-2", "-q:v", "5", "-f", "image2", str(out)],
                timeout=60).returncode == 0 and out.exists() and out.stat().st_size > 0)
            if not ok and Path(row["name"]).suffix.lower() in (".heic", ".heif"):
                out.unlink(missing_ok=True)
                ok = _heic_cli(src, out)       # full-size JPEG is fine for the viewer
            if not ok:
                out.unlink(missing_ok=True)
                return None
        return out
    except Exception:
        out.unlink(missing_ok=True)
        return None
    finally:
        if tmp:
            tmp.unlink(missing_ok=True)


TRASH_DAYS = 30


def _friendly_error(err):
    """Short plain-language reason for a failed upload (flood wait, size, network ...). The raw message is shown next to it."""
    e = str(err or "")
    if not e:
        return ""
    l = e.lower()
    m = re.search(r"retry after (\d+)", l) or re.search(r"flood\w*\D{0,20}(\d+)", l)
    if "too many requests" in l or "flood" in l or "retry after" in l:
        return "Telegram rate limit (flood wait" + (f" {m.group(1)} s" if m else "") + ") - it retries by itself"
    if any(x in l for x in ("too large", "too big", "413", "file_too_big")):
        return "File is too big for Telegram"
    if any(x in l for x in ("network error", "timed out", "timeout", "connection", "ssl", "name or service", "unreachable", "did not respond")):
        return "Network problem - check the internet (it retries by itself)"
    if any(x in l for x in ("unauthorized", "401", "invalid token", "forbidden", "403", "not a member", "chat not found", "administrator")):
        return "Bot / channel permission problem - the bot must be admin of the channel"
    if "changed while" in l:
        return "The file changed while it was being uploaded"
    if any(x in l for x in ("no such file", "not found", "missing")):
        return "The file is missing on this phone"
    if "no space" in l or "disk" in l:
        return "Not enough storage space"
    return ""


# last 50 problems (uploads that failed, jobs that stopped, server errors) - kept in storage/config/errors.json
_ERRLOG = {"loaded": False, "items": []}
_ERR_LOCK = threading.Lock()


def log_problem(src, msg):
    try:
        with _ERR_LOCK:
            f = CONFIG_DIR / "errors.json"
            if not _ERRLOG["loaded"]:
                _ERRLOG["loaded"] = True
                try:
                    _ERRLOG["items"] = json.loads(f.read_text("utf-8"))[-50:]
                except Exception:
                    _ERRLOG["items"] = []
            _ERRLOG["items"].append({"t": now(), "src": str(src)[:30], "msg": str(msg)[:400]})
            _ERRLOG["items"] = _ERRLOG["items"][-50:]
            try:
                CONFIG_DIR.mkdir(parents=True, exist_ok=True)
                f.write_text(json.dumps(_ERRLOG["items"]), "utf-8")
            except OSError:
                pass
    except Exception:
        pass


def _trash_age_days(ts):
    """Days since a file was moved to Recently Deleted (None when the stamp cannot be read)."""
    try:
        d = datetime.fromisoformat(str(ts))
        if d.tzinfo is None:
            d = d.astimezone()
        return (datetime.now(timezone.utc) - d).total_seconds() / 86400.0
    except Exception:
        return None


def _trash_days_left(ts):
    a = _trash_age_days(ts)
    if a is None:
        return None
    return max(0, int(TRASH_DAYS - a + 0.999))


def to_json(row, code=""):
    local = local_path(row) is not None
    return {"id": row["id"], "name": row["name"], "kind": row["kind"], "mime": row["mime"], "size": row["size"],
            "size_human": human_size(row["size"]), "taken_at": row["taken_at"], "status": row["status"],
            "local": local, "cloud": row["status"] == "backed_up" and not local,
            "message_id": row["message_id"], "chat_id": row["chat_id"], "error": row["error"],
            "code": code, "has_thumb": thumb_path(row["id"]).exists(),
            "v": format(zlib.crc32(str(row["sha256"]).encode()), "x") + THUMB_VER + (f"r{_rot_of(row)}" if _rot_of(row) else ""),      # changes when the id is reused by another photo -> browser never shows a stale picture
            "skip": bool(row["skip"]), "trashed": bool(row["trashed_at"]), "trash_days_left": _trash_days_left(row["trashed_at"]) if row["trashed_at"] else None, "error_hint": _friendly_error(row["error"]) if row["status"] == "failed" else "",
            "fav": bool(row["fav"]), "folder": row["folder"] or "", "has_cache": bool(row["cache_name"]), "rot": _rot_of(row), "backed_at": row["backed_at"] or "", "locked": bool(row["locked"]), "orphan": _is_orphan(row), "thumb_missing": _thumb_missing(row), "thumb_restorable": _thumb_restorable(row)}


# ── big files are stored as numbered PARTS: every part is one Telegram message (always <= 48 MB) ──
SINGLE_MAX = 48 * 1024 * 1024                                                     # bigger files are split into parts
PART_SIZE = max(8, min(48, int(os.environ.get("VAULT_PART_MB", "40")))) * 1024 * 1024
PART_WORKERS = max(1, min(8, int(os.environ.get("VAULT_PART_WORKERS", "3"))))     # parts fetched at the same time on download


def _part_dict(r):
    return {"idx": r["idx"], "pos": r["pos"], "len": r["plen"], "message_id": r["message_id"]}


def _plan_parts(c, row):
    """The part plan of one file. It is created once; a part that already reached Telegram keeps its message id,
    so an interrupted upload continues with the missing parts only."""
    size = int(row["size"] or 0)
    rows = c.execute("SELECT * FROM parts WHERE file_id=? ORDER BY idx", (row["id"],)).fetchall()
    if rows and sum(r["plen"] for r in rows) != size:                   # the file changed since the plan was made
        c.execute("DELETE FROM parts WHERE file_id=?", (row["id"],))
        rows = []
    if not rows:
        n = max(1, -(-size // PART_SIZE))
        for i in range(n):
            pos = i * PART_SIZE
            c.execute("INSERT INTO parts(file_id,idx,pos,plen) VALUES(?,?,?,?)",
                      (row["id"], i + 1, pos, min(PART_SIZE, size - pos)))
        rows = c.execute("SELECT * FROM parts WHERE file_id=? ORDER BY idx", (row["id"],)).fetchall()
    return rows


def ensure_parts(row):
    with db() as c:
        return [_part_dict(r) for r in _plan_parts(c, row)]


def get_parts(fid):
    with db() as c:
        return [_part_dict(r) for r in c.execute("SELECT * FROM parts WHERE file_id=? ORDER BY idx", (fid,)).fetchall()]


def done_parts(row):
    """Parts of a file that is completely in Telegram as parts - otherwise []."""
    if row["status"] != "backed_up":
        return []
    ps = get_parts(row["id"])
    return ps if ps and all(p["message_id"] for p in ps) else []


def part_mids(fid):
    return [p["message_id"] for p in get_parts(fid) if p["message_id"]]


def finalize_chunked(row, chat_id):
    """Every part is in Telegram -> the file counts as backed up (its message id = the first part)."""
    mid = get_parts(row["id"])[0]["message_id"]
    with db() as c:
        c.execute("UPDATE files SET status='backed_up', chat_id=?, message_id=?, bot_name='Parts', error=NULL, backed_at=? WHERE id=?",
                  (chat_id, mid, now(), row["id"]))
    return mid


def fetch_part(row, p, folder, job=None):
    out = folder / f"{p['idx']:05d}.bin"
    tl_download(row["chat_id"], p["message_id"], out, job=job)
    if out.stat().st_size != p["len"]:
        out.unlink(missing_ok=True)
        raise RuntimeError(f"Part {p['idx']} came back with the wrong size - try again")
    return out


def iter_part_files(row, parts, job=None):
    """Yield (part, local_path) in order while the next few parts are already downloading in parallel.
    A part file is deleted as soon as the caller is done with it, so the disk never holds the whole file."""
    folder = TMP / f"dl_{row['id']}_{time.time_ns()}"
    folder.mkdir(parents=True, exist_ok=True)
    ex = concurrent.futures.ThreadPoolExecutor(PART_WORKERS, thread_name_prefix="part-dl")
    futs, n = {}, len(parts)
    try:
        for i in range(min(PART_WORKERS, n)):
            futs[i] = ex.submit(fetch_part, row, parts[i], folder, job)
        for i in range(n):
            path = futs.pop(i).result()
            j = i + PART_WORKERS
            if j < n:
                futs[j] = ex.submit(fetch_part, row, parts[j], folder, job)
            yield parts[i], path
            path.unlink(missing_ok=True)
    finally:
        ex.shutdown(wait=False, cancel_futures=True)
        shutil.rmtree(folder, ignore_errors=True)


def assemble_parts(row, parts, dest):
    """Join all parts into ONE local file and verify it against the original SHA-256."""
    tmp = dest.with_name(dest.name + ".merge")
    h = hashlib.sha256()
    try:
        with open(tmp, "wb") as out:
            for _p, path in iter_part_files(row, parts):
                with open(path, "rb") as src:
                    for blk in iter(lambda: src.read(1 << 20), b""):
                        out.write(blk)
                        h.update(blk)
        if not str(row["sha256"]).startswith("cloud:") and h.hexdigest() != row["sha256"]:
            raise RuntimeError("The joined file does not match its original checksum - a part is damaged")
        os.replace(tmp, dest)
    finally:
        tmp.unlink(missing_ok=True)


# ── live transfer list: every download (this device, LAN guests, share links, FTP) is listed with its percentage ──
# The Downloads page reads it through GET /api/transfers. Only counters are kept here - no file data.
XFERS, _xf_lock, _xf_seq = {}, threading.Lock(), [0]


def _xf_who():
    """Who is downloading (inside a Flask request)."""
    try:
        ip = request.remote_addr or ""
        if request.environ.get("vault.lan") is not None:
            return "LAN " + ip
        return "This device" if ip in ("127.0.0.1", "::1", "") else "Device " + ip
    except RuntimeError:
        return ""


def xfer_begin(kind, name, total=0, who=None, note="", tag=None, fid=None):
    if tag is None:
        try:
            tag = (request.args.get("tx") or "")[:24]
        except RuntimeError:
            tag = ""
    uid = ""
    try:
        uid = (getattr(g, "guest", None) or {}).get("uid", "")          # LAN guest cookie id ("" = owner / FTP / share link)
    except RuntimeError:
        pass
    with _xf_lock:
        _xf_seq[0] += 1
        xid, t = _xf_seq[0], time.time()
        XFERS[xid] = {"id": xid, "kind": kind, "name": name, "total": int(total or 0), "done": 0, "who": who if who is not None else _xf_who(),
                      "tag": tag, "note": note, "status": "running", "t0": t, "t": t, "fid": fid, "uid": uid}
        finished = [k for k, v in XFERS.items() if v["status"] != "running"]
        for k in sorted(finished)[:-40]:
            XFERS.pop(k, None)
    return xid


def xfer_add(xid, n, note=None):
    x = XFERS.get(xid)
    if x:
        x["done"] += n
        x["t"] = time.time()
        if note is not None:
            x["note"] = note


def xfer_note(xid, note):
    x = XFERS.get(xid)
    if x:
        x["note"] = note
        x["t"] = time.time()


DLLOG_FILE = CONFIG_DIR / "download_log.json"        # file id -> who downloaded it last (kept after restarts)
DLLOG, _dl_lock = {}, threading.Lock()
DLLOG_KEEP = max(0.0, float(os.environ.get("VAULT_DLLOG_HOURS", "0"))) * 3600      # 0 (default) = entries stay until you clear them on the Downloads page; N = they also expire after N hours


def _xf_label(who):
    """Short text for the Downloads page: Web browser / LAN 192.168.x.x / FTP 192.168.x.x / Share link ..."""
    who = who or ""
    if who == "This device":
        return "Web browser"
    if who.startswith("Device "):
        return "Web browser " + who[7:]
    return who


DLLOG_LOCAL_FTP = os.environ.get("VAULT_DLLOG_LOCAL_FTP") == "1"      # 1 = also log FTP clients running on this same phone (default: no)


def is_local_ftp(who):
    """'FTP 127.0.0.1' = a file manager (MT Manager ...) on THIS phone reading files through the FTP. Every open / preview there is a full
    read, so it is not a real download by somebody else and must not fill the download log."""
    w = str(who or "").strip()
    return w.startswith("FTP ") and w[4:].strip() in ("127.0.0.1", "::1", "localhost", "")


def _dllog_save():
    """Write the log; when nothing is left the download_log.json file itself is deleted. (call with _dl_lock held)"""
    try:
        if not DLLOG:
            DLLOG_FILE.unlink(missing_ok=True)
            return
        CONFIG_DIR.mkdir(parents=True, exist_ok=True)
        tmp = DLLOG_FILE.with_suffix(".tmp")
        sec_write(tmp, json.dumps(DLLOG))
        os.replace(tmp, DLLOG_FILE)
    except OSError:
        pass


def dllog_prune():
    """Remove the entries that are older than DLLOG_KEEP; the file is deleted when it becomes empty. Returns how many were removed."""
    if not DLLOG_KEEP:
        return 0                                          # no timer: entries only go when they are cleared on the Downloads page
    with _dl_lock:
        limit = time.time() - DLLOG_KEEP
        old = [k for k, v in DLLOG.items() if int((v or {}).get("t") or 0) < limit]
        for k in old:
            DLLOG.pop(k, None)
        if old or (not DLLOG and DLLOG_FILE.exists()):
            _dllog_save()
        return len(old)


def dllog_clear():
    """Forget every download record and delete download_log.json."""
    with _dl_lock:
        DLLOG.clear()
        try:
            DLLOG_FILE.unlink(missing_ok=True)
        except OSError:
            pass


def dllog_remove(ids):
    """Downloads page > Clear: forget these files. When nothing is left, download_log.json is deleted. Returns how many were removed."""
    with _dl_lock:
        n = 0
        for i in ids or []:
            if DLLOG.pop(str(i), None) is not None:
                n += 1
        if n or (not DLLOG and DLLOG_FILE.exists()):
            _dllog_save()
        return n


def dllog_load():
    try:
        DLLOG.update({str(k): v for k, v in json.loads(sec_read(DLLOG_FILE)).items()})
    except Exception:
        pass
    if not DLLOG_LOCAL_FTP:                               # entries of this phone's own FTP reads (older versions wrote them) are dropped
        with _dl_lock:
            bad = [k for k, v in DLLOG.items() if is_local_ftp((v or {}).get("by"))]
            for k in bad:
                DLLOG.pop(k, None)
            if bad or (not DLLOG and DLLOG_FILE.exists()):
                _dllog_save()
    dllog_prune()


dllog_load()


def dllog_add(fid, who, uid=""):
    if not fid or (is_local_ftp(who) and not DLLOG_LOCAL_FTP):
        return
    with _dl_lock:
        old = DLLOG.pop(str(fid), None) or {}
        us = [u for u in old.get("u", []) if u != uid][-19:] + ([uid] if uid else [])
        DLLOG[str(fid)] = {"by": _xf_label(who), "t": int(time.time()), "u": us}
        while len(DLLOG) > 5000:
            DLLOG.pop(next(iter(DLLOG)))
        _dllog_save()
    dllog_prune()


def xfer_end(xid, ok=None, note=""):
    """ok=None: finished when everything announced was sent, otherwise 'stopped' (the other side closed the connection)."""
    x = XFERS.get(xid)
    if not x or x["status"] != "running":
        return
    if ok is None:
        ok = not x["total"] or x["done"] >= x["total"]
    x["status"] = "done" if ok else ("error" if note else "stopped")
    if ok and x.get("fid"):
        dllog_add(x["fid"], x["who"], x.get("uid", ""))
    x["note"] = note if note else ("" if ok else "Stopped")
    x["t"] = time.time()


class _Count:
    """Response body wrapper: counts the bytes that really leave this device and closes the transfer when it ends."""
    def __init__(self, body, xid):
        self.body, self.xid, self.src = body, xid, iter(body)

    def __iter__(self):
        return self

    def __next__(self):
        try:
            b = next(self.src)
        except StopIteration:
            xfer_end(self.xid)
            raise
        except BaseException as e:
            xfer_end(self.xid, False, str(e)[:120] or "Failed")
            raise
        xfer_add(self.xid, len(b), "")
        return b

    def close(self):
        xfer_end(self.xid)
        c = getattr(self.body, "close", None)
        if c:
            c()


def xfer_wrap(resp, xid):
    """Attach the counter to a finished Response (file, stream ...). Replies that carry no file (304, errors) leave no entry."""
    if resp.status_code in (200, 206) and not isinstance(resp.response, (list, tuple)):
        n = resp.content_length
        if n:
            XFERS[xid]["total"] = int(n)
        resp.response = _Count(resp.response, xid)
    else:
        XFERS.pop(xid, None)
    return resp


def xfer_list():
    now = time.time()
    with _xf_lock:
        for x in XFERS.values():
            if x["status"] == "running" and now - x["t"] > 3600:
                x["status"], x["note"] = "stopped", "Stopped"
        for k in [k for k, x in XFERS.items() if x["status"] != "running" and now - x["t"] > 3600]:
            XFERS.pop(k, None)
        items = sorted(XFERS.values(), key=lambda x: -x["id"])
    out = []
    for x in items:
        pct = min(100, int(x["done"] * 100 / x["total"])) if x["total"] else (100 if x["status"] == "done" else 0)
        out.append({"id": x["id"], "kind": x["kind"], "name": x["name"], "who": x["who"], "tag": x["tag"], "status": x["status"],
                    "note": x["note"], "done": x["done"], "total": x["total"], "pct": pct, "fid": x.get("fid")})
    return out


def stream_parts(row, parts, who=None):
    """Browser download of a multi-part file: parts are fetched in parallel and sent in order,
    so the browser receives ONE merged file and nothing is assembled on the server's disk."""
    if not tl_ready():
        return "Log in to your Telegram account (Settings) to download this file again.", 503
    xid = xfer_begin("download", row["name"], sum(p["len"] for p in parts), who, "Fetching from Telegram ...", fid=row["id"])
    it = iter_part_files(row, parts)
    try:
        first = next(it)                                  # fail early (before the download starts) if Telegram refuses
    except Exception as e:
        it.close()
        xfer_end(xid, False, "Telegram refused")
        return f"Could not get this file: {e}", 503
    xfer_note(xid, "")

    def gen():
        try:
            for _p, path in itertools.chain([first], it):
                with open(path, "rb") as f:
                    while True:
                        blk = f.read(1 << 20)
                        if not blk:
                            break
                        yield blk
        finally:
            it.close()
    from urllib.parse import quote
    resp = Response(_Count(gen(), xid), mimetype="application/octet-stream", headers={
        "Content-Disposition": "attachment; filename*=UTF-8''" + quote(row["name"]),
        "Content-Length": str(sum(p["len"] for p in parts)), "Cache-Control": "no-store",
        "X-Content-Type-Options": "nosniff", "Content-Security-Policy": "sandbox"})
    return resp


def restore_local(row, progress=None):
    """Make sure a local copy exists (download from Telegram when needed). Returns Path."""
    p = local_path(row)
    if p:
        return p
    if not (row["chat_id"] and row["message_id"]):
        raise RuntimeError("No copy of this file exists on this device or in Telegram.")
    if not tl_ready():
        raise RuntimeError("Log in to your Telegram account (Settings) to download this file again.")
    ensure_dirs()
    with _files_guard:
        lock = _locks.setdefault(row["id"], threading.Lock())
    with lock:
        p = local_path(row)
        if p:
            return p
        name = f"{row['id']}_{safe_name(row['name'])}"
        dest = CACHE / name
        parts = done_parts(row)
        if parts:
            assemble_parts(row, parts, dest)              # big file: parts come back in parallel and are joined + verified
        else:
            tl_download(row["chat_id"], row["message_id"], dest, progress=progress)
        with db() as c:
            c.execute("UPDATE files SET cache_name=? WHERE id=?", (name, row["id"]))
        return dest


def apk_icon(src, out):
    # APK = zip file: pick the biggest launcher/icon PNG inside it
    try:
        from PIL import Image
        with zipfile.ZipFile(src) as z:
            cands = [i for i in z.infolist() if i.filename.lower().endswith(".png")
                     and any(w in i.filename.lower() for w in ("launcher", "icon", "logo"))]
            if not cands:
                cands = [i for i in z.infolist() if i.filename.lower().endswith(".png") and "mipmap" in i.filename.lower()]
            if not cands:
                return None
            data = z.read(max(cands, key=lambda i: i.file_size))
        with Image.open(io.BytesIO(data)) as im:
            im = im.convert("RGBA")
            im.thumbnail((420, 420))
            bg = Image.new("RGBA", im.size, (255, 255, 255, 255))
            bg.alpha_composite(im)
            bg.convert("RGB").save(out, "JPEG", quality=85)
        return out
    except Exception:
        out.unlink(missing_ok=True)
        return None


THUMB_EDGE, THUMB_Q = 280, 50        # light grid previews: ~15-25 KB each (see THUMB_MAX_KB)
THUMB_MAX_KB = 10                    # quality is lowered step by step until a preview fits under this
THUMB_MIN = 120                      # a cached preview smaller than this (long side) is a tiny Telegram preview (~90-320 px) -> rebuild it
THUMB_VER = "t5"                     # bump to rebuild every preview once at the next start


def jpeg_long_side(path):
    """Long side in pixels of a JPEG, read from its header only (no Pillow needed). None if unknown."""
    try:
        with open(path, "rb") as f:
            if f.read(2) != b"\xff\xd8":
                return None
            while True:
                b = f.read(1)
                while b and b != b"\xff":
                    b = f.read(1)
                while b == b"\xff":
                    b = f.read(1)
                if not b:
                    return None
                m = b[0]
                if m == 0x01 or 0xD0 <= m <= 0xD8:
                    continue
                seg = f.read(2)
                if len(seg) < 2:
                    return None
                n = int.from_bytes(seg, "big")
                if 0xC0 <= m <= 0xCF and m not in (0xC4, 0xC8, 0xCC):
                    d = f.read(5)
                    return max(int.from_bytes(d[1:3], "big"), int.from_bytes(d[3:5], "big"))
                f.seek(n - 2, 1)
    except Exception:
        return None


_TM_TAG = b"VMETA1:"


def _tm_split(data):
    """(index after the leading APPn segments, [(start, end) of old VMETA comments], meta dict or None) of a JPEG."""
    pos, ins, old, meta = 2, None, [], None
    while pos + 4 <= len(data) and data[pos] == 0xFF:
        mk = data[pos + 1]
        if mk == 0xFF:
            pos += 1
            continue
        if mk in (0xDA, 0xD9):
            break
        ln = int.from_bytes(data[pos + 2:pos + 4], "big")
        if mk == 0xFE and data[pos + 4:pos + 4 + len(_TM_TAG)] == _TM_TAG:
            old.append((pos, pos + 2 + ln))
            try:
                meta = json.loads(data[pos + 4 + len(_TM_TAG):pos + 2 + ln].decode("utf-8"))
            except Exception:
                pass
        elif ins is None and not (0xE0 <= mk <= 0xEF):
            ins = pos
        pos += 2 + ln
    return (ins if ins is not None else 2), old, meta


def thumb_meta_read(path):
    """Photo details (width, height, camera, location) that travel INSIDE the thumbnail jpg itself, or None."""
    try:
        with open(path, "rb") as f:
            data = f.read(65536 + 4096)
        if data[:2] != b"\xff\xd8":
            return None
        return _tm_split(data)[2]
    except Exception:
        return None


def thumb_meta_embed(path, meta):
    """Writes the details into the thumb jpg (JPEG comment block, ~100 bytes). It stays in the file when the thumb is uploaded to
    Telegram, restored, zipped or copied - so the details always load together with the thumbnail. Never raises."""
    try:
        path = Path(path)
        data = path.read_bytes()
        if data[:2] != b"\xff\xd8":
            return False
        body = _TM_TAG + json.dumps({k: (meta or {}).get(k) for k in _META_KEYS}, separators=(",", ":")).encode("utf-8")
        seg = b"\xff\xfe" + (len(body) + 2).to_bytes(2, "big") + body
        ins, old, _m = _tm_split(data)
        for a, b in reversed(old):
            data = data[:a] + data[b:]
            if a < ins:
                ins -= (b - a)
        tmp = path.with_name(path.name + f".{time.time_ns()}.mt")
        tmp.write_bytes(data[:ins] + seg + data[ins:])
        os.replace(tmp, path)
        return True
    except Exception:
        return False


def _tm_kv_save(row, meta):
    try:
        with db() as c:
            c.execute("INSERT OR REPLACE INTO kv(key,value) VALUES(?,?)", ("meta6:" + str(row["sha256"]), json.dumps({k: meta.get(k) for k in _META_KEYS})))
    except Exception:
        pass


def _tm_attach(thumb, src, row):
    """New thumbnail of a photo: read its details from the original and put them into the thumb at once."""
    try:
        m = _read_image_meta(src)
        if m.get("width"):
            thumb_meta_embed(thumb, m)
            _tm_kv_save(row, m)
    except Exception:
        pass


def thumb_is_low(path):
    side = jpeg_long_side(path)
    return side is not None and side < THUMB_MIN


def thumb_upgrade():
    """Once per THUMB_VER: drop the old soft/tiny previews so they are rebuilt sharp (originals are never touched)."""
    try:
        if kv_get("thumb_ver") != THUMB_VER:
            kv_set("thumb_ver", THUMB_VER)
            def _shrink():                     # existing previews are made smaller in place - no Telegram, no deleting
                try:
                    from PIL import Image
                except ImportError:
                    return
                for p in list(THUMBS.glob("*.jpg")):
                    try:
                        if p.stat().st_size <= THUMB_MAX_KB * 1024:
                            continue
                        _keep = thumb_meta_read(p)
                        with Image.open(p) as im:
                            im = im.convert("RGB"); im.thumbnail((THUMB_EDGE, THUMB_EDGE), Image.LANCZOS)
                        tmp = p.with_name(p.name + ".shr")
                        for q in (THUMB_Q, 42, 35, 28):
                            im.save(tmp, "JPEG", quality=q, optimize=True, progressive=True)
                            if tmp.stat().st_size <= THUMB_MAX_KB * 1024:
                                break
                        if _keep:
                            thumb_meta_embed(tmp, _keep)
                        os.replace(tmp, p)
                    except Exception:
                        pass
            threading.Thread(target=_shrink, daemon=True).start()
    except Exception:
        pass


def _jpeg_pil(src, out):
    from PIL import Image, ImageOps
    with Image.open(src) as im:
        im = ImageOps.exif_transpose(im)
        im.thumbnail((THUMB_EDGE, THUMB_EDGE), Image.LANCZOS)
        im = im.convert("RGB")
        for q in (THUMB_Q, 42, 35, 28):                      # smallest quality that still fits ~25 KB
            im.save(out, "JPEG", quality=q, optimize=True, progressive=True)
            if os.path.getsize(out) <= THUMB_MAX_KB * 1024:
                break


def _pdf_thumb(src, out):
    """First page of a PDF as a small JPEG: PyMuPDF if present, else poppler's pdftoppm."""
    try:
        import fitz
        with fitz.open(str(src)) as d:
            pix = d[0].get_pixmap(matrix=fitz.Matrix(1, 1), alpha=False)
            tmp = Path(str(out) + ".png"); pix.save(str(tmp))
        try:
            _jpeg_pil(tmp, out)
        finally:
            tmp.unlink(missing_ok=True)
        return Path(out).exists() and Path(out).stat().st_size > 0
    except Exception:
        pass
    if shutil.which("pdftoppm"):
        base = Path(str(out) + ".pp")
        try:
            subprocess.run(["pdftoppm", "-jpeg", "-r", "50", "-f", "1", "-l", "1", "-singlefile", str(src), str(base)], timeout=60, check=True)
            j = Path(str(base) + ".jpg")
            try:
                _jpeg_pil(j, out)
            except Exception:
                os.replace(j, out)
            j.unlink(missing_ok=True)
            return Path(out).exists() and Path(out).stat().st_size > 0
        except Exception:
            pass
    return False


def _heic_cli(src, out):
    """HEIC/HEIF -> full JPEG using libheif command-line tools (Termux: pkg install libheif-progs). True on success."""
    for tool in ("heif-dec", "heif-convert"):
        exe = shutil.which(tool)
        if not exe:
            continue
        try:
            Path(out).unlink(missing_ok=True)
            subprocess.run([exe, str(src), str(out)], timeout=120, check=True,
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            if Path(out).exists() and Path(out).stat().st_size > 0:
                return True
            # some versions write name-1.jpg
            alt = Path(out).with_name(Path(out).stem + "-1.jpg")
            if alt.exists() and alt.stat().st_size > 0:
                os.replace(alt, out)
                return True
        except Exception:
            pass
    return False


def _heic_make(src, out, edge=None):
    """Last-resort HEIC handler: CLI-convert to a temp JPEG, then shrink it (Pillow or ffmpeg). edge=None -> thumb size."""
    tmpj = Path(str(out) + f".{time.time_ns()}.full.jpg")
    try:
        if not _heic_cli(src, tmpj):
            return False
        try:
            _jpeg_pil(tmpj, out)
            return Path(out).exists() and Path(out).stat().st_size > 0
        except Exception:
            return _jpeg_ffmpeg(tmpj, out)
    finally:
        tmpj.unlink(missing_ok=True)


def _jpeg_ffmpeg(src, out, video=False):
    """Fallback when Pillow is not installed (common on phones): ffmpeg can shrink images and grab video frames."""
    if not shutil.which("ffmpeg"):
        return False
    cmd = ["ffmpeg", "-y", "-loglevel", "error"] + (["-ss", "1"] if video else []) + ["-i", str(src), "-frames:v", "1",
           "-vf", f"scale='min({THUMB_EDGE},iw)':-2", "-q:v", "3", "-f", "image2", str(out)]
    try:
        subprocess.run(cmd, timeout=60, check=True)
    except Exception:
        if video:                       # very short clip: try the first frame
            try:
                subprocess.run([c for c in cmd if c not in ("-ss", "1")], timeout=60, check=True)
            except Exception:
                return False
        else:
            return False
    return Path(out).exists() and Path(out).stat().st_size > 0


def make_thumb(row, src=None):
    """Small JPEG preview (512 px, q65 like the app) from a local copy. Returns Path or None."""
    out = thumb_path(row["id"])
    src = src or local_path(row)
    if out.exists() and out.stat().st_size > 0:
        if not src or not thumb_is_low(out):
            return out
    if not src:
        return None
    ensure_dirs()
    tmp = out.with_name(out.name + f".{time.time_ns()}.tmp")
    try:
        ok = False
        if row["kind"] == "image":
            try:
                _jpeg_pil(src, tmp)
                ok = True
            except Exception:
                tmp.unlink(missing_ok=True)
                ok = _jpeg_ffmpeg(src, tmp)
                if not ok and Path(row["name"]).suffix.lower() in (".heic", ".heif"):
                    tmp.unlink(missing_ok=True)
                    ok = _heic_make(src, tmp)
        elif Path(row["name"]).suffix.lower() == ".apk":
            ok = apk_icon(src, tmp) is not None
        elif Path(row["name"]).suffix.lower() == ".pdf":
            ok = _pdf_thumb(src, tmp)
        elif row["kind"] == "video":
            ok = _jpeg_ffmpeg(src, tmp, video=True)
        elif Path(row["name"]).suffix.lower() in AUDIO_MIME:
            ok = _jpeg_ffmpeg(src, tmp)                  # cover art embedded in the song (if any)
        if ok and tmp.exists() and tmp.stat().st_size > 0:
            if row["kind"] == "image":
                _tm_attach(tmp, src, row)                # photo details go INSIDE the thumbnail (and so into Telegram with it)
            os.replace(tmp, out)
            return out
    except Exception:
        pass
    tmp.unlink(missing_ok=True)
    return out if out.exists() and out.stat().st_size > 0 else None


def _bots_for(row):
    """Bots to try for Bot-API calls: the one that uploaded the file first."""
    bots = cfg_bots()
    return sorted(bots, key=lambda b: 0 if b["name"] == row["bot_name"] else 1)


def tg_fetch_file(token, file_id, timeout=40):
    """Bot API getFile + download (works up to 20 MB, perfect for thumbnails). Returns bytes."""
    info = tgapi_call(token, "getFile", {"file_id": file_id})
    fp = info.get("file_path")
    if not fp:
        raise RuntimeError("Telegram gave no file_path")
    conn = http.client.HTTPSConnection("api.telegram.org", timeout=timeout)
    try:
        conn.request("GET", f"/file/bot{token}/{fp}")
        r = conn.getresponse()
        data = r.read()
        if r.status != 200:
            raise RuntimeError(f"Telegram file HTTP {r.status}")
        return data
    except (OSError, http.client.HTTPException) as e:
        raise RuntimeError("Network error: " + str(e).replace(token, "***"))
    finally:
        conn.close()


def fetch_bot_thumb(row):
    """Thumbnail that WE uploaded next to the file (thumb.jpg message), fetched with getFile - no Telegram login needed."""
    out = thumb_path(row["id"])
    fid = row["thumb_file_id"]
    if not fid:
        return None
    ensure_dirs()
    for b in _bots_for(row):
        try:
            data = tg_fetch_file(b["token"], fid)
            if len(data) < 100:
                continue
            tmp = out.with_name(out.name + f".{time.time_ns()}.tmp")
            tmp.write_bytes(data)
            os.replace(tmp, out)
            return out
        except Exception:
            continue
    return None


def upload_thumb(row, bot, mid, job=None):
    """After a file is backed up: send a small thumb.jpg as its own message (same idea as the app's uploadThumbnail).
    Returns (file_id, message_id) or None. Never raises - a missing thumbnail must not fail the backup."""
    try:
        p = make_thumb(row)
        if not p:
            return None
        for attempt in range(3):
            try:
                res = tgapi_call(bot["token"], "sendDocument",
                                 {"chat_id": cfg_load()["chat_id"], "caption": make_caption(cfg_load()["vault_code"], row["name"], row["sha256"]) + f"\nVT {mid}", "disable_notification": "true"},
                                 file_path=str(p), upload_name="thumb.jpg", timeout=120, job=job)
                doc = res.get("document") or {}
                if doc.get("file_id"):
                    return doc["file_id"], res["message_id"]
                return None
            except TgRetry as e:
                job_nap(job, min(e.retry_after + 1, 30))
        return None
    except Exception:
        return None


THUMB_FAIL = {}      # file id -> time of last failed attempt (so a broken tile does not hammer Telegram)


def _linked_thumb(row, force=False):
    """The thumb.jpg message that is ALREADY in Telegram (its message id is saved, or it is found by its 'VT <file message id>' caption)
    is downloaded and kept in thumbs/ - nothing is uploaded. Returns (state, Path): 'ok' / 'gone' (really no thumbnail in Telegram) /
    'error' (Telegram or network trouble: unsure, so the caller must NOT upload a new one)."""
    out = thumb_path(row["id"])
    if not force and out.exists() and out.stat().st_size > 0:
        return "ok", out
    if not (row["chat_id"] and row["message_id"]) or not tl_ready():
        return "error", None
    tm = int(row["thumb_message_id"] or 0)
    try:
        if not tm:
            if not (row["kind"] in ("image", "video") or str(row["name"]).lower().endswith(".apk")):
                return "gone", None
            found = tl_find_thumbs(row["chat_id"], [int(row["message_id"])]).get(int(row["message_id"])) or []
            if not found:
                return "gone", None
            tm = max(found)
            with db() as c:
                c.execute("UPDATE files SET thumb_message_id=? WHERE id=? AND thumb_message_id IS NULL", (tm, row["id"]))
        ensure_dirs()
        tmp = out.with_name(out.name + f".{time.time_ns()}.lt")
        try:
            tl_download(row["chat_id"], tm, tmp, timeout=90)
            if tmp.exists() and tmp.stat().st_size > 100:
                os.replace(tmp, out)
                return "ok", out
            return "error", None
        finally:
            tmp.unlink(missing_ok=True)
    except Exception as e:
        if "no longer exists" in str(e):
            return "gone", None
        return "error", None


def get_thumb(row):
    """Every way to get a thumbnail: local copy -> our uploaded thumb -> Telegram's own thumb -> small download.
    A tiny Telegram preview (a few hundred px at best) is only a stop-gap: the original is pulled once and a sharp one built."""
    fid = row["id"]
    p = make_thumb(row)
    if p:
        return p                                   # any preview we already have is shown at once
    _is_song = Path(row["name"]).suffix.lower() in AUDIO_MIME
    if _is_song:
        q = audio_cover(row)                       # the picture inside the song's own tag beats any tiny Telegram preview
        if q:
            return q
    if time.time() - THUMB_FAIL.get(fid, 0) < (15 if BIG_BUSY[0] else 120):
        return p
    p = fetch_bot_thumb(row) or _linked_thumb(row)[1] or fetch_cloud_thumb(row)
    if p:
        return p
    if row["kind"] in ("image", "video") and 0 < row["size"] <= 3 * 1024 * 1024 and row["chat_id"] and row["message_id"] and tl_ready():
        tmp = None
        try:
            ensure_dirs()
            tmp = TMP / f"th_{fid}_{time.time_ns()}{Path(row['name']).suffix}"
            tl_download(row["chat_id"], row["message_id"], tmp, timeout=300)
            q = make_thumb(row, tmp)
            if q and not thumb_is_low(q):
                return q
        except Exception:
            pass
        finally:
            if tmp:
                tmp.unlink(missing_ok=True)
    if (row["kind"] == "video" and shutil.which("ffmpeg") and row["chat_id"] and row["message_id"] and int(row["size"] or 0) > 0
            and not done_parts(row) and tl_ready()):
        tmp = None                                  # no preview in Telegram: grab a frame from only the first 4 MB + last 2 MB of the video
        try:
            ensure_dirs()
            nb = -(-int(row["size"]) // STREAM_B)
            tmp = TMP / f"vt_{fid}_{time.time_ns()}.mp4"
            with open(tmp, "wb") as f:
                f.truncate(int(row["size"]))
                for i in sorted(set(range(min(nb, 4))) | set(range(max(0, nb - 2), nb))):
                    f.seek(i * STREAM_B)
                    f.write(_block_bytes(row, i))
            q = make_thumb(row, tmp)
            if q:
                return q
        except Exception:
            pass
        finally:
            if tmp:
                tmp.unlink(missing_ok=True)
    if _is_song:
        q = audio_web_cover(row)
        if q:
            return q
        THUMB_FAIL[fid] = time.time() - 105        # songs: try again soon (a retry costs little)
        return p
    THUMB_FAIL[fid] = time.time()
    return p


# ---- song tags + cover (ID3v2: title, artist, album and the embedded picture) ----------------------------------------
# A music player does not "guess" the cover: an MP3 carries it inside the file, in a block at the very beginning (ID3 tag).
# We read only that block (the first MBs, streamed from Telegram if the file is cloud-only), keep the picture as the thumbnail.
def _syncsafe(b):
    return (b[0] << 21) | (b[1] << 14) | (b[2] << 7) | b[3]


def _read_head(row, n):
    """The first n bytes of a song: from the local copy, or the first 1 MB blocks of a cloud file."""
    lp = local_path(row)
    if lp:
        with open(lp, "rb") as f:
            return f.read(n)
    size = int(row["size"] or 0)
    if size <= 0 or not (row["chat_id"] and row["message_id"]) or done_parts(row) or not tl_ready():
        return b""
    out = b""
    for i in range(-(-min(n, size) // STREAM_B)):
        out += _block_bytes(row, i)                    # in memory only: no block files are left on the disk
    return out[:n]


def _id3_text(b):
    if not b:
        return ""
    codec = {0: "latin-1", 1: "utf-16", 2: "utf-16-be", 3: "utf-8"}.get(b[0], "latin-1")
    try:
        return b[1:].decode(codec, "replace").split("\x00")[0].replace("\ufeff", "").strip()
    except Exception:
        return ""


def _id3_pic(b, v22):
    enc, i = b[0], 1
    if v22:
        i += 3
    else:
        i = b.index(b"\x00", i) + 1                     # mime type
    i += 1                                              # picture type
    if enc in (1, 2):                                   # description in UTF-16: ends with 00 00
        while i + 1 < len(b) and not (b[i] == 0 and b[i + 1] == 0):
            i += 2
        i += 2
    else:
        j = b.find(b"\x00", i)
        i = j + 1 if j >= 0 else len(b)
    return b[i:]


def parse_id3(head):
    if len(head) < 10 or head[:3] != b"ID3":
        return {}
    ver, flags = head[3], head[5]
    if flags & 0x80:                                    # unsynchronised tag
        head = head[:10] + head[10:].replace(b"\xff\x00", b"\xff")
    end, pos = min(len(head), 10 + _syncsafe(head[6:10])), 10
    if flags & 0x40 and ver >= 3 and len(head) > 14:    # extended header
        pos = 10 + (int.from_bytes(head[10:14], "big") + 4 if ver == 3 else _syncsafe(head[10:14]))
    hl, res = (6 if ver == 2 else 10), {}
    while pos + hl <= end:
        if head[pos] == 0:
            break
        fid = head[pos:pos + (3 if ver == 2 else 4)].decode("latin-1")
        if ver == 2:
            sz = int.from_bytes(head[pos + 3:pos + 6], "big")
        elif ver == 4:
            sz = _syncsafe(head[pos + 4:pos + 8])
        else:
            sz = int.from_bytes(head[pos + 4:pos + 8], "big")
        body = head[pos + hl:pos + hl + sz]
        fl = head[pos + 9] if ver == 4 and pos + 9 < len(head) else 0
        pos += hl + sz
        if fl & 0x02:
            body = body.replace(b"\xff\x00", b"\xff")
        if fl & 0x01:                                   # data length indicator
            body = body[4:]
        if sz <= 0:
            break
        if fid in ("TIT2", "TT2"):
            res["title"] = _id3_text(body)
        elif fid in ("TPE1", "TP1"):
            res["artist"] = _id3_text(body)
        elif fid in ("TALB", "TAL"):
            res["album"] = _id3_text(body)
        elif fid in ("APIC", "PIC") and "pic" not in res:
            try:
                res["pic"] = _id3_pic(body, ver == 2)
            except Exception:
                pass
    return res


def _save_cover(row, pic):
    out = thumb_path(row["id"])
    ensure_dirs()
    tmp = TMP / f"cv_{row['id']}_{time.time_ns()}"
    t2 = out.with_name(out.name + f".{time.time_ns()}.tmp")
    try:
        tmp.write_bytes(pic)
        ok = False
        try:
            _jpeg_pil(tmp, t2)
            ok = True
        except Exception:
            t2.unlink(missing_ok=True)
            ok = _jpeg_ffmpeg(tmp, t2)
        if not ok and pic[:2] == b"\xff\xd8":
            t2.write_bytes(pic)
            ok = True
        if ok and t2.exists() and t2.stat().st_size > 0:
            os.replace(t2, out)
            return out
    except Exception:
        pass
    finally:
        tmp.unlink(missing_ok=True)
        t2.unlink(missing_ok=True)
    return None


def _clean_title(name):
    s = re.sub(r"\(.*?\)|\[.*?\]", " ", Path(name).stem)
    s = re.sub(r"\b\d{2,3}\s*kbps\b", " ", s, flags=re.I)
    return " ".join(re.sub(r"[_\-.]+", " ", s).split())


def audio_tags(row):
    """{title, artist, album, cover} of a song (cached). The cover inside the file's own tag becomes the thumbnail."""
    jp = PREVIEWS / f"{row['id']}.tags.json"
    try:
        c = json.loads(jp.read_text("utf-8"))
        if c.get("v") == 2:
            return c
    except Exception:
        pass
    head = _read_head(row, 10)
    if not head:
        return {"title": "", "artist": "", "album": "", "cover": False}
    info = parse_id3(_read_head(row, min(10 + _syncsafe(head[6:10]), 12 * 1024 * 1024))) if head[:3] == b"ID3" else {}
    saved = _save_cover(row, info["pic"]) if info.get("pic") else None
    tags = {"v": 2, "title": info.get("title", ""), "artist": info.get("artist", ""), "album": info.get("album", ""), "cover": bool(saved), "web": False}
    try:
        ensure_dirs()
        jp.write_text(json.dumps(tags), "utf-8")
    except Exception:
        pass
    return tags


def audio_cover(row):
    """The picture that is inside the song itself."""
    try:
        t = audio_tags(row)
    except Exception:
        return None
    p = thumb_path(row["id"])
    return p if t.get("cover") and p.exists() and p.stat().st_size > 0 else None


def audio_web_cover(row):
    """Last resort for songs that carry no picture: the public cover of the same song (iTunes search, nothing is uploaded but the song name).
    Switch off with VAULT_NO_WEBART=1."""
    if os.environ.get("VAULT_NO_WEBART") == "1":
        return None
    try:
        t = audio_tags(row)
        if t.get("cover"):
            return thumb_path(row["id"])
        if t.get("web"):
            return None                                   # already tried, nothing found
        import urllib.request, urllib.parse
        term = (t.get("title") + " " + t.get("artist")).strip() if t.get("title") else _clean_title(row["name"])
        if not term:
            return None
        url = "https://itunes.apple.com/search?" + urllib.parse.urlencode({"term": term, "media": "music", "entity": "song", "limit": 3, "country": "IN"})
        hdr = {"User-Agent": "Mozilla/5.0 CloudVault"}
        with urllib.request.urlopen(urllib.request.Request(url, headers=hdr), timeout=8) as r:
            res = json.loads(r.read().decode("utf-8", "replace")).get("results", [])
        words = [w for w in re.split(r"\W+", _clean_title(row["name"]).lower()) if len(w) >= 3][:2]
        hit = None
        for x in res:
            blob = (x.get("trackName", "") + " " + x.get("artistName", "")).lower()
            if x.get("artworkUrl100") and words and all(w in blob for w in words):
                hit = x
                break
        t["web"] = True                                   # the search itself worked: do not repeat it
        out = None
        if hit:
            art = hit["artworkUrl100"].replace("100x100bb", "600x600bb")
            with urllib.request.urlopen(urllib.request.Request(art, headers=hdr), timeout=10) as r:
                out = _save_cover(row, r.read(6 * 1024 * 1024))
            if out:
                t["cover"] = True
                t["title"] = t.get("title") or hit.get("trackName", "")
                t["artist"] = t.get("artist") or hit.get("artistName", "")
        try:
            (PREVIEWS / f"{row['id']}.tags.json").write_text(json.dumps(t), "utf-8")
        except Exception:
            pass
        return out
    except Exception:
        return None                                       # network trouble: not remembered, tried again later


THUMB_PAR = max(1, min(32, int(os.environ.get("VAULT_THUMB_PAR", "12"))))      # previews downloaded at the same time during Sync


async def _thumbs_bulk(items, tick):
    """items = [(chat_id, message_id, dest Path, file id)]. The messages are asked 100 per request and the tiny previews are
    downloaded THUMB_PAR at a time over the logged-in account. Result: file id -> True (saved) / False (this file has no preview
    in Telegram - never asked again) / None (network trouble - tried again next time)."""
    c = await _client()
    res, sem, by_chat = {}, asyncio.Semaphore(THUMB_PAR), {}
    for it in items:
        by_chat.setdefault(str(it[0]), []).append(it)

    async def one(m, dest, fid, full=False):
        async with sem:
            tmp = dest.with_name(dest.name + f".{time.time_ns()}.part")
            try:
                out = await asyncio.wait_for(c.download_media(m, file=str(tmp)) if full else c.download_media(m, file=str(tmp), thumb=-1), 60)
                if out and os.path.getsize(out) > 100:
                    os.replace(out, dest)
                    res[fid] = True
                else:
                    res[fid] = False
                    if out:
                        Path(out).unlink(missing_ok=True)
            except Exception:
                res[fid] = None
            finally:
                Path(tmp).unlink(missing_ok=True)
                tick()

    for chat, its in by_chat.items():
        ent = await _entity(c, chat)
        for i in range(0, len(its), 100):
            chunk = its[i:i + 100]
            try:
                got = await c.get_messages(ent, ids=[x[1] for x in chunk])
            except Exception:
                for x in chunk:
                    res[x[3]] = None
                    tick()
                continue
            if not isinstance(got, list):
                got = [got]
            jobs = []
            for x, m in zip(chunk, got):
                if m is None or not (getattr(m, "document", None) or getattr(m, "photo", None)):
                    res[x[3]] = False
                    tick()
                else:
                    jobs.append(one(m, x[2], x[3], len(x) > 4 and bool(x[4])))
            if jobs:
                await asyncio.gather(*jobs)
    return res


def fetch_cloud_thumb(row, job=None):
    """Tiny preview straight from Telegram (no full download) for cloud-only files."""
    out = thumb_path(row["id"])
    if out.exists() and out.stat().st_size > 0:
        return out
    if not (row["chat_id"] and row["message_id"]) or not tl_ready():
        return None
    if done_parts(row):
        return None
    try:
        tl_download(row["chat_id"], row["message_id"], out, thumb=-1, timeout=60, job=job)
        return out if out.exists() and out.stat().st_size > 0 else None
    except Exception:
        out.unlink(missing_ok=True)
        return None


# ============================================================================
# RECOVERY / SYNC  (was vault/recovery.py)
# ============================================================================
# Sync = recover. Search the whole Telegram channel for OUR single vault code and rebuild the library.


def need_setup():
    d = cfg_load()
    if not d["vault_code"]:
        return "Generate the vault code first (Settings -> Vault code)."
    if not d["chat_id"]:
        return "Chat / channel ID is missing (Settings -> Account)."
    if not TL_HAVE:
        return "Telethon is not installed. Run: pip install telethon  and restart run.py"
    if not tl_creds():
        return "Add your Telegram API ID + hash and log in (Settings -> Telegram account)."
    if not tl_ready(True):
        return "Telegram account is not logged in (Settings -> Telegram account)."
    return None


def index_found(chat_id, items):
    """Insert/refresh rows for files found in Telegram. Returns list of names that were new.
    Parts (PART: i/n) of one file are grouped by hash; a complete group becomes ONE library file."""
    new = []
    singles = [it for it in items if not it.get("part")]
    groups = {}
    for it in items:
        if it.get("part"):
            groups.setdefault(it["sha"] or f"{it['name']}:{it.get('total')}", []).append(it)
    with db() as c:
        def gone(it):                                    # deleted forever on purpose -> never recover it
            return c.execute("SELECT 1 FROM kv WHERE key=?", (f"gone:{chat_id}:{it['message_id']}",)).fetchone() is not None
        for it in reversed(singles):                    # oldest first, newest message wins
            if gone(it):
                continue
            row = None
            if it["sha"]:
                row = c.execute("SELECT id FROM files WHERE sha256=?", (it["sha"],)).fetchone()
            if not row:
                row = c.execute("SELECT id FROM files WHERE chat_id=? AND message_id=?",
                                (chat_id, it["message_id"])).fetchone()
            if not row:
                row = c.execute("SELECT id FROM files WHERE name=? AND size=? AND status!='backed_up'",
                                (it["name"], it["size"])).fetchone() if it["size"] else None
            if row:
                c.execute("UPDATE files SET status='backed_up', chat_id=?, message_id=?, error=NULL WHERE id=?",
                          (chat_id, it["message_id"], row["id"]))
                continue
            c.execute("INSERT INTO files(name,kind,mime,size,sha256,taken_at,added_at,status,chat_id,message_id,backed_at) "
                      "VALUES(?,?,?,?,?,?,?, 'backed_up',?,?,?)",
                      (it["name"], kind_for(it["name"], it["mime"]), it["mime"], it["size"],
                       it["sha"] or f"cloud:{chat_id}:{it['message_id']}", it["date"], it["date"],
                       chat_id, it["message_id"], it["date"]))
            new.append(it["name"])
        for g in groups.values():
            best = {}
            for it in g:
                if gone(it):
                    continue
                i = it["part"][0]
                if i not in best or it["message_id"] > best[i]["message_id"]:
                    best[i] = it
            if not best:
                continue
            n, sha = g[0]["part"][1], g[0]["sha"]
            total = int(g[0].get("total") or sum(b["size"] for b in best.values()))
            row = c.execute("SELECT * FROM files WHERE sha256=?", (sha,)).fetchone() if sha else \
                c.execute("SELECT * FROM files WHERE name=? AND size=?", (g[0]["name"], total)).fetchone()
            if len(best) == n and all(i in best for i in range(1, n + 1)):          # every part exists -> the file is complete
                first = best[1]
                if row:
                    fid = row["id"]
                    c.execute("UPDATE files SET status='backed_up', chat_id=?, message_id=?, error=NULL WHERE id=?",
                              (chat_id, first["message_id"], fid))
                else:
                    mime = mimetypes.guess_type(first["name"])[0]
                    fid = c.execute("INSERT INTO files(name,kind,mime,size,sha256,taken_at,added_at,status,chat_id,message_id,backed_at) "
                                    "VALUES(?,?,?,?,?,?,?, 'backed_up',?,?,?)",
                                    (first["name"], kind_for(first["name"], mime), mime, total,
                                     sha or f"cloud:{chat_id}:{first['message_id']}", first["date"], first["date"],
                                     chat_id, first["message_id"], first["date"])).lastrowid
                    new.append(first["name"])
                c.execute("DELETE FROM parts WHERE file_id=?", (fid,))
                pos = 0
                for i in range(1, n + 1):
                    b = best[i]
                    c.execute("INSERT INTO parts(file_id,idx,pos,plen,message_id,bot_name) VALUES(?,?,?,?,?,'Scan')",
                              (fid, i, pos, b["size"], b["message_id"]))
                    pos += b["size"]
            elif row and row["status"] != "backed_up":                              # an earlier upload was interrupted:
                plan = _plan_parts(c, row)                                          # remember which parts are already there
                if len(plan) == n:
                    for i, b in best.items():
                        c.execute("UPDATE parts SET message_id=?, bot_name='Scan' WHERE file_id=? AND idx=? AND plen=? AND message_id IS NULL",
                                  (b["message_id"], row["id"], i, b["size"]))
    return new


def scan_channel(job, full=False):
    """Incremental unless full=True. Returns (found, new_names)."""
    d = cfg_load()
    chat, code = d["chat_id"], d["vault_code"]
    key = f"scan:{chat}:{code}"
    last = 0 if full else int(kv_get(key, "0") or 0)
    search = os.environ.get("VAULT_FULL_WALK") != "1"
    job_log(job, f"Searching Telegram channel for {code} " + ("(full history)" if last == 0 else f"(new messages after #{last})")
            + (" - Telegram searches for you, only matches are downloaded" if search else " - reading every message"))
    items, top, seen = tl_scan(chat, code, last, lambda n: job_log(job, f"   {n} messages checked ..."), job, search,
                               lambda p: job_pct(job, 0, 60, p))
    new = index_found(chat, items)
    kv_set(key, max(top, last))
    job_log(job, f"{seen} messages checked: {len(items)} file(s) carry your code, {len(new)} new to this library.")
    for n in new[:100]:
        job_log(job, f"   recovered: {n}")
    if len(new) > 100:
        job_log(job, f"   ... and {len(new) - 100} more")
    return len(items), new


async def _missing_msgs(chat_id, ids, pct=None):
    """Which of these message ids no longer exist in the channel (deleted by hand in Telegram)?"""
    c = await _client()
    ent = await _entity(c, chat_id)
    gone = set()
    ids = sorted(set(ids))
    for i in range(0, len(ids), 100):
        batch = ids[i:i + 100]
        res = await c.get_messages(ent, ids=batch)
        if not isinstance(res, list):
            res = [res]
        for mid, m in zip(batch, res):
            if m is None or type(m).__name__ == "MessageEmpty":
                gone.add(mid)
        if pct:
            pct(min(100.0, (i + len(batch)) * 100.0 / max(len(ids), 1)))
    return gone


def prune_deleted(job):
    """Files whose Telegram message was deleted by hand disappear from the library too. Returns how many were removed."""
    d = cfg_load()
    chat = d["chat_id"]
    with db() as c:
        rows = c.execute("SELECT id,message_id,chat_id,cache_name FROM files WHERE status='backed_up' AND message_id IS NOT NULL").fetchall()
    rows = [r for r in rows if not r["chat_id"] or str(r["chat_id"]) == str(chat)]
    if not rows:
        return 0
    mids = {r["id"]: {int(r["message_id"])} | {int(x) for x in part_mids(r["id"])} for r in rows}
    allm = set().union(*mids.values())
    job_log(job, f"Checking {len(allm)} message(s) for files deleted in Telegram ...")
    gone = tl_run(_missing_msgs(chat, allm, lambda p: job_pct(job, 60, 70, p)), 600, job)
    if not gone:
        return 0
    # SAFETY: a temporary Telegram glitch must never wipe the library. Re-check once more, and refuse mass deletes.
    time.sleep(3)
    gone = tl_run(_missing_msgs(chat, gone, None), 600, job)
    if not gone:
        return 0
    if len(gone) > 5 and len(gone) * 4 > len(allm):
        job_log(job, f"SAFETY: {len(gone)} of {len(allm)} messages look deleted - too many, nothing was removed from the library.")
        return 0
    dead = [r for r in rows if mids[r["id"]] & gone]
    for r in dead:
        mark_gone(chat, *mids[r["id"]])
        with db() as c:
            c.execute("DELETE FROM files WHERE id=?", (r["id"],))
            c.execute("DELETE FROM parts WHERE file_id=?", (r["id"],))
        purge_local(r["id"], r["cache_name"])
    job_log(job, f"{len(dead)} file(s) deleted in Telegram were removed from the library.")
    return len(dead)


async def _orphan_thumb_scan(chat_id):
    """Every 'thumb.jpg' message (caption 'VT <file message id>') in the channel: [(thumb message id, file message id, size, date)]."""
    from telethon.tl.types import InputMessagesFilterDocument
    c = await _client()
    ent = await _entity(c, chat_id)
    out = []
    async for m in c.iter_messages(ent, search="VT", filter=InputMessagesFilterDocument, limit=None):
        mt = re.search(r"^VT\s*(\d+)\s*$", (getattr(m, "message", "") or ""), re.M)
        if not mt:
            continue
        doc = getattr(m, "document", None)
        name = ""
        for a in getattr(doc, "attributes", None) or []:
            name = getattr(a, "file_name", None) or name
        if name != "thumb.jpg":
            continue
        nm = NAME_RE.search(getattr(m, "message", "") or "")          # new thumbnails carry the real file's name in their caption
        out.append((int(m.id), int(mt.group(1)), int(getattr(doc, "size", 0) or 0), m.date.isoformat() if getattr(m, "date", None) else now(),
                    nm.group(1).strip() if nm else ""))
    return out


def recover_orphan_thumbs(job):
    """Full scan: a thumb.jpg whose real file is gone from Telegram (and from the library) is put into Recently Deleted,
    so it can be deleted from there for good. A thumbnail without a lonely thumb message is never shown; a thumb whose file still exists is left alone."""
    chat = cfg_load()["chat_id"]
    cand = tl_run(_orphan_thumb_scan(chat), 900, job)
    if not cand:
        return 0
    with db() as c:
        known = set()
        for r in c.execute("SELECT message_id, thumb_message_id FROM files").fetchall():
            known.update(int(v) for v in (r["message_id"], r["thumb_message_id"]) if v)
        for r in c.execute("SELECT message_id FROM parts WHERE message_id IS NOT NULL").fetchall():
            known.add(int(r["message_id"]))
        gone_keys = {x["key"] for x in c.execute("SELECT key FROM kv WHERE key LIKE ?", (f"gone:{chat}:%",)).fetchall()}
    cand = [x for x in cand if x[0] not in known and x[1] not in known and f"gone:{chat}:{x[0]}" not in gone_keys]
    if not cand:
        return 0
    missing = tl_run(_missing_msgs(chat, {x[1] for x in cand}, None), 600, job)          # is the real file really gone from Telegram?
    if missing:                                                                          # SAFETY: ask once more - a Telegram glitch must never make a live file's thumbnail look like a leftover
        time.sleep(3)
        missing = tl_run(_missing_msgs(chat, missing, None), 600, job)
    cand = [x for x in cand if x[1] in missing]
    n = 0
    with db() as c:
        newids = []
        for tmid, fmid, size, date, real_name in cand:
            nm = real_name or f"thumb VT {fmid}.jpg"
            cur = c.execute("INSERT OR IGNORE INTO files(name,kind,mime,size,sha256,taken_at,added_at,status,chat_id,message_id,thumb_message_id,error) "
                            "VALUES(?,?,?,?,?,?,?, 'pending',?,NULL,?,?)",
                            (nm, kind_for(nm) if real_name else "image", mimetypes.guess_type(nm)[0] or "image/jpeg", 0, f"{ORPHAN_PFX}{chat}:{tmid}", date, date,
                             chat, tmid, "File is not available"))
            if cur.rowcount:
                newids.append((cur.lastrowid, tmid))
                n += 1
    ensure_dirs()
    for fid, tmid in newids:                                  # the small thumbnail picture, so the Pending list can show it
        try:
            tl_download(chat, tmid, thumb_path(fid), timeout=120, job=job)
        except Cancelled:
            raise
        except Exception:
            pass
    if n:
        job_log(job, f"{n} thumbnail(s) without their file are now in Pending (File is not available) - open Backup -> 3 dots -> Pending and tap one to upload its file.")
    return n


def _thumb_from_file(row):
    """Best thumbnail for a file: local copy -> the original pulled back from Telegram (photos / apk) -> Telegram preview / video frames."""
    p = make_thumb(row)
    if p and not thumb_is_low(p):
        return p
    size, ext = int(row["size"] or 0), Path(row["name"]).suffix.lower()
    if row["chat_id"] and row["message_id"] and 0 < size and tl_ready() and not done_parts(row) and \
            ((row["kind"] == "image" and size <= 40 * 1024 * 1024) or (ext == ".apk" and size <= 150 * 1024 * 1024)):
        tmp = None
        try:
            ensure_dirs()
            tmp = TMP / f"rt_{row['id']}_{time.time_ns()}{ext}"
            tl_download(row["chat_id"], row["message_id"], tmp, timeout=600)
            q = make_thumb(row, tmp)
            if q:
                return q
        except Cancelled:
            raise
        except Exception:
            pass
        finally:
            if tmp:
                tmp.unlink(missing_ok=True)
    return p or get_thumb(row)


def repair_missing_thumbs(job, full=False, only_ids=None):
    """Sync / Full scan: EVERY backed-up photo, video or apk whose thumb.jpg is missing in Telegram gets a new thumbnail built from
    the file itself and uploaded (4 at a time). A thumbnail that already sits in Telegram is only linked (never uploaded twice).
    only_ids = file ids whose thumb.jpg is known to be gone from Telegram (no channel scan needed, they are rebuilt right away)."""
    d = cfg_load()
    bots, chat = cfg_bots(), d.get("chat_id")
    if not bots or not chat or not d.get("vault_code") or not tl_ready():
        return 0
    with db() as c:
        rows = c.execute("SELECT * FROM files WHERE status='backed_up' AND trashed_at IS NULL AND thumb_message_id IS NULL AND message_id IS NOT NULL "
                         "AND (kind IN ('image','video') OR LOWER(name) LIKE '%.apk') AND sha256 NOT LIKE 'cloud:orphanthumb:%' AND locked=0").fetchall()
    if only_ids is not None:
        rows = [r for r in rows if r["id"] in only_ids]
    if not rows:
        return 0
    onchat = {}
    if only_ids is None:
        try:
            onchat = {fm: tm for tm, fm, _s, _d, _n in tl_run(_orphan_thumb_scan(chat), 900, job)}     # file message id -> thumb message id
        except Cancelled:
            raise
        except Exception as e:
            job_log(job, f"Thumbnail check skipped ({e}).")
            return 0                                                                                    # unsure what is in Telegram -> never risk double uploads
    linked, todo = 0, []
    for r in rows:
        job_check(job)
        tm = onchat.get(int(r["message_id"]))
        if tm:
            with db() as c:
                c.execute("UPDATE files SET thumb_message_id=? WHERE id=?", (tm, r["id"]))
            linked += 1
        else:
            todo.append(r)
    if todo:
        job_log(job, f"Rebuilding {len(todo)} missing thumbnail(s) from their files and uploading them ...")

    def _one(r):
        ok = False
        try:
            if _thumb_from_file(r):
                for b in _bots_for(r)[:3]:
                    th = upload_thumb(r, b, int(r["message_id"]), job)
                    if th:
                        with db() as c:
                            c.execute("UPDATE files SET thumb_file_id=?, thumb_message_id=? WHERE id=?", (th[0], th[1], r["id"]))
                        ok = True
                        break
        except Cancelled:
            raise
        except Exception:
            pass
        with db() as c:
            if ok:
                c.execute("DELETE FROM kv WHERE key=?", (f"thumbup:{r['id']}",))
            else:
                c.execute("INSERT OR REPLACE INTO kv(key,value) VALUES(?,?)", (f"thumbup:{r['id']}", now()))
        return ok

    fixed = 0
    if todo:
        with concurrent.futures.ThreadPoolExecutor(max_workers=4, thread_name_prefix="thumb-fix") as ex:
            futs = [ex.submit(_one, r) for r in todo]
            try:
                for f in concurrent.futures.as_completed(futs):
                    job_check(job)
                    fixed += bool(f.result())
            except BaseException:
                for f in futs:
                    f.cancel()
                raise
    if linked or fixed:
        job_log(job, f"Thumbnails: {fixed} missing one(s) rebuilt from the file and uploaded, {linked} already in Telegram (linked).")
    return fixed


def run_sync(job, full=False):
    err = need_setup()
    if err:
        job["error"] = err
        job_log(job, err)
        return
    found, new = scan_channel(job, full)
    job_pct(job, 0, 60, 100)
    try:
        removed = prune_deleted(job)
    except Exception as e:
        removed = 0
        job_log(job, f"Could not check for deleted files: {e}")
    if full:
        try:
            recover_orphan_thumbs(job)
        except Cancelled:
            raise
        except Exception as e:
            job_log(job, f"Could not look for leftover thumbnails: {e}")
    job_pct(job, 0, 65, 100)
    try:
        repair_missing_thumbs(job, full)
    except Cancelled:
        raise
    except Exception as e:
        job_log(job, f"Could not repair missing thumbnails: {e}")
    job_pct(job, 0, 70, 100)
    # previews for recovered cloud-only files (tiny, straight from Telegram)
    # Only photos / videos (songs read their cover from the song itself when needed), only the ones that have no preview yet, and
    # never again for a file Telegram has no preview for (that retry used to cost MB on every single sync).
    with db() as c:
        rows = c.execute("SELECT * FROM files WHERE status='backed_up' AND source_path IS NULL AND cache_name IS NULL "
                         "AND message_id IS NOT NULL AND chat_id IS NOT NULL AND kind IN ('image','video')").fetchall()
        nothumb = {x["key"] for x in c.execute("SELECT key FROM kv WHERE key LIKE 'nothumb%'").fetchall()}
    todo = [r for r in rows if not thumb_path(r["id"]).exists() and not done_parts(r)
            and (f"nothumbm:{r['id']}" if r["thumb_message_id"] else f"nothumb:{r['id']}") not in nothumb]
    full_ids = {r["id"] for r in todo if r["thumb_message_id"]}
    job["total"] = len(todo)
    if todo:
        job_log(job, f"Fetching {len(todo)} preview(s), {THUMB_PAR} at a time ...")
        ensure_dirs()

        def _tick():
            with LOCK:
                job["done"] += 1
            job_pct(job, 70, 100, job["done"] * 100.0 / max(job["total"], 1))
        items = [(r["chat_id"], int(r["thumb_message_id"] or r["message_id"]), thumb_path(r["id"]), r["id"], bool(r["thumb_message_id"])) for r in todo]
        try:
            res = tl_run(_thumbs_bulk(items, _tick), 3600, job)
        except Cancelled:
            raise
        except Exception as e:
            res = {}
            job_log(job, f"Previews stopped: {e}")
        none = [(("nothumbm:" if k in full_ids else "nothumb:") + str(k), "1") for k, v in res.items() if v is False]
        if none:
            with db() as c:
                c.executemany("INSERT OR REPLACE INTO kv(key,value) VALUES(?,?)", none)
    try:                                                          # thumb.jpg message that is gone from Telegram -> rebuilt from the file and uploaded once
        gone = {k for k, v in (res or {}).items() if v is False and k in full_ids} if todo else set()
        if gone:
            with db() as c:
                for k in gone:
                    c.execute("UPDATE files SET thumb_message_id=NULL, thumb_file_id=NULL WHERE id=?", (k,))
                    c.execute("DELETE FROM kv WHERE key=?", (f"nothumbm:{k}",))
            repair_missing_thumbs(job, full, only_ids=gone)
    except Cancelled:
        raise
    except Exception as e:
        job_log(job, f"Could not rebuild vanished thumbnails: {e}")
    try:                                                          # files that have a local copy but no thumbnail picture yet: built now (no Telegram)
        with db() as c:
            lrows = c.execute("SELECT * FROM files WHERE status='backed_up' AND trashed_at IS NULL AND locked=0 AND kind IN ('image','video') "
                              "AND (source_path IS NOT NULL OR cache_name IS NOT NULL)").fetchall()
        for r in lrows:
            job_check(job)
            if not thumb_path(r["id"]).exists():
                make_thumb(r)
    except Cancelled:
        raise
    except Exception as e:
        job_log(job, f"Could not build local thumbnails: {e}")
    job_pct(job, 0, 100, 100)
    job["result"] = {"found": found, "recovered": len(new), "removed": removed}
    job_log(job, f"Sync complete: {found} file(s) found on Telegram, {len(new)} recovered, {removed} removed (deleted in Telegram).")


# ============================================================================
# SCANNER  (was vault/scanner.py)
# ============================================================================
# Backup folders (on the device that runs this server): find photos/videos and register them.

MEDIA_EXT = IMAGE_EXT | VIDEO_EXT


def _is_excluded(full, ex):
    full = full.rstrip("/")
    base = os.path.basename(full).lower()
    for e in ex:
        if "/" in e:
            if full == e or full.startswith(e + "/"):
                return True
        elif base == e.lower():
            return True
    return False


def walk(folder):
    try:
        ex = list(cfg_get("excluded_folders") or [])
    except Exception:
        ex = []
    if ex and _is_excluded(str(folder), ex):
        return
    for root, dirs, names in os.walk(folder):
        dirs[:] = [d for d in dirs if not d.startswith(".") and not (ex and _is_excluded(os.path.join(root, d), ex))]
        for n in names:
            if not n.startswith(".") and Path(n).suffix.lower() in MEDIA_EXT:
                yield Path(root) / n


def register(path, folder=None, check=None):
    """Add one local file to the index. Returns 'new' | 'known' | 'adopted'."""
    st = path.stat()
    with db() as c:
        row = c.execute("SELECT id,mtime,size FROM files WHERE source_path=?", (str(path),)).fetchone()
        if row and row["mtime"] == st.st_mtime and row["size"] == st.st_size:
            if folder:
                c.execute("UPDATE files SET folder=? WHERE id=?", (folder, row["id"]))
            return "known"
    digest, size = sha256_file(path, check=check)
    mime = mimetypes.guess_type(path.name)[0]
    with db() as c:
        same = c.execute("SELECT id FROM files WHERE sha256=?", (digest,)).fetchone()
        if not same:   # file recovered from Telegram earlier without a hash in its caption
            same = c.execute("SELECT id FROM files WHERE sha256 LIKE 'cloud:%' AND name=? AND size=?",
                             (path.name, size)).fetchone()
        if same:
            c.execute("UPDATE files SET sha256=?, source_path=?, folder=?, mtime=? WHERE id=?",
                      (digest, str(path), folder, st.st_mtime, same["id"]))
            return "adopted"
        c.execute("""INSERT INTO files(name,kind,mime,size,sha256,source_path,folder,mtime,taken_at,added_at,status)
                     VALUES(?,?,?,?,?,?,?,?,?,?,'pending')""",
                  (path.name, kind_for(path.name, mime), mime, size, digest, str(path), folder, st.st_mtime,
                   iso_from_ts(st.st_mtime), now()))
    return "new"


def run_scan(job):
    folders = cfg_get("folders")
    if not folders:
        job["error"] = "No backup folder added yet (Settings -> Manage Backup Folders)."
        return
    paths = []
    for f in folders:
        if not f["enabled"]:
            continue
        if not Path(f["path"]).is_dir():
            job_log(job, f"Folder not found: {f['path']}")
            continue
        paths += [(p, f["path"]) for p in walk(f["path"])]
    job["total"] = len(paths)
    new = 0
    for p, folder in paths:
        job_check(job)
        try:
            if register(p, folder, lambda: job_check(job)) != "known":
                new += 1
        except Cancelled:
            raise
        except Exception as e:
            job_log(job, f"Skipped {p.name}: {e}")
        job["done"] += 1
    job_log(job, f"Folder scan finished: {len(paths)} file(s) checked, {new} new/updated.")


# ============================================================================
# BACKUP ENGINE  (was vault/backup.py)
# ============================================================================
# Upload engine: strictly one send at a time, bots used in rotation (bot pool), rate-limit aware.

BOT_API_LIMIT = 49 * 1024 * 1024
MAX_BOTS = int(os.environ.get("VAULT_MAX_BOTS", "200"))        # bots kept in the pool (primary not counted)
BOT_PARALLEL_MAX = max(1, int(os.environ.get("VAULT_PARALLEL_MAX", "200")))   # every bot uploads at the same time (more bots = more speed)
BOT_STATS = {}              # token -> live health numbers of that bot (ok / fail counts, rate-limit end, last error)
BOT_STATS_LK = threading.Lock()


def _bs(token):
    with BOT_STATS_LK:
        return BOT_STATS.setdefault(token, {"ok": 0, "fail": 0, "limit_until": 0.0, "last_err": "", "err_at": 0.0,
                                             "dead": False, "last_ok": 0.0, "live": None, "live_at": 0.0})


TG_COOLDOWN = [0.0]         # shared: when Telegram says "slow down", ALL bots wait together (no thundering herd)


SEL_ONLY = [None]      # set of file ids: while a "Back up selected" job runs, only these files are uploaded (None = everything)


def pending_rows():
    enabled = [f["path"] for f in cfg_get("folders") if f["enabled"]]
    with db() as c:
        rows = c.execute("SELECT * FROM files WHERE status IN ('pending','failed') AND skip=0 AND trashed_at IS NULL ORDER BY taken_at DESC").fetchall()
    # files that came from a folder which is switched off are "excluded"
    rows = [r for r in rows if (not r["folder"] or r["folder"] in enabled) and not _is_orphan(r)]
    only = SEL_ONLY[0]
    if only is not None:
        rows = [r for r in rows if r["id"] in only]
    return rows


def strip_gps(src, name):
    """Copy of a JPEG without GPS EXIF (needs Pillow). Returns Path or None."""
    try:
        from PIL import Image
        if Path(name).suffix.lower() not in (".jpg", ".jpeg"):
            return None
        ensure_dirs()
        with Image.open(src) as im:
            exif = im.getexif()
            if 0x8825 not in exif:
                return None
            del exif[0x8825]
            out = TMP / f"strip_{time.time_ns()}.jpg"
            im.save(out, "JPEG", exif=exif.tobytes(), quality="keep" if im.format == "JPEG" else 95)
            return out
    except Exception:
        return None


BIG_LOCK = threading.Lock()
BOT_FATAL = ("unauthorized", "forbidden", "chat not found", "not enough rights", "bot was kicked",
             "not a member", "need administrator", "invalid token")


def wait_for_battery(job):
    """Runs before every file: waits while battery is low / not charging (Charging only) / not on Wi-Fi (Wi-Fi only).
    The backup continues by itself the moment the condition is right again."""
    last = None
    while True:
        why = backup_block_reason()
        if not why:
            if last:
                job_log(job, "Condition is right again - backup continues.")
            return
        if why != last:
            job_log(job, why)
            last = why
        for _ in range(10):
            job_check(job)
            time.sleep(2)


def _live_init(job, total_bytes, total_files):
    with LOCK:
        job["live"] = {"bytes_total": int(total_bytes), "bytes_done": 0, "files_total": total_files, "files_done": 0,
                       "ok": 0, "failed": 0, "speed": 0.0, "eta": None, "pct": 0.0, "started": time.time(),
                       "active": {}, "_w": []}


def _live_calc(L):
    L["pct"] = min(100.0, L["bytes_done"] * 100.0 / max(L["bytes_total"], 1))
    sp = L["speed"]
    L["eta"] = int(max(L["bytes_total"] - L["bytes_done"], 0) / sp) if sp > 1 else None


def _make_track(job, slot):
    def track(n):
        if job["cancel"]:
            raise Cancelled()                    # aborts the running upload within one chunk
        if slot.get("cancel"):
            raise FileCancelled()                # only this file is cancelled
        if n <= 0:
            return
        with LOCK:
            L = job["live"]
            L["bytes_done"] += n
            slot["sent"] = min(slot["size"], slot["sent"] + n)
            t = time.time()
            w = L["_w"]
            w.append((t, L["bytes_done"]))
            while len(w) > 2 and t - w[0][0] > 8:
                w.pop(0)
            if t - w[0][0] >= 0.5:
                L["speed"] = (L["bytes_done"] - w[0][1]) / (t - w[0][0])
            _live_calc(L)
    return track


def bot_send(bot, d, path, fname, caption, track, job, file_range=None):
    """One Bot-API sendDocument (a whole small file, or ONE byte range = one part of a big file), with retries."""
    res = None
    for attempt in range(5):
        try:
            res = tgapi_call(bot["token"], "sendDocument",
                             {"chat_id": d["chat_id"], "caption": caption, "disable_notification": "true"},
                             file_path=str(path), upload_name=fname, timeout=900, progress=track, job=job,
                             file_range=file_range)
            break
        except TgRetry as e:
            if attempt == 4:
                raise
            job_log(job, f"   Telegram rate limit - waiting {e.retry_after + 1}s")
            _bs(bot["token"])["limit_until"] = time.time() + e.retry_after + 1
            TG_COOLDOWN[0] = max(TG_COOLDOWN[0], time.time() + e.retry_after + 1)
            job_nap(job, e.retry_after + 1)
        except RuntimeError as e:
            if "Network error" in str(e) and attempt < 2:
                job_log(job, "   network hiccup - retrying")
                job_nap(job, 3)
                continue
            raise
    _st = _bs(bot["token"]); _st["ok"] += 1; _st["last_ok"] = time.time(); _st["dead"] = False
    return res["message_id"]


def send_one(row, bot, job, d, track):
    """A file up to 48 MB: one message."""
    src = restore_local(row)
    sha = row["sha256"] if not row["sha256"].startswith("cloud:") else None
    caption = make_caption(d["vault_code"], row["name"], sha)
    tmp = strip_gps(src, row["name"]) if d["strip_location"] and row["kind"] == "image" else None
    try:
        return bot_send(bot, d, tmp or src, row["name"], caption, track, job), bot["name"]
    finally:
        if tmp:
            tmp.unlink(missing_ok=True)


def send_part(row, part, bot, job, d, track):
    """ONE part of a big file: the bytes are read straight from the original file (offset + length), no temp copy."""
    src = restore_local(row)
    if src.stat().st_size != int(row["size"] or 0):
        raise RuntimeError("The file changed on disk since it was scanned - press Back up now again")
    sha = row["sha256"] if not row["sha256"].startswith("cloud:") else None
    caption = make_caption(d["vault_code"], row["name"], sha, (part["idx"], part["n"]), row["size"])
    fname = f"{safe_name(row['name'])}.part{part['idx']:03d}"
    return bot_send(bot, d, src, fname, caption, track, job, (part["pos"], part["len"]))


def run_backup(job):
    d = cfg_load()
    if not d["vault_code"]:
        job["error"] = "Generate the vault code first (Settings -> Vault code)."
        return
    bots = cfg_bots()
    if not bots or not d["chat_id"]:
        job["error"] = "Add the bot token and chat ID first (Settings -> Account)."
        return
    # 1) look at Telegram first so nothing is uploaded twice (this also finds parts of an earlier, interrupted upload)
    if tl_ready():
        try:
            scan_channel(job)
        except Exception as e:
            job_log(job, f"History check failed ({e}); continuing without it.")
    # 2) upload: every bot is its own worker, so N bots = N uploads at the same time
    rows = pending_rows()
    job["total"], job["done"] = len(rows), 0
    run_bots = bots
    if len(bots) > BOT_PARALLEL_MAX:                       # many bots: a fresh group of them works each minute
        off = int(time.time() // 60) % len(bots)
        run_bots = (bots[off:] + bots[:off])[:BOT_PARALLEL_MAX]
    job_log(job, f"{len(rows)} file(s) waiting for backup, {len(run_bots)} of {len(bots)} bot(s) uploading in parallel.")
    if not rows:
        job_log(job, "Nothing to upload.")
        return
    # 3) files over 48 MB become numbered parts; parts that already reached Telegram are skipped (resume)
    tasks, fin, instant, total_bytes, utasks = [], {}, [], 0, []
    for r in rows:
        size = int(r["size"] or 0)
        if size > SINGLE_MAX:
            allp = get_parts(r["id"])
            if allp and all(p["message_id"] for p in allp):          # an older upload already finished as parts
                instant.append(r)
                continue
            if allp:
                with db() as c:
                    c.execute("DELETE FROM parts WHERE file_id=?", (r["id"],))
            job_log(job, f"   {r['name']}: over 48 MB - uploaded by your Telegram account as ONE file")
            utasks.append({"row": r, "part": None})
            total_bytes += size
        else:
            tasks.append({"row": r, "part": None})
            total_bytes += size
    _live_init(job, total_bytes, len(rows))
    q = queue.Queue()
    for t in tasks:
        q.put(t)
    uq = queue.Queue()
    for t in utasks:
        uq.put(t)
    st = {"ok": 0, "bad": 0, "streak": 0}
    thumb_ex = concurrent.futures.ThreadPoolExecutor(max_workers=4, thread_name_prefix="thumb-up")
    dead, stop = set(), threading.Event()
    gate, last_start = threading.Lock(), [0.0]
    gap = 0.15 if d["fast_upload"] else 1.5

    def file_end(row, kind, msg="", bot=None, mid=None):
        """A whole file is settled. kind = ok | fail | skip."""
        if kind == "fail":
            with db() as c:
                c.execute("UPDATE files SET status='failed', error=?, tries=tries+1 WHERE id=?", (msg[:300], row["id"]))
            log_problem("Upload", f"{row['name']} - {_friendly_error(msg) or msg}")
        elif kind == "ok" and bot and mid and not job["cancel"] and \
                (row["kind"] in ("image", "video") or row["name"].lower().endswith(".apk")):
            def _th(row=row, bot=bot, mid=mid):
                th = upload_thumb(row, bot, mid, job)        # separate thumb.jpg message, like the Android app
                if th:
                    with db() as c:
                        c.execute("UPDATE files SET thumb_file_id=?, thumb_message_id=? WHERE id=?", (th[0], th[1], row["id"]))
                    old = row["thumb_message_id"]
                    if old and int(old) != int(th[1]):               # the file came late (was a 'File is not available' thumbnail): drop the old lonely thumb
                        cid = cfg_load()["chat_id"]
                        try:
                            tl_delete(cid, [int(old)])
                        except Exception:
                            try:
                                tgapi_call(bot["token"], "deleteMessage", {"chat_id": cid, "message_id": int(old)})
                            except Exception:
                                pass
            try:
                thumb_ex.submit(_th)                         # background: the bot immediately starts its next file
            except RuntimeError:
                pass
        with LOCK:
            L = job["live"]
            L["files_done"] += 1
            job["done"] += 1
            if kind == "ok":
                st["ok"] += 1
                st["streak"] = 0
                L["ok"] += 1
            elif kind == "fail":
                st["bad"] += 1
                st["streak"] += 1
                L["failed"] += 1
        if kind == "fail" and st["streak"] >= max(8, len(run_bots) * 2):
            job["error"] = "Stopped after many failures in a row - check bot token / admin rights / internet."
            stop.set()

    def settle(task, kind, slot=None, bot=None, mid=None, msg=""):
        """One upload task (a file or a part) is over. kind = ok | skip | cancel | fail."""
        row, part = task["row"], task["part"]
        plen = part["len"] if part else int(row["size"] or 0)
        sent = slot["sent"] if slot else 0
        with LOCK:
            L = job["live"]
            if kind == "ok":
                L["bytes_done"] += max(0, plen - sent)
            else:
                L["bytes_done"] = max(0, L["bytes_done"] - sent)
                L["bytes_total"] = max(0, L["bytes_total"] - plen)
            _live_calc(L)
            if part:
                fs = fin[row["id"]]
                fs["left"] -= 1
                if kind != "ok" and (not fs["bad"] or (kind == "fail" and fs["bad"] != "fail")):
                    fs["bad"], fs["msg"] = kind, msg
                last, bad, fmsg = fs["left"] == 0, fs["bad"], fs["msg"]
            else:
                last, bad, fmsg = True, (None if kind == "ok" else kind), msg
        if not last:
            return
        if not bad:
            if part:
                mid = finalize_chunked(row, d["chat_id"])      # all parts are in Telegram -> one backed-up file
            file_end(row, "ok", bot=bot, mid=mid)
        else:
            file_end(row, "fail" if bad == "fail" else "skip", msg=fmsg)

    def worker(idx, bot):
        key, last_end = str(idx), 0.0
        while not stop.is_set() and not job["cancel"]:
            try:
                task = q.get_nowait()
            except queue.Empty:
                return
            row, part = task["row"], task["part"]
            if bot["token"] in dead:
                q.put(task)
                return
            try:
                wait_for_battery(job)
            except Cancelled:
                q.put(task)
                return
            with db() as c:
                fresh = c.execute("SELECT status, skip, trashed_at FROM files WHERE id=?", (row["id"],)).fetchone()
            if (not fresh or fresh["status"] == "backed_up" or fresh["skip"] or fresh["trashed_at"]
                    or (part and fin[row["id"]]["bad"])):
                settle(task, "skip")
                continue
            wait = gap - (time.time() - last_end)
            if wait > 0:
                try:
                    job_nap(job, wait)
                except Cancelled:
                    q.put(task)
                    return
            cd = TG_COOLDOWN[0] - time.time()
            if cd > 0:
                try:
                    job_nap(job, min(cd, 60))
                except Cancelled:
                    q.put(task)
                    return
            with gate:                      # tiny floor between sends of ALL bots (shared channel)
                w = (0.08 if d["fast_upload"] else 0.35) - (time.time() - last_start[0])
                if w > 0:
                    time.sleep(w)
                last_start[0] = time.time()
            plen = part["len"] if part else int(row["size"] or 0)
            label = row["name"] + (f"  (part {part['idx']}/{part['n']})" if part else "")
            slot = {"name": label, "size": plen, "sent": 0, "bot": bot["name"], "cancel": False}
            with LOCK:
                job["live"]["active"][key] = slot
            job_log(job, f"-> [{bot['name']}] {label}")
            track = _make_track(job, slot)
            outcome, mid, err = "ok", None, ""
            try:
                if part:
                    mid = send_part(row, part, bot, job, d, track)
                    with db() as c:                              # saved at once: a stop / crash never loses a finished part
                        c.execute("UPDATE parts SET message_id=?, bot_name=? WHERE file_id=? AND idx=?",
                                  (mid, bot["name"], row["id"], part["idx"]))
                else:
                    mid, who = send_one(row, bot, job, d, track)
                    with db() as c:
                        c.execute("UPDATE files SET status='backed_up', chat_id=?, message_id=?, bot_name=?, error=NULL, "
                                  "backed_at=? WHERE id=?", (d["chat_id"], mid, who, now(), row["id"]))
            except Cancelled:
                return                                   # stopped by the user: the file / part simply stays pending
            except FileCancelled:                        # user pressed 'x' on this one upload: skip it, carry on with the others
                with db() as c:
                    c.execute("UPDATE files SET skip=1, error=NULL WHERE id=? AND status!='backed_up'", (row["id"],))
                outcome = "cancel"
                job_log(job, f"   cancelled: {label}")
            except Exception as e:
                if job["cancel"]:
                    return
                msg = str(e)
                bot_fault = any(k in msg.lower() for k in BOT_FATAL)
                _st = _bs(bot["token"]); _st["fail"] += 1; _st["last_err"] = msg[:160]; _st["err_at"] = time.time()
                if bot_fault:
                    _st["dead"] = True
                if bot_fault and len([b for b in bots if b["token"] not in dead]) > 1:
                    dead.add(bot["token"])
                    with LOCK:
                        job["live"]["bytes_done"] = max(0, job["live"]["bytes_done"] - slot["sent"])
                    job_log(job, f"   bot {bot['name']} cannot post here ({msg}) - the other bots continue")
                    q.put(task)
                    return
                outcome, err = "fail", msg
                job_log(job, f"   failed: {msg}")
            finally:
                with LOCK:
                    job["live"]["active"].pop(key, None)
                last_end = time.time()
            settle(task, outcome, slot, bot, mid, err)

    def user_worker(idx):
        """Files over 48 MB: no bot - the logged-in Telegram account uploads the whole file (up to 2 GB / 4 GB Premium)."""
        key = f"u{idx}"
        while not stop.is_set() and not job["cancel"]:
            try:
                task = uq.get_nowait()
            except queue.Empty:
                return
            row = task["row"]
            try:
                wait_for_battery(job)
            except Cancelled:
                uq.put(task)
                return
            with db() as c:
                fresh = c.execute("SELECT status, skip, trashed_at FROM files WHERE id=?", (row["id"],)).fetchone()
            if not fresh or fresh["status"] == "backed_up" or fresh["skip"] or fresh["trashed_at"]:
                settle(task, "skip")
                continue
            plen = int(row["size"] or 0)
            slot = {"name": row["name"] + "  (account)", "size": plen, "sent": 0, "bot": "Account", "cancel": False}
            with LOCK:
                job["live"]["active"][key] = slot
            job_log(job, f"-> [Account] {row['name']}")
            if not cryptg_active():
                job_log(job, "   slow: 'cryptg' is not active, so Telegram encryption runs in slow Python (~100-300 KB/s). "
                             "Run: pip install cryptg  (Termux: pkg install rust clang make; pip install cryptg) and restart the server.")
            track = _make_track(job, slot)
            outcome, mid, err = "ok", None, ""
            try:
                if not tl_ready():
                    raise RuntimeError("Log in with your Telegram account (Settings) - files over 48 MB are uploaded by your account")
                src = restore_local(row)
                sha = row["sha256"] if not row["sha256"].startswith("cloud:") else None
                caption = make_caption(d["vault_code"], row["name"], sha)
                mid = tl_send_big(d["chat_id"], src, row["name"], caption, track, job)
                with db() as c:
                    c.execute("UPDATE files SET status='backed_up', chat_id=?, message_id=?, bot_name='Account', error=NULL, "
                              "backed_at=? WHERE id=?", (d["chat_id"], mid, now(), row["id"]))
            except Cancelled:
                return
            except FileCancelled:
                with db() as c:
                    c.execute("UPDATE files SET skip=1, error=NULL WHERE id=? AND status!='backed_up'", (row["id"],))
                outcome = "cancel"
                job_log(job, f"   cancelled: {row['name']}")
            except Exception as e:
                if job["cancel"]:
                    return
                outcome, err = "fail", str(e)
                job_log(job, f"   failed: {err}")
            finally:
                with LOCK:
                    job["live"]["active"].pop(key, None)
            settle(task, outcome, slot, run_bots[0], mid, err)

    for r in instant:                                    # every part was already uploaded earlier: just commit the file
        file_end(r, "ok", bot=run_bots[0], mid=finalize_chunked(r, d["chat_id"]))
    streams = max(1, min(4, int(os.environ.get("VAULT_STREAMS_PER_BOT", "1") or 1)))    # uploads per bot at once (computers: 2-3)
    threads = [threading.Thread(target=worker, args=(i * streams + k, b), daemon=True, name=f"upload-{i}-{k}")
               for i, b in enumerate(run_bots) for k in range(streams)]
    ustreams = max(1, min(4, int(os.environ.get("VAULT_ACCOUNT_STREAMS", "2") or 2)))        # big files uploaded at once by the account
    threads += [threading.Thread(target=user_worker, args=(i,), daemon=True, name=f"upload-acc-{i}") for i in range(ustreams if utasks else 0)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    thumb_ex.shutdown(wait=True)
    if job["cancel"]:
        raise Cancelled()
    job_log(job, f"Backup finished: {st['ok']} uploaded, {st['bad']} failed.")
    if q.qsize() or uq.qsize():
        job_log(job, f"{q.qsize() + uq.qsize()} upload task(s) were not finished (stopped early) - they stay pending and continue next time.")
    if st["bad"] and not job["error"]:
        job["error"] = f"{st['bad']} file(s) failed - see log."
    return st["ok"]


def run_full(job):
    """'Back up now': scan folders, then upload."""
    if cfg_get("folders"):
        run_scan(job)
        job["done"], job["total"] = 0, 0
        job["error"] = None
    idle, uploaded = 0, 0
    for rnd in range(1, 31):                                  # failed files are retried automatically, no button needed
        ok = run_backup(job) or 0
        uploaded += ok
        with db() as c:
            n_failed = c.execute("SELECT COUNT(*) n FROM files WHERE status='failed' AND skip=0 AND trashed_at IS NULL").fetchone()["n"]
        if not n_failed or job["cancel"]:
            break
        idle = 0 if ok else idle + 1
        if idle >= 4:                                         # 4 rounds without a single success: give up for now (watchdog tries again later)
            break
        job_log(job, f"{n_failed} failed file(s) - automatic retry in {min(10 * rnd, 60)}s (round {rnd}) ...")
        job_nap(job, min(10 * rnd, 60))
        job["error"] = None
        job["done"], job["total"] = 0, 0
    else:
        pass
    with db() as c:
        left = c.execute("SELECT COUNT(*) n FROM files WHERE status='failed' AND skip=0 AND trashed_at IS NULL").fetchone()["n"]
    if left:
        job["error"] = f"{left} file(s) still failed - will retry automatically."
    else:
        job["error"] = None
    if uploaded and not left and not job["cancel"]:           # everything is in the cloud -> clear the local copies by itself
        with db() as c:
            waiting = c.execute("SELECT COUNT(*) n FROM files WHERE status IN ('pending','failed') AND skip=0 AND trashed_at IS NULL AND sha256 NOT LIKE 'cloud:orphanthumb:%'").fetchone()["n"]
        if not waiting:
            try:
                freed = wipe_local()
                job_log(job, f"Local copies removed automatically ({human_size(freed)} freed).")
            except Exception as e:
                job_log(job, f"Automatic cleanup skipped: {e}")


def run_selected(job, ids):
    """Backup page -> 3-dot menu -> Pending / Failed -> 'Backup start': upload ONLY the ticked files (no folder scan)."""
    ids = set(int(i) for i in ids)
    SEL_ONLY[0] = ids
    try:
        idle = 0
        for rnd in range(1, 4):
            ok = run_backup(job) or 0
            with db() as c:
                q = ",".join("?" * len(ids))
                left = c.execute(f"SELECT COUNT(*) n FROM files WHERE status='failed' AND skip=0 AND trashed_at IS NULL AND id IN ({q})", tuple(ids)).fetchone()["n"]
            if not left or job["cancel"]:
                break
            idle = 0 if ok else idle + 1
            if idle >= 2:
                break
            job_log(job, f"{left} selected file(s) failed - retry in {10 * rnd}s (round {rnd}) ...")
            job_nap(job, 10 * rnd)
            job["error"] = None
            job["done"], job["total"] = 0, 0
        with db() as c:
            q = ",".join("?" * len(ids))
            left = c.execute(f"SELECT COUNT(*) n FROM files WHERE status='failed' AND skip=0 AND trashed_at IS NULL AND id IN ({q})", tuple(ids)).fetchone()["n"]
        job["error"] = f"{left} selected file(s) still failed - see Failed / Error list." if left else None
    finally:
        SEL_ONLY[0] = None


# ── vault code pinned in the channel ─────────────────────────────────────
# The code always stays PINNED in the Telegram channel (re-pinned automatically if it is unpinned or replaced).
# After a Telegram login the app reads the pinned message and takes the code from it - no copy/paste.
PIN_TEXT = "VAULT BACKUP\nCODE: {code}\n\nThis message holds the vault code of this channel. Keep it pinned."


def _code_in(text):
    m = CODE_RE.search(text or "")
    return vc_normalize(m.group(1)) if m else None


async def _pinned_code_tl(chat_id):
    from telethon.tl.types import InputMessagesFilterPinned
    c = await _client()
    ent = await _entity(c, chat_id)
    for m in await c.get_messages(ent, limit=10, filter=InputMessagesFilterPinned()):
        code = _code_in(getattr(m, "message", "") or "")
        if code:
            return code
    return None


async def _any_code_tl(chat_id):
    """No pin? Every uploaded file carries 'CODE: TV-...' in its caption - take it from the newest such message."""
    c = await _client()
    ent = await _entity(c, chat_id)
    for kw in ("VAULT BACKUP", None):                          # server-side search first, then the latest 400 messages
        try:
            it = c.iter_messages(ent, search=kw, limit=100) if kw else c.iter_messages(ent, limit=400, wait_time=0)
            async for m in it:
                code = _code_in(getattr(m, "message", "") or "")
                if code:
                    return code
        except Exception:
            continue
    return None


def pinned_code(chat_id):
    """The vault code of this channel: from the pinned message, else from any file caption in the chat. Telegram login first, bot (pin only) as fallback."""
    if tl_ready():
        try:
            code = tl_run(_pinned_code_tl(chat_id), 40)
            if code:
                return code
            code = tl_run(_any_code_tl(chat_id), 60)
            if code:
                return code
        except Exception:
            pass
    for b in cfg_bots():
        try:
            pm = (tgapi_call(b["token"], "getChat", {"chat_id": chat_id}, timeout=30) or {}).get("pinned_message") or {}
            return _code_in(pm.get("text") or pm.get("caption") or "")
        except Exception:
            continue
    return None


def adopt_code_from_pin():
    """Take the code from the channel's pin. Only when this is safe: no local code yet, or nothing was uploaded/queued under the old one.
    Returns the adopted code or None."""
    d = cfg_load()
    if not d["chat_id"]:
        return None
    found = pinned_code(d["chat_id"])
    if not found or found == d["vault_code"]:
        return None
    if d["vault_code"]:
        with db() as c:
            n = c.execute("SELECT COUNT(*) n FROM files WHERE message_id IS NOT NULL OR status IN ('pending','failed')").fetchone()["n"]
        if n:
            return None
    cfg_set_code(found)
    return found


def ensure_code_pin():
    """Make sure OUR code message is pinned in the channel; (re)send + pin it when it is not."""
    d = cfg_load()
    code, chat = d["vault_code"], d["chat_id"]
    bots = cfg_bots()
    if not (code and chat and bots):
        return False
    tok = bots[0]["token"]
    try:
        pm = (tgapi_call(tok, "getChat", {"chat_id": chat}, timeout=30) or {}).get("pinned_message") or {}
        if _code_in(pm.get("text") or pm.get("caption") or "") == code:
            return True
        mid = None
        saved = kv_get(f"codepin:{chat}:{code}")
        if saved and str(saved).isdigit():
            mid = int(saved)                                  # our old code message may still exist: just pin it again
        if mid:
            try:
                tgapi_call(tok, "pinChatMessage", {"chat_id": chat, "message_id": mid, "disable_notification": True}, timeout=30)
                return True
            except Exception:
                mid = None
        r = tgapi_call(tok, "sendMessage", {"chat_id": chat, "text": PIN_TEXT.format(code=code)}, timeout=30)
        mid = r["message_id"]
        kv_set(f"codepin:{chat}:{code}", mid)
        tgapi_call(tok, "pinChatMessage", {"chat_id": chat, "message_id": mid, "disable_notification": True}, timeout=30)
        return True
    except Exception:
        return False                                          # e.g. bot has no 'Pin messages' right - tried again next round


def code_pin_watchdog():
    """Every 30 s: no code yet -> try to take it from the channel pin; code present -> keep it pinned (checked every 5 min)."""
    last = 0.0
    while True:
        time.sleep(30)
        try:
            d = cfg_load()
            if not d["chat_id"]:
                continue
            if not d["vault_code"]:
                adopt_code_from_pin()
                continue
            if time.time() - last >= 300:
                last = time.time()
                ensure_code_pin()
        except Exception:
            pass


def code_pin_kick():
    threading.Thread(target=lambda: (adopt_code_from_pin(), ensure_code_pin()), daemon=True).start()


def auto_clear_watchdog():
    """While 'Auto remove local copies' is ON: run Remove local copies every minute (never while a job runs or files wait for upload)."""
    while True:
        time.sleep(60)
        try:
            if not cfg_get("auto_clear_local"):
                continue
            with LOCK:
                if any(j["status"] in ("queued", "running") for j in JOBS.values()):
                    continue
            with db() as c:
                waiting = c.execute("SELECT COUNT(*) n FROM files WHERE status IN ('pending','failed') AND skip=0 AND trashed_at IS NULL AND sha256 NOT LIKE 'cloud:orphanthumb:%'").fetchone()["n"]
            if not waiting:
                wipe_local()
        except Exception:
            pass


# ============================================================================
# OCR  - text written inside photos (notes, documents) -> searchable
# ============================================================================
# Uses the "tesseract" program of the device that runs this server (Termux: pkg install tesseract).
# Without it nothing breaks: the photo search simply works on names / dates as before.
_OCR = {"bin": None, "langs": "", "checked": 0.0, "skip": {}, "last_err": ""}
_OCR_LOCK = threading.Lock()


def ocr_engine():
    """(path of tesseract, '+'-joined languages) or (None, ''). Re-checked every 5 minutes."""
    with _OCR_LOCK:
        if time.time() - _OCR["checked"] < 300:
            return _OCR["bin"], _OCR["langs"]
        exe = shutil.which("tesseract")
        langs = ""
        if exe:
            try:
                out = subprocess.run([exe, "--list-langs"], capture_output=True, text=True, timeout=15)
                have = {x.strip() for x in (out.stdout + "\n" + out.stderr).splitlines()[1:] if x.strip() and " " not in x.strip()}
                pick = [l for l in ("eng", "hin") if l in have]      # English + Hindi (if its language file is installed)
                other = sorted(have - {"osd", "equ"})
                langs = "+".join(pick) if pick else (other[0] if other else "eng")
            except Exception:
                langs = "eng"
        _OCR.update(bin=exe, langs=langs, checked=time.time())
        return exe, langs


def ocr_read(path, exe, langs):
    """Text of one picture ('' when nothing readable). Raises on a real failure."""
    from PIL import Image, ImageOps
    TMP.mkdir(parents=True, exist_ok=True)
    tmp = TMP / f"ocr-{threading.get_ident()}-{time.time_ns()}.png"
    try:
        with Image.open(path) as im:
            im = ImageOps.exif_transpose(im).convert("L")
            w, h = im.size
            big = max(w, h)
            if big > 2400:                                          # phone photos are huge: 2400 px is plenty for text and 4x faster
                k = 2400 / big
                im = im.resize((max(1, int(w * k)), max(1, int(h * k))))
            elif big < 900:
                k = 1400 / big
                im = im.resize((max(1, int(w * k)), max(1, int(h * k))))
            im = ImageOps.autocontrast(im)
            im.save(tmp, "PNG")
        env = dict(os.environ, OMP_THREAD_LIMIT="1")                # one core only: the phone stays cool and fast
        r = subprocess.run([exe, str(tmp), "stdout", "-l", langs, "--psm", "3"], capture_output=True, timeout=120, env=env)
        txt = r.stdout.decode("utf-8", "ignore")
        if r.returncode != 0 and not txt.strip():
            raise RuntimeError((r.stderr.decode("utf-8", "ignore") or "tesseract failed")[:200])
        return re.sub(r"\s+", " ", txt).strip()[:20000]
    finally:
        tmp.unlink(missing_ok=True)


def ocr_batch(limit=6):
    """Reads up to `limit` photos that were not read yet. Returns how many were processed."""
    d = cfg_load()
    if not d.get("ocr_search"):
        return 0
    exe, langs = ocr_engine()
    if not exe:
        return 0
    pct, charging = battery()
    if pct is not None and not charging and pct < 20:                # low battery: leave the phone alone
        return 0
    with LOCK:
        if any(j["status"] in ("queued", "running") for j in JOBS.values()):     # do not slow down an upload in progress
            return 0
    with db() as c:
        rows = c.execute("SELECT * FROM files WHERE kind='image' AND trashed_at IS NULL AND id NOT IN (SELECT file_id FROM ocr) "
                         "ORDER BY taken_at DESC, id DESC LIMIT 60").fetchall()
    done, t_now = 0, time.time()
    for r in rows:
        if done >= limit:
            break
        if _OCR["skip"].get(r["id"], 0) > t_now:                    # no local copy / failed recently: try again later
            continue
        src = local_path(r)
        if not src:
            _OCR["skip"][r["id"]] = t_now + 1800
            continue
        try:
            txt = ocr_read(src, exe, langs)
        except Exception as e:
            _OCR["last_err"] = str(e)[:200]
            _OCR["skip"][r["id"]] = t_now + 6 * 3600
            continue
        with db() as c:
            c.execute("INSERT OR REPLACE INTO ocr(file_id, text, at) VALUES(?,?,?)", (r["id"], txt, now()))
        done += 1
    if len(_OCR["skip"]) > 5000:
        _OCR["skip"].clear()
    return done


def ocr_worker():
    time.sleep(40)
    while True:
        n = 0
        try:
            n = ocr_batch(6)
        except Exception as e:
            _OCR["last_err"] = str(e)[:200]
        time.sleep(4 if n else 90)


def trash_purge_old():
    """Recently Deleted files older than TRASH_DAYS are deleted forever (app + Telegram). Failed ones stay and are tried again later."""
    if not cfg_get("trash_auto_delete"):
        return 0
    with db() as c:
        rows = c.execute("SELECT id, trashed_at FROM files WHERE trashed_at IS NOT NULL AND locked=0").fetchall()
    ids = [r["id"] for r in rows if (_trash_age_days(r["trashed_at"]) or 0) >= TRASH_DAYS][:200]
    if not ids:
        return 0
    bots = cfg_bots()
    rws = [r for r in (_row(i) for i in ids) if r]
    errs = delete_remote_batch(rws, bots) if rws else {}
    done = 0
    for r in rws:
        fid = r["id"]
        if fid in errs:
            continue
        cid = r["chat_id"] or cfg_load()["chat_id"]
        if cid:
            mark_gone(cid, r["message_id"], r["thumb_message_id"], *part_mids(fid))
        with db() as c:
            c.execute("DELETE FROM files WHERE id=?", (fid,))
            c.execute("DELETE FROM parts WHERE file_id=?", (fid,))
        purge_local(fid, r["cache_name"])
        done += 1
    return done


def trash_watchdog():
    time.sleep(90)
    while True:
        try:
            d = cfg_load()
            if d["vault_code"] and d["chat_id"] and cfg_bots():
                trash_purge_old()
        except Exception:
            pass
        time.sleep(1800)


_RETRY = {"k": 0, "next": 0.0}


def retry_watchdog():
    """Failed files are retried by themselves with a growing wait (2, 4, 8 ... up to 60 minutes). The wait starts again at 2 minutes
    as soon as nothing is failed any more."""
    while True:
        time.sleep(30)
        try:
            if time.time() < _RETRY["next"]:
                continue
            d = cfg_load()
            if not (d["vault_code"] and d["chat_id"] and cfg_bots()):
                continue
            with LOCK:
                busy = any(j["status"] in ("queued", "running") for j in JOBS.values())
            if busy or backup_block_reason(d):
                continue
            with db() as c:
                n = c.execute("SELECT COUNT(*) n FROM files WHERE status='failed' AND skip=0 AND trashed_at IS NULL").fetchone()["n"]
            if n:
                job_submit("backup", "Auto retry", run_full)
                _RETRY["k"] += 1
                _RETRY["next"] = time.time() + min(120 * (2 ** _RETRY["k"]), 3600)
            else:
                _RETRY["k"], _RETRY["next"] = 0, 0.0
        except Exception:
            pass


# ============================================================================
# ROUTES: pages  (was vault/routes/pages.py)
# ============================================================================
bp_pages = Blueprint("pages", __name__)
BOOT = str(int(time.time()))


_PRELOAD = []


def _module_preload():
    """Every script file the app loads at start (found by following the static import lines from app.js). The browser is told about all
    of them at once, so a bad network pays one waiting round instead of one per level of imports."""
    if _PRELOAD:
        return _PRELOAD
    seen, todo = [], ["js/app.js"]
    pat = re.compile(r"""(?:^|[\n;])\s*(?:import|export)\s+(?:[^'";]*?\s+from\s+)?["'](\./[\w./-]+\.js)["']""")
    while todo:
        nm = todo.pop(0)
        if nm in seen or nm not in WEB_ASSETS:
            continue
        seen.append(nm)
        for m in pat.finditer(WEB_ASSETS[nm][1]):
            todo.append("js/" + m.group(1)[2:])
    _PRELOAD[:] = seen
    return _PRELOAD


@bp_pages.get("/")
def home():
    pre = [("/static/" + n + ("?v=" + BOOT if n.endswith(".js") else "")) for n in _module_preload()]
    return render_template_string(INDEX_HTML, v=BOOT, preload=pre)


_GZ = {}
_VJ = {}
BOOT_HM = time.strftime("%H:%M", time.localtime(int(BOOT)))


def _versioned_js(name, text):
    """Every start of the server gives every JS module a NEW url (?v=BOOT): a phone / WebView can never keep running an old copy of a module."""
    if not name.endswith(".js"):
        return text
    t = _VJ.get(name)
    if t is None:
        t = re.sub(r"""(\bfrom\s*["']|\bimport\s*\(\s*["'])(\.{1,2}/[^"'?]+\.js)(["'])""", lambda m: m.group(1) + m.group(2) + "?v=" + BOOT + m.group(3), text)
        t = t.replace("__BOOT__", BOOT_HM)
        _VJ[name] = t
    return t


@bp_pages.get("/static/<path:name>")
def static_asset(name):
    """Serves the embedded css/js (gzip-compressed once, then kept in memory; ETag -> 304)."""
    a = WEB_ASSETS.get(name)
    if a is None:
        abort(404)
    gz = "gzip" in request.headers.get("Accept-Encoding", "")
    txt = _versioned_js(name, a[1])
    body = _GZ.setdefault(name, gzip.compress(txt.encode("utf-8"), 9)) if gz else txt.encode("utf-8")
    resp = Response(body, mimetype=a[0])
    resp.headers["Vary"] = "Accept-Encoding"
    if gz:
        resp.headers["Content-Encoding"] = "gzip"
    resp.headers["Cache-Control"] = "no-cache"
    resp.add_etag()
    return resp.make_conditional(request)


