# ── custom theme: background photo (kept in storage/config so it is part of app.backup) ──
def _bg_clear_files(keep=None):
    for p in CONFIG_DIR.glob("bg_*"):
        if p.name != (keep + ".json" if keep else None):
            p.unlink(missing_ok=True)


@bp_config.post("/api/theme/bg")
def theme_bg_upload():
    f = request.files.get("file")
    if not f:
        return jsonify(ok=False, error="No image received."), 400
    limit = 30 * 1024 * 1024
    raw = f.read(limit + 1)
    if len(raw) > limit:
        return jsonify(ok=False, error="Image is too big (max 30 MB)."), 400
    ext, data = "jpg", raw
    try:
        from PIL import Image, ImageOps
        with Image.open(io.BytesIO(raw)) as im:
            im = ImageOps.exif_transpose(im)
            im.thumbnail((1600, 1600))          # phone-sized: light on the browser and on app.backup
            buf = io.BytesIO()
            im.convert("RGB").save(buf, "JPEG", quality=82, optimize=True)
            data = buf.getvalue()
    except ImportError:
        if raw[:3] == b"\xff\xd8\xff":
            ext = "jpg"
        elif raw[:8] == b"\x89PNG\r\n\x1a\n":
            ext = "png"
        elif raw[:4] == b"RIFF" and raw[8:12] == b"WEBP":
            ext = "webp"
        else:
            return jsonify(ok=False, error="Please choose a JPG, PNG or WEBP photo."), 400
        if len(raw) > 12 * 1024 * 1024:
            return jsonify(ok=False, error="Install Pillow to use photos bigger than 12 MB (pip install Pillow)."), 400
    except Exception:
        return jsonify(ok=False, error="This file is not a valid image."), 400
    ensure_dirs()
    name = f"bg_{secrets.token_hex(6)}.{ext}"
    cfgimg(name).write_bytes(data)
    ct = dict(cfg_load()["custom_theme"])
    ct["image"] = name
    d = cfg_update({"custom_theme": ct, "theme": "custom"})
    _bg_clear_files(keep=name)
    return jsonify(ok=True, config=d)


@bp_config.post("/api/theme/bg/clear")
def theme_bg_clear():
    ct = dict(cfg_load()["custom_theme"])
    ct.pop("image", None)
    d = cfg_update({"custom_theme": ct})
    _bg_clear_files()
    return jsonify(ok=True, config=d)


@bp_config.get("/api/theme/bg/<name>")
def theme_bg_get(name):
    if not BG_NAME_RE.match(name) or not cfgimg(name).exists():
        abort(404)
    return send_file(cfgimg(name), mimetype=mimetypes.guess_type(name)[0] or "image/jpeg", max_age=31536000)


BACKUP_MAGIC = "TGVAULT-BACKUP"


BACKUP_VERSION = 2
BROWSER_STATE = TMP / "browser_state.json"


def _sqlite_snapshot(path):
    """Consistent copy of a live sqlite file. Returns (path_to_read, is_temp)."""
    path = Path(path)
    if not path.exists():
        return None, False
    ensure_dirs()
    snap = TMP / f"snap_{time.time_ns()}.db"
    try:
        a, b = sqlite3.connect(path, timeout=30), sqlite3.connect(snap)
        try:
            a.backup(b)
        finally:
            b.close()
            a.close()
        return snap, True
    except Exception:
        snap.unlink(missing_ok=True)
        return path, False


def _zip_dir(z, folder, arc):
    n = 0
    if folder.is_dir():
        for p in folder.rglob("*"):
            try:
                if p.is_file():
                    z.write(p, f"{arc}/{p.relative_to(folder).as_posix()}")
                    n += 1
            except OSError:
                pass
    return n


def _unzip_dir(z, prefix, dest):
    """Replace folder `dest` with the zip entries under `prefix/` (path escapes are ignored)."""
    shutil.rmtree(dest, ignore_errors=True)
    dest.mkdir(parents=True, exist_ok=True)
    root, n = dest.resolve(), 0
    for info in z.infolist():
        if info.is_dir() or not info.filename.startswith(prefix + "/"):
            continue
        target = (dest / info.filename[len(prefix) + 1:]).resolve()
        if root not in target.parents:
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        with z.open(info) as src, open(target, "wb") as out:
            shutil.copyfileobj(src, out, 1 << 20)
        n += 1
    return n


@bp_config.post("/api/backup/browser")
def backup_browser_state():
    """The browser sends its own saved state (localStorage + open tab) right before an export."""
    d = request.get_json(force=True, silent=True) or {}
    local, budget = {}, 2 * 1024 * 1024
    for k, v in (d.get("local") or {}).items():
        k, v = str(k)[:200], str(v)
        if len(v) <= budget:
            local[k] = v
            budget -= len(v)
    ensure_dirs()
    BROWSER_STATE.write_text(json.dumps({"local": local, "hash": str(d.get("hash", ""))[:60]}), "utf-8")
    return jsonify(ok=True)


@bp_config.get("/api/backup/export")
def export_backup():
    """app.backup (v2) = one ZIP: settings, Telegram login, library index, theme + background photo,
    thumbnails/previews, this browser's saved state and (optional, ?media=1) every local photo/video copy."""
    _db_ensure()
    ensure_dirs()
    media = request.args.get("media") == "1"
    for stale in TMP.glob("export_*.zip"):                       # leftovers of an interrupted download
        try:
            if time.time() - stale.stat().st_mtime > 900:
                stale.unlink()
        except OSError:
            pass
    out = TMP / f"export_{time.time_ns()}.zip"
    inc = {"media": media, "session": False, "avatar": False, "browser": False}
    counts = {}
    D = zipfile.ZIP_DEFLATED
    with zipfile.ZipFile(out, "w", zipfile.ZIP_STORED, allowZip64=True) as z:
        z.writestr("config.json", json.dumps(cfg_load(), ensure_ascii=False, indent=1), compress_type=D)
        for arc, src in (("db.sqlite3", DB), ("session.session", SESSION.with_suffix(".session"))):
            p, temp = _sqlite_snapshot(src)
            if p is not None:
                z.write(p, arc, compress_type=D)
                inc["session" if arc.startswith("session") else "db"] = True
                if temp:
                    p.unlink(missing_ok=True)
        for _lf in (LOCK_FILE, LOCK_KEEP):
            if _lf.exists():
                z.writestr(_lf.name, sec_read(_lf))                        # PIN/pattern hash + which photos are hidden (readable inside the backup)
        if AVATAR.exists():
            z.write(AVATAR, "avatar.jpg")
            inc["avatar"] = True
        counts["theme"] = 0
        for p in CONFIG_DIR.glob("bg_*"):
            lg = p.name[:-5] if p.name.endswith(".json") else p.name
            if BG_NAME_RE.match(lg):
                z.write(p, f"theme/{lg}")
                counts["theme"] += 1
        counts["thumbs"] = _zip_dir(z, THUMBS, "thumbs")
        counts["previews"] = _zip_dir(z, PREVIEWS, "previews")
        if media:
            counts["cache"] = _zip_dir(z, CACHE, "cache")
        if BROWSER_STATE.exists():
            z.write(BROWSER_STATE, "browser.json", compress_type=D)
            inc["browser"] = True
            BROWSER_STATE.unlink(missing_ok=True)
        z.writestr("manifest.json", json.dumps({"magic": BACKUP_MAGIC, "version": BACKUP_VERSION, "created": now(),
                                                "app": "Telegram Cloud Vault", "includes": inc, "counts": counts}),
                   compress_type=D)
    resp = send_file(out, mimetype="application/octet-stream", as_attachment=True, download_name="app.backup", max_age=0)
    resp.headers["Cache-Control"] = "no-store"
    resp.call_on_close(lambda: out.unlink(missing_ok=True))
    return resp


def _import_legacy(raw):
    """Old single-JSON app.backup (version 1) - still accepted."""
    global _db_ready
    try:
        data = json.loads(raw.decode("utf-8"))
    except Exception:
        return jsonify(ok=False, error="This is not a valid app.backup file."), 400
    if not isinstance(data, dict) or data.get("magic") != BACKUP_MAGIC:
        return jsonify(ok=False, error="This is not a valid app.backup file."), 400
    if TL_HAVE and _st["client"] is not None:
        try:
            tl_run(_drop(), 15)
        except Exception:
            pass
    ensure_dirs()
    cfg_in = data.get("config") or {}
    new = dict(DEFAULTS)
    for k, v in cfg_in.items():
        if k in EDITABLE:
            new[k] = _cfg_clean(k, v)
    code = str(cfg_in.get("vault_code", "")).upper()
    if VALID.match(code):
        new["vault_code"] = code
    dbb = data.get("db_b64")
    blob = base64.b64decode(dbb) if dbb else b""
    if dbb and not blob.startswith(b"SQLite format 3"):
        return jsonify(ok=False, error="The library index inside this backup is damaged."), 400
    with _cfg_lock:
        _cfg_write(new)
    if data.get("session_b64"):
        SESSION.with_suffix(".session").write_bytes(base64.b64decode(data["session_b64"]))
        SESSION.with_suffix(".session-journal").unlink(missing_ok=True)
    if data.get("avatar_b64"):
        AVATAR.write_bytes(base64.b64decode(data["avatar_b64"]))
    if blob:
        tmp = DB.with_suffix(".import")
        tmp.write_bytes(blob)
        for ext in ("-wal", "-shm", "-journal"):
            Path(str(DB) + ext).unlink(missing_ok=True)
        os.replace(tmp, DB)
        for folder in (THUMBS, PREVIEWS):
            shutil.rmtree(folder, ignore_errors=True)
        ensure_dirs()
    _db_ready = False
    tl_mark(False)
    threading.Thread(target=lambda: tl_ready(True), daemon=True).start()
    return jsonify(ok=True, config=cfg_load(), browser={}, restored={})


def _import_zip(path):
    global _db_ready
    try:
        z = zipfile.ZipFile(path)
    except zipfile.BadZipFile:
        return jsonify(ok=False, error="This is not a valid app.backup file."), 400
    browser, counts = {}, {}
    with z:
        names = set(z.namelist())
        try:
            man = json.loads(z.read("manifest.json").decode("utf-8"))
        except Exception:
            man = None
        if not isinstance(man, dict) or man.get("magic") != BACKUP_MAGIC:
            return jsonify(ok=False, error="This is not a valid app.backup file."), 400
        bad = z.testzip()                       # full CRC pass BEFORE anything on this device is touched
        if bad:
            return jsonify(ok=False, error=f"The backup file is damaged ({bad}). Nothing was changed."), 400
        try:
            cfg_in = json.loads(z.read("config.json").decode("utf-8")) if "config.json" in names else {}
            if not isinstance(cfg_in, dict):
                raise ValueError("config")
        except Exception:
            return jsonify(ok=False, error="The settings inside this backup are damaged. Nothing was changed."), 400
        if "db.sqlite3" in names:
            with z.open("db.sqlite3") as fh:
                if not fh.read(16).startswith(b"SQLite format 3"):
                    return jsonify(ok=False, error="The library index inside this backup is damaged. Nothing was changed."), 400
        # ---- the file is good: put every piece back exactly as it was when the backup was made ----
        if TL_HAVE and _st["client"] is not None:
            try:
                tl_run(_drop(), 15)
            except Exception:
                pass
        ensure_dirs()
        _bg_clear_files()                                                  # 1) theme background photo(s)
        counts["theme"] = 0
        for nm in names:
            if nm.startswith("theme/") and BG_NAME_RE.match(nm[6:]):
                with z.open(nm) as src, open(cfgimg(nm[6:]), "wb") as out:
                    shutil.copyfileobj(src, out, 1 << 20)
                counts["theme"] += 1
        new = dict(DEFAULTS)                                               # 2) settings (theme, custom colours, bots, folders ...)
        for k, v in cfg_in.items():
            if k in EDITABLE:
                new[k] = _cfg_clean(k, v)
        code = str(cfg_in.get("vault_code", "")).upper()
        if VALID.match(code):
            new["vault_code"] = code
        with _cfg_lock:
            _cfg_write(new)
        ses = SESSION.with_suffix(".session")                              # 3) Telegram login + profile picture
        ses.unlink(missing_ok=True)
        SESSION.with_suffix(".session-journal").unlink(missing_ok=True)
        if "session.session" in names:
            ses.write_bytes(z.read("session.session"))
        AVATAR.unlink(missing_ok=True)
        if "avatar.jpg" in names:
            AVATAR.write_bytes(z.read("avatar.jpg"))
        for _ln, _lf in (("lock.json", LOCK_FILE), ("locked_keep.json", LOCK_KEEP)):
            if _ln in names:
                try:
                    json.loads(z.read(_ln).decode("utf-8"))
                    sec_write(_lf, z.read(_ln).decode("utf-8"))
                    if _lf is LOCK_FILE:
                        _lock_mirror()
                    else:
                        _keep_mirror()
                except Exception:
                    pass
        if "db.sqlite3" in names:                                          # 4) library index
            tmp = DB.with_suffix(".import")
            with z.open("db.sqlite3") as src, open(tmp, "wb") as out:
                shutil.copyfileobj(src, out, 1 << 20)
            for ext in ("-wal", "-shm", "-journal"):
                Path(str(DB) + ext).unlink(missing_ok=True)
            os.replace(tmp, DB)
        counts["thumbs"] = _unzip_dir(z, "thumbs", THUMBS)                 # 5) thumbnails + previews
        counts["previews"] = _unzip_dir(z, "previews", PREVIEWS)
        if (man.get("includes") or {}).get("media"):                       # 6) local photo/video copies (full backup)
            counts["cache"] = _unzip_dir(z, "cache", CACHE)
        if "browser.json" in names:                                        # 7) what this browser had saved
            try:
                b = json.loads(z.read("browser.json").decode("utf-8"))
                if isinstance(b, dict):
                    browser = {"local": {str(k): str(v) for k, v in (b.get("local") or {}).items()},
                               "hash": str(b.get("hash", ""))[:60]}
            except Exception:
                browser = {}
    ensure_dirs()
    _db_ready = False
    try:
        _lock_reload_ids()
    except Exception:
        pass
    tl_mark(False)
    threading.Thread(target=lambda: tl_ready(True), daemon=True).start()
    return jsonify(ok=True, config=cfg_load(), browser=browser, restored=counts)


@bp_config.post("/api/backup/import")
def import_backup():
    ensure_dirs()
    f = request.files.get("file")
    tmp = TMP / f"import_{time.time_ns()}.bin"
    try:
        if f:
            f.save(tmp)
        else:
            tmp.write_bytes(request.get_data())
        if zipfile.is_zipfile(tmp):
            return _import_zip(tmp)
        return _import_legacy(tmp.read_bytes())
    finally:
        tmp.unlink(missing_ok=True)


@bp_config.post("/api/code/generate")
def code_generate():
    if cfg_get("vault_code"):
        return jsonify(ok=False, error="A vault code already exists. There is only ONE code for the whole app."), 409
    code = vc_generate()
    cfg_set_code(code)
    code_pin_kick()
    return jsonify(ok=True, code=code, config=cfg_load())


@bp_config.post("/api/code/set")
def code_set():
    """Use an existing code (e.g. when recovering a channel that was backed up earlier)."""
    cur = cfg_get("vault_code")
    code = vc_normalize((request.get_json(force=True, silent=True) or {}).get("code", ""))
    if not code:
        return jsonify(ok=False, error="Code must look like TV-1A2B3C4D5E6F"), 400
    with db() as c:
        n = c.execute("SELECT COUNT(*) n FROM files WHERE status='pending' OR status='failed'").fetchone()["n"]
    if cur and cur != code and n:
        return jsonify(ok=False, error="Finish the pending backups before switching to another code."), 409
    cfg_set_code(code)
    code_pin_kick()
    return jsonify(ok=True, code=code, config=cfg_load())


def _dir_bytes(p):
    n = 0
    try:
        for root, _d, names in os.walk(p):
            for x in names:
                try:
                    n += os.path.getsize(os.path.join(root, x))
                except OSError:
                    pass
    except OSError:
        pass
    return n


@bp_config.get("/api/errors")
def errors_list():
    with _ERR_LOCK:
        loaded = _ERRLOG["loaded"]
    if not loaded:
        try:
            _ERRLOG["items"] = json.loads((CONFIG_DIR / "errors.json").read_text("utf-8"))[-50:]
        except Exception:
            pass
        _ERRLOG["loaded"] = True
    with _ERR_LOCK:
        return jsonify(ok=True, errors=list(reversed(_ERRLOG["items"])))


@bp_config.post("/api/errors/clear")
def errors_clear():
    with _ERR_LOCK:
        _ERRLOG["items"], _ERRLOG["loaded"] = [], True
        try:
            (CONFIG_DIR / "errors.json").write_text("[]", "utf-8")
        except OSError:
            pass
    return jsonify(ok=True)


@bp_config.get("/api/storage")
def storage_info():
    """Storage dashboard: what the library holds (photos / videos / other / Recently Deleted) and what this app keeps on the phone."""
    out = {k: {"n": 0, "b": 0} for k in ("image", "video", "other", "trash")}
    backed = pending = 0
    with db() as c:
        rows = c.execute("SELECT kind, status, (trashed_at IS NOT NULL) tr, COUNT(*) n, COALESCE(SUM(size),0) b FROM files GROUP BY kind, status, (trashed_at IS NOT NULL)").fetchall()
    for r in rows:
        k = "trash" if r["tr"] else (r["kind"] if r["kind"] in ("image", "video") else "other")
        out[k]["n"] += r["n"]
        out[k]["b"] += int(r["b"] or 0)
        if not r["tr"]:
            if r["status"] == "backed_up":
                backed += int(r["b"] or 0)
            else:
                pending += int(r["b"] or 0)
    out["backed"], out["pending"] = backed, pending
    out["cache"], out["thumbs"] = _dir_bytes(CACHE), _dir_bytes(THUMBS)
    out["previews"], out["tmp"] = _dir_bytes(PREVIEWS), _dir_bytes(TMP)
    try:
        out["db"] = DB.stat().st_size
    except OSError:
        out["db"] = 0
    try:
        du = shutil.disk_usage(str(STORAGE if STORAGE.exists() else ROOT))
        out["disk_total"], out["disk_free"] = du.total, du.free
    except OSError:
        out["disk_total"] = out["disk_free"] = 0
    return jsonify(ok=True, **out)


@bp_config.get("/api/state")
def state():
    d = cfg_load()
    enabled = {f["path"] for f in d["folders"] if f["enabled"]}
    s = {"total": 0, "backed_local": 0, "cloud": 0, "pending": 0, "failed": 0, "excluded": 0,
         "backed_bytes": 0, "pending_bytes": 0}
    fstats = {}
    with db() as c:
        rows = c.execute("SELECT id,status,folder,size,source_path,cache_name,skip FROM files WHERE trashed_at IS NULL").fetchall()
    for r in rows:
        s["total"] += 1
        if r["folder"]:
            fs = fstats.setdefault(r["folder"], {"total": 0, "backed": 0, "skipped": 0})
            fs["total"] += 1
            fs["backed"] += 1 if r["status"] == "backed_up" else 0
            fs["skipped"] += 1 if (r["skip"] and r["status"] != "backed_up") else 0
        if r["status"] == "backed_up":
            s["backed_bytes"] += r["size"]
            s["backed_local" if local_path(r) else "cloud"] += 1
        elif (r["folder"] and r["folder"] not in enabled) or r["skip"]:
            s["excluded"] += 1
        else:
            s["failed" if r["status"] == "failed" else "pending"] += 1
            s["pending_bytes"] += r["size"]
    s["removable_bytes"] = storage_usage()
    return jsonify(ok=True, **s, code=d["vault_code"], bot=bool(d["bot_token"] and d["chat_id"]),
                   telegram=tl_ready(), cryptg=cryptg_active(), activity=job_active(), folder_stats=fstats)


