# ROUTES: library  (was vault/routes/library.py)
# ============================================================================
bp_library = Blueprint("library", __name__)


def _row(fid):
    with db() as c:
        return c.execute("SELECT * FROM files WHERE id=?", (fid,)).fetchone()


_FILES_CACHE = {}
_FILES_LOCK = threading.Lock()


def _db_token():
    """Changes whenever the database is committed to (WAL grows / db file changes) - no query needed."""
    t = []
    for suf in ("", "-wal"):
        try:
            st = os.stat(str(DB) + suf)
            t.append((st.st_mtime_ns, st.st_size))
        except OSError:
            t.append(None)
    return tuple(t)


@bp_library.get("/api/files")
def list_files():
    _lock_keep_tick()
    kind, q = request.args.get("kind", ""), request.args.get("q", "").strip()
    trash = request.args.get("trash") == "1"            # ?trash=1 -> the Recycle Bin
    code = cfg_get("vault_code")
    gst = _guest()
    key = (kind, q, trash, code, gst["uid"] if gst else None)
    tok, now = _db_token(), time.time()
    with _FILES_LOCK:
        hit = _FILES_CACHE.get(key)
    if not (hit and hit[0] == tok and now - hit[1] < 4):      # 4 s cap: also notices files that appeared / vanished on disk
        sql, args = "SELECT * FROM files WHERE locked=0 AND trashed_at IS " + ("NOT NULL" if trash else "NULL"), []
        if kind in ("image", "video", "other"):
            sql += " AND kind=?"
            args.append(kind)
        if q:
            sql += " AND name LIKE ?"
            args.append(f"%{q}%")
        sql += " ORDER BY taken_at DESC, id DESC LIMIT 5000"
        with db() as c:
            rows = c.execute(sql, args).fetchall()
        out = []
        for r in rows:
            j = to_json(r, "" if gst else code)
            if gst:
                j.update(chat_id=None, message_id=None, error="", folder="", mine=bool(r["uploader"]) and r["uploader"] == gst["uid"])
            out.append(j)
        raw = current_app.json.dumps({"ok": True, "files": out}).encode("utf-8")
        tag = hashlib.md5(raw).hexdigest()[:16]
        if hit and hit[2] == tag:
            gz = hit[4]                                         # same content as before: reuse the compressed copy
        else:
            gz = gzip.compress(raw, 4) if len(raw) > 700 else None
        hit = (tok, now, tag, raw, gz)
        with _FILES_LOCK:
            if len(_FILES_CACHE) > 12:
                _FILES_CACHE.clear()
            _FILES_CACHE[key] = hit
    _, _, tag, raw, gz = hit
    use_gz = gz is not None and "gzip" in request.headers.get("Accept-Encoding", "")
    resp = Response(gz if use_gz else raw, mimetype="application/json")
    if use_gz:
        resp.headers["Content-Encoding"] = "gzip"
    resp.headers["Vary"] = "Accept-Encoding"
    resp.headers["Cache-Control"] = "no-cache"
    resp.set_etag(tag + ("-gz" if use_gz else ""))
    return resp.make_conditional(request)


@bp_library.get("/api/ocr/search")
def ocr_search_ids():
    """Photos whose written text contains every typed word -> list of file ids (the app adds them to the name search)."""
    if _guest():
        return jsonify(ok=False, error="Not allowed"), 403
    words = [w for w in re.split(r"\s+", request.args.get("q", "").strip()) if w][:6]
    if not words or not cfg_get("ocr_search"):
        return jsonify(ok=True, ids=[])
    sql, args = "SELECT file_id FROM ocr WHERE 1=1", []
    for w in words:
        sql += " AND text LIKE ? ESCAPE '\\'"
        args.append("%" + w.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_") + "%")
    with db() as c:
        ids = [r["file_id"] for r in c.execute(sql + " LIMIT 3000", args).fetchall()]
    return jsonify(ok=True, ids=ids)


@bp_library.get("/api/ocr/status")
def ocr_status():
    if _guest():
        return jsonify(ok=False, error="Not allowed"), 403
    exe, langs = ocr_engine()
    with db() as c:
        total = c.execute("SELECT COUNT(*) n FROM files WHERE kind='image' AND trashed_at IS NULL").fetchone()["n"]
        done = c.execute("SELECT COUNT(*) n FROM files f JOIN ocr o ON o.file_id=f.id WHERE f.kind='image' AND f.trashed_at IS NULL").fetchone()["n"]
        withtext = c.execute("SELECT COUNT(*) n FROM files f JOIN ocr o ON o.file_id=f.id WHERE f.kind='image' AND f.trashed_at IS NULL AND LENGTH(o.text)>0").fetchone()["n"]
    return jsonify(ok=True, enabled=bool(cfg_get("ocr_search")), engine=bool(exe), langs=langs, total=total, done=done, with_text=withtext,
                   error=_OCR["last_err"])


def _files_stamp_value():
    """Changes whenever something in the library changes: files added / removed / renamed / moved, status, favorites, trash, cache (Downloads)."""
    with db() as c:
        r = c.execute("SELECT COUNT(*) n, COALESCE(MAX(id),0) m, COALESCE(SUM(status='backed_up'),0) b, "
                      "COALESCE(SUM(trashed_at IS NOT NULL),0) t, COALESCE(SUM(fav),0) f, COALESCE(SUM(status='failed'),0) x, "
                      "COALESCE(SUM(cache_name IS NOT NULL),0) k, COALESCE(SUM(LENGTH(name)+LENGTH(COALESCE(folder,''))),0) l FROM files").fetchone()
    return f"{r['n']}.{r['m']}.{r['b']}.{r['t']}.{r['f']}.{r['x']}.{r['k']}.{r['l']}"


def _exif_text(v):
    if isinstance(v, bytes):
        v = v.decode("utf-8", "ignore")
    return str(v or "").strip("\x00 \t\r\n")


def _exp_list(focal=None, fnum=None, expt=None, iso=None, wb=None):
    """Shooting settings as short labels, like a camera app shows them: 31.0 mm | f 1.7 | S 1/20 s | ISO 5659 | WB Auto.
    Only values that really exist in the file are returned (None when there are none)."""
    r = []
    try:
        if focal and float(focal) > 0:
            r.append("%.1f mm" % float(focal))
        if fnum and float(fnum) > 0:
            r.append("f %.1f" % float(fnum))
        if expt and float(expt) > 0:
            t = float(expt)
            r.append("S 1/%d s" % round(1 / t) if t < 0.95 else "S %s s" % ("%.1f" % t).rstrip("0").rstrip("."))
        if iso and float(iso) > 0:
            r.append("ISO %d" % int(float(iso)))
        if wb is not None and str(wb) != "":
            r.append("WB " + ("Auto" if int(wb) == 0 else "Manual"))
    except Exception:
        pass
    return r or None


_SRC_NAMES = [  # (regex, shown name) - AI generators / editors that leave their name inside a photo's metadata
    (r"midjourney", "Midjourney"), (r"dall[-· ]?e", "DALL-E (OpenAI)"), (r"stable[ _-]?diffusion|sdxl|automatic1111|comfyui", "Stable Diffusion"),
    (r"adobe firefly|firefly", "Adobe Firefly"), (r"google ai|gemini|imagen|nano banana", "Google Gemini"), (r"chatgpt|openai|gpt-image", "ChatGPT (OpenAI)"),
    (r"grok|xai", "Grok"), (r"leonardo\.?ai", "Leonardo AI"), (r"ideogram", "Ideogram"), (r"flux\b", "FLUX"), (r"bing image creator|designer\.microsoft", "Bing Image Creator"),
    (r"meta ai", "Meta AI"), (r"c2pa|contentcredentials|trainedalgorithmicmedia", "AI generated"),
    (r"photoshop", "Adobe Photoshop"), (r"lightroom", "Adobe Lightroom"), (r"canva", "Canva"), (r"snapseed", "Snapseed"),
    (r"picsart", "PicsArt"), (r"gimp", "GIMP"), (r"remini", "Remini"), (r"facetune", "Facetune"),
]


def _source_hint(b, software=""):
    """Name of what made a picture that has no camera Make/Model (AI tool or editor), from the EXIF Software tag or
    a known name found in the metadata bytes (XMP / PNG text / EXIF). Returns "" when nothing is found."""
    sw = _exif_text(software)
    if sw and re.search(r"[A-Za-z]{3}", sw):
        for rx, nm in _SRC_NAMES:
            if re.search(rx, sw, re.I):
                return nm
        return sw[:40]
    try:
        head = bytes(b[:262144]).decode("latin-1")
    except Exception:
        return ""
    for rx, nm in _SRC_NAMES:
        if re.search(rx, head, re.I):
            return nm
    return ""


def _read_image_meta(path):
    """width, height, camera and GPS of an image file (JPEG / PNG / WEBP / HEIC if pillow-heif is installed)."""
    out = {"width": None, "height": None, "camera": "", "location": None, "exp": None}
    try:
        hm = _heic_meta_file(path)                  # HEIC / HEIF / AVIF: works even when Pillow cannot open them (phones)
        if hm and hm["width"]:
            return hm
    except Exception:
        pass
    from PIL import Image
    try:
        from pillow_heif import register_heif_opener
        register_heif_opener()
    except Exception:
        pass
    with Image.open(path) as im:
        out["width"], out["height"] = im.size
        try:
            ex = im.getexif()
        except Exception:
            ex = {}
        mk, md = _exif_text(ex.get(0x010F)), _exif_text(ex.get(0x0110))
        if not (mk or md):                       # some files keep Make/Model only in the Exif sub-IFD
            try:
                sub = ex.get_ifd(0x8769) or {}
                mk, md = _exif_text(sub.get(0x010F)), _exif_text(sub.get(0x0110))
            except Exception:
                pass
        out["camera"] = md if (mk and md.lower().startswith(mk.lower())) else " ".join(x for x in (mk, md) if x)
        if not out["camera"]:                    # no camera: show what made the picture (AI tool / editor) instead
            try:
                with open(path, "rb") as fh:
                    hb = fh.read(1048576)
                out["camera"] = _head_meta(hb)[0].get("camera") or _source_hint(hb, ex.get(0x0131))
            except Exception:
                pass
        try:
            sub = ex.get_ifd(0x8769) or {}
            _i = sub.get(0x8827) or sub.get(0x8833)
            out["exp"] = _exp_list(sub.get(0x920A), sub.get(0x829D), sub.get(0x829A), _i[0] if isinstance(_i, (tuple, list)) else _i, sub.get(0xA403))
        except Exception:
            pass
        try:
            gps = ex.get_ifd(0x8825) or {}
            def deg(v, ref):
                d = float(v[0]) + float(v[1]) / 60 + float(v[2]) / 3600
                return -d if _exif_text(ref).upper() in ("S", "W") else d
            if gps.get(2) and gps.get(4):
                lat, lon = deg(gps[2], gps.get(1, "N")), deg(gps[4], gps.get(3, "E"))
                if abs(lat) > 1e-6 or abs(lon) > 1e-6:          # 0,0 = "no fix" written by some phones
                    out["location"] = {"lat": round(lat, 5), "lon": round(lon, 5)}
        except Exception:
            pass
    return out


_NAME_HINTS = [  # weak clue from the file name - only used when the file itself carries no camera / tool name
    (r"gemini[_ -]?generated", "Google Gemini"), (r"chatgpt|dall[-_· ]?e", "ChatGPT / DALL-E"), (r"midjourney", "Midjourney"),
    (r"leonardo", "Leonardo AI"), (r"firefly", "Adobe Firefly"), (r"grok", "Grok"), (r"meta[_ -]?ai", "Meta AI"), (r"copilot|bing[_ -]?image", "Microsoft Copilot"),
    (r"ideogram", "Ideogram"), (r"stable[_ -]?diffusion", "Stable Diffusion"), (r"^pxl_", "Google Pixel camera"), (r"^screenshot|^screen[_ -]?shot|^scr_", "Screenshot"),
    (r"^img[-_]\d{8}[-_]wa", "WhatsApp"), (r"^whatsapp", "WhatsApp"), (r"^signal-", "Signal"), (r"^snap[-_ ]|^snapchat", "Snapchat"),
    (r"^fb_img|^facebook", "Facebook"), (r"^insta|^instagram", "Instagram"), (r"^telegram|^photo_\d{4}-\d\d-\d\d", "Telegram"),
    (r"^dsc[_-]?\d|^dscn", "Digital camera (DSC)"), (r"^dji_", "DJI camera"), (r"^gopr|^gx\d", "GoPro"),
    (r"^img_\d{4}\.(heic|heif)$", "Apple iPhone"),
]


def _name_hint(name):
    n = Path(str(name or "")).name.lower()
    for rx, nm in _NAME_HINTS:
        if re.search(rx, n):
            return nm + " (from file name)"
    return ""


HEAD_CHUNK = 4096            # photo details are read from the FIRST 4 KB of the cloud file (8 KB at most) - never the whole photo


async def _head_bytes(chat_id, mid, chunks, size=HEAD_CHUNK):
    c = await _client()
    ent = await _entity(c, chat_id)
    m = await c.get_messages(ent, ids=int(mid))
    media = getattr(m, "document", None) or getattr(m, "photo", None) if m else None
    if not media:
        raise RuntimeError("message gone")
    buf = b""
    async for ch in c.iter_download(media, offset=0, limit=chunks, request_size=size):
        buf += bytes(ch)
        if len(buf) >= chunks * size:
            break
    return buf


def tl_head(chat_id, mid, chunks=1, timeout=25, size=HEAD_CHUNK):
    return tl_run(_head_bytes(chat_id, mid, chunks, size), timeout)


def _tiff_meta(t):
    """Make/Model, pixel size and GPS from the TIFF block of EXIF - tolerant of a file that was cut short."""
    import struct
    out = {"width": None, "height": None, "camera": "", "location": None, "exp": None}
    if len(t) < 8 or t[:2] not in (b"II", b"MM"):
        return out
    e = "<" if t[:2] == b"II" else ">"
    SZ = {1: 1, 2: 1, 3: 2, 4: 4, 5: 8, 7: 1}

    def ifd(off):
        res = {}
        try:
            n = struct.unpack_from(e + "H", t, off)[0]
            for i in range(min(n, 200)):
                tag, typ, cnt = struct.unpack_from(e + "HHI", t, off + 2 + i * 12)
                sz = SZ.get(typ, 0) * cnt
                if not sz:
                    continue
                vo = off + 2 + i * 12 + 8
                if sz > 4:
                    vo = struct.unpack_from(e + "I", t, vo)[0]
                if vo + sz > len(t):
                    continue
                raw = t[vo:vo + sz]
                if typ == 2:
                    res[tag] = raw.split(b"\x00")[0].decode("utf-8", "ignore").strip()
                elif typ == 3:
                    res[tag] = list(struct.unpack(e + "%dH" % cnt, raw))
                elif typ == 4:
                    res[tag] = list(struct.unpack(e + "%dI" % cnt, raw))
                elif typ == 5:
                    v = struct.unpack(e + "%dI" % (cnt * 2), raw)
                    res[tag] = [v[k] / v[k + 1] if v[k + 1] else 0.0 for k in range(0, len(v), 2)]
        except Exception:
            pass
        return res
    try:
        i0 = ifd(struct.unpack_from(e + "I", t, 4)[0])
    except Exception:
        return out
    mk, md = str(i0.get(0x010F, "")), str(i0.get(0x0110, ""))
    out["camera"] = md if (mk and md.lower().startswith(mk.lower())) else " ".join(x for x in (mk, md) if x)
    out["software"] = str(i0.get(0x0131, ""))
    ex = ifd(i0[0x8769][0]) if i0.get(0x8769) else {}
    if ex.get(0xA002) and ex.get(0xA003):
        out["width"], out["height"] = int(ex[0xA002][0]), int(ex[0xA003][0])
    _g = lambda k: (ex.get(k) or [None])[0] if isinstance(ex.get(k), list) else ex.get(k)
    out["exp"] = _exp_list(_g(0x920A), _g(0x829D), _g(0x829A), _g(0x8827) or _g(0x8833), _g(0xA403))
    if i0.get(0x8825):
        g = ifd(i0[0x8825][0])
        try:
            def deg(v, ref):
                d = v[0] + v[1] / 60 + v[2] / 3600
                return -d if str(ref).upper() in ("S", "W") else d
            if g.get(2) and g.get(4):
                lat, lon = deg(g[2], g.get(1, "N")), deg(g[4], g.get(3, "E"))
                if abs(lat) > 1e-6 or abs(lon) > 1e-6:
                    out["location"] = {"lat": round(lat, 5), "lon": round(lon, 5)}
        except Exception:
            pass
    return out


def _heic_meta(b):
    """(meta, need). Pure-python reader for HEIC / HEIF / AVIF (no Pillow, no pillow-heif, no ffmpeg needed): pixel size from the
    'ispe' box, camera + GPS from the Exif item that 'iloc' points to. need = how many bytes from the file start are required
    to finish the job (None when done) - the caller fetches that much and calls again."""
    import struct
    out = {"width": None, "height": None, "camera": "", "location": None, "exp": None}
    n = len(b)
    need = [None]

    def boxes(lo, hi):
        pos = lo
        while pos + 8 <= hi:
            sz, typ = struct.unpack_from(">I4s", b, pos)
            hdr = 8
            if sz == 1:
                if pos + 16 > hi:
                    return
                sz, hdr = struct.unpack_from(">Q", b, pos + 8)[0], 16
            elif sz == 0:
                sz = hi - pos
            if sz < hdr:
                return
            yield typ, pos + hdr, pos + sz
            pos += sz

    exif_id, locs, ispes, rot = None, {}, [], 0
    try:
        for typ, s, e in boxes(0, n):
            if typ != b"meta":
                continue
            if e > n:
                need[0] = e
            s, e = s + 4, min(e, n)
            for t2, s2, e2 in boxes(s, e):
                if t2 == b"iinf":
                    v = b[s2]
                    cnt, p = (struct.unpack_from(">H", b, s2 + 4)[0], s2 + 6) if v == 0 else (struct.unpack_from(">I", b, s2 + 4)[0], s2 + 8)
                    for t3, s3, e3 in boxes(p, e2):
                        if t3 != b"infe" or b[s3] < 2:
                            continue
                        if b[s3] == 2:
                            iid, q = struct.unpack_from(">H", b, s3 + 4)[0], s3 + 6
                        else:
                            iid, q = struct.unpack_from(">I", b, s3 + 4)[0], s3 + 8
                        if b[q + 2:q + 6] == b"Exif":
                            exif_id = iid
                elif t2 == b"iloc":
                    v, p = b[s2], s2 + 4
                    osz, lsz, bsz = b[p] >> 4, b[p] & 15, b[p + 1] >> 4
                    isz = (b[p + 1] & 15) if v in (1, 2) else 0
                    p += 2
                    if v < 2:
                        cnt, p = struct.unpack_from(">H", b, p)[0], p + 2
                    else:
                        cnt, p = struct.unpack_from(">I", b, p)[0], p + 4
                    for _ in range(cnt):
                        if p + 8 > e2:
                            break
                        if v < 2:
                            iid, p = struct.unpack_from(">H", b, p)[0], p + 2
                        else:
                            iid, p = struct.unpack_from(">I", b, p)[0], p + 4
                        cm = 0
                        if v in (1, 2):
                            cm, p = struct.unpack_from(">H", b, p)[0] & 15, p + 2
                        p += 2                                            # data_reference_index
                        base, p = int.from_bytes(b[p:p + bsz], "big"), p + bsz
                        ec, p = struct.unpack_from(">H", b, p)[0], p + 2
                        for k in range(ec):
                            p += isz if (v in (1, 2) and isz) else 0
                            eo, p = int.from_bytes(b[p:p + osz], "big"), p + osz
                            el, p = int.from_bytes(b[p:p + lsz], "big"), p + lsz
                            if k == 0 and iid not in locs:
                                locs[iid] = (cm, base + eo, el)
                elif t2 == b"iprp":
                    for t3, s3, e3 in boxes(s2, e2):
                        if t3 != b"ipco":
                            continue
                        for t4, s4, e4 in boxes(s3, e3):
                            if t4 == b"ispe" and s4 + 12 <= e4:
                                ispes.append(struct.unpack_from(">II", b, s4 + 4))
                            elif t4 == b"irot" and s4 < e4 and (b[s4] & 1):
                                rot = 1                                   # turned 90 / 270 degrees: width and height swap
            break
    except (struct.error, IndexError):
        pass
    if ispes:
        w, h = max(ispes, key=lambda x: x[0] * x[1])
        out["width"], out["height"] = (h, w) if rot else (w, h)
    if exif_id in locs:
        cm, off, ln = locs[exif_id]
        if cm == 0 and 4 < ln <= 8 * 1024 * 1024:
            if off + ln > n:
                need[0] = max(need[0] or 0, off + ln)
            else:
                d = b[off:off + ln]
                m = _tiff_meta(d[4 + int.from_bytes(d[:4], "big"):])
                out["camera"], out["location"], out["exp"] = m["camera"], m["location"], m.get("exp")
                if not out["camera"]:
                    out["camera"] = _source_hint(d, m.get("software"))
                if not out["width"] and m["width"]:
                    out["width"], out["height"] = m["width"], m["height"]
    if not out["camera"] and not need[0]:
        out["camera"] = _source_hint(b)
    return out, need[0]


def _heic_meta_file(path):
    """HEIC / HEIF / AVIF file on disk -> meta dict (see _heic_meta), or None when it is not such a file."""
    with open(path, "rb") as f:
        if f.read(12)[4:8] != b"ftyp":
            return None
        f.seek(0)
        out, need = _heic_meta(f.read(262144))
        if need and need <= 16 * 1024 * 1024:
            f.seek(0)
            out, need = _heic_meta(f.read(need))
        return out


def _head_meta(b):
    out, done = _head_meta0(b)
    if not out.get("camera") and done:
        out["camera"] = _source_hint(b)
    return out, done


def _head_meta0(b):
    """(meta, complete). Reads size / camera / GPS from the first bytes of a JPEG, PNG, WEBP or GIF.
    complete=False when a JPEG's EXIF block is longer than the bytes we have."""
    import struct
    out = {"width": None, "height": None, "camera": "", "location": None, "exp": None}
    if b[:8] == b"\x89PNG\r\n\x1a\n" and len(b) >= 24:
        out["width"], out["height"] = struct.unpack(">II", b[16:24])
        pos, blob, sw, done = 8, [], "", False
        while pos + 8 <= len(b):
            ln, ty = struct.unpack(">I4s", b[pos:pos + 8])
            d = b[pos + 8:pos + 8 + ln]
            if ty == b"IDAT" or ty == b"IEND":
                done = True
                break
            if len(d) < ln:                                  # chunk runs past the bytes we have
                break
            try:
                if ty == b"eXIf":
                    m = _tiff_meta(d)
                    out["camera"] = out["camera"] or m["camera"]
                    sw = sw or m.get("software", "")
                    out["location"] = out["location"] or m["location"]
                    out["exp"] = out["exp"] or m.get("exp")
                elif ty == b"tEXt":
                    k, _, v = d.partition(b"\x00")
                    blob.append(k.decode("latin-1") + "=" + v.decode("utf-8", "ignore"))
                    if k.lower() in (b"software", b"source", b"generator", b"creator", b"tool"):
                        sw = sw or v.decode("utf-8", "ignore")
                elif ty == b"zTXt":
                    k, _, v = d.partition(b"\x00")
                    blob.append(k.decode("latin-1") + "=" + zlib.decompress(v[1:]).decode("utf-8", "ignore"))
                elif ty == b"iTXt":
                    k, _, v = d.partition(b"\x00")
                    flag = v[0]
                    v = v[2:].split(b"\x00", 2)[2] if len(v) > 2 else b""
                    blob.append(k.decode("latin-1") + "=" + (zlib.decompress(v) if flag else v).decode("utf-8", "ignore"))
                elif ty == b"caBX":                          # C2PA / Content Credentials ("made by AI" label)
                    blob.append(d.decode("latin-1"))
                    out["camera"] = out["camera"] or "AI generated (C2PA)"
            except Exception:
                pass
            pos += 12 + ln
        if not out["camera"]:
            out["camera"] = _source_hint("\n".join(blob).encode("latin-1", "ignore"), sw)
        return out, done or len(b) < 65536
    if b[:4] == b"GIF8" and len(b) >= 10:
        out["width"], out["height"] = struct.unpack("<HH", b[6:10])
        return out, True
    if b[:4] == b"RIFF" and b[8:12] == b"WEBP":
        pos = 12
        while pos + 8 <= len(b):
            ck, ln = b[pos:pos + 4], struct.unpack("<I", b[pos + 4:pos + 8])[0]
            d = b[pos + 8:pos + 8 + ln]
            if ck == b"VP8X" and len(d) >= 10:
                out["width"], out["height"] = 1 + int.from_bytes(d[4:7], "little"), 1 + int.from_bytes(d[7:10], "little")
            elif ck == b"VP8 " and len(d) >= 10:
                out["width"], out["height"] = struct.unpack("<HH", d[6:10])[0] & 0x3FFF, struct.unpack("<HH", d[6:10])[1] & 0x3FFF
            elif ck == b"VP8L" and len(d) >= 5:
                v = int.from_bytes(d[1:5], "little")
                out["width"], out["height"] = (v & 0x3FFF) + 1, ((v >> 14) & 0x3FFF) + 1
            elif ck == b"EXIF":
                x = d[6:] if d[:6] == b"Exif\x00\x00" else d
                out.update({k: v for k, v in _tiff_meta(x).items() if k in ("camera", "location", "exp") or v})
                return out, len(d) >= ln
            pos += 8 + ln + (ln & 1)
        return out, out["width"] is not None
    if b[:2] == b"\xff\xd8":
        pos, complete, sof = 2, True, False
        while pos + 4 <= len(b):
            if b[pos] != 0xFF:
                break
            mk, ln = b[pos + 1], struct.unpack(">H", b[pos + 2:pos + 4])[0]
            if mk == 0xD9:
                break
            seg = b[pos + 4:pos + 2 + ln]
            if mk == 0xE1 and seg[:6] == b"Exif\x00\x00":
                m = _tiff_meta(seg[6:])
                out["camera"], out["location"] = m["camera"] or _source_hint(b"", m.get("software")), m["location"]
                out["exp"] = m.get("exp")
                if m["width"] and not sof:
                    out["width"], out["height"] = m["width"], m["height"]
            elif 0xC0 <= mk <= 0xCF and mk not in (0xC4, 0xC8, 0xCC) and len(seg) >= 5:
                out["height"], out["width"] = struct.unpack(">HH", seg[1:5])
                sof = True
                break                                    # real pixel size found - nothing more is needed
            elif mk == 0xDA:
                break
            if pos + 2 + ln > len(b):                   # this segment (XMP / ICC / C2PA ...) runs past the bytes we have
                complete = False
                break
            pos += 2 + ln
        if not sof and pos + 4 > len(b) and len(b) >= 2:
            complete = False                             # ran out of bytes before the size marker
        return out, complete
    return out, True


_META_KEYS = ("width", "height", "camera", "location", "exp")


def _meta_for_row(row, cached_only=False):
    """(meta dict, error). Cached answer first; else local copy; else a temporary download from Telegram. Saves the answer."""
    key = "meta6:" + str(row["sha256"])
    with db() as c:
        kr = c.execute("SELECT value FROM kv WHERE key=?", (key,)).fetchone()
    if kr:
        try:
            return json.loads(kr["value"]), None
        except Exception:
            pass
    tp = thumb_path(row["id"])
    if row["kind"] == "image" and tp.is_file():          # details already inside the thumbnail: instant, no Telegram, no original needed
        tm = thumb_meta_read(tp)
        if tm and tm.get("width") and tm.get("camera") and "exp" in tm:
            tm = {k: tm.get(k) for k in _META_KEYS}
            _tm_kv_save(row, tm)
            return tm, None
    if cached_only:
        return None, None
    out = {"width": None, "height": None, "camera": "", "location": None, "exp": None}
    try:
        lp = local_path(row)
        if lp:
            out.update(_read_image_meta(lp))
        else:
            if not (row["chat_id"] and row["message_id"]):
                return out, "no copy"
            if not tl_ready():
                return out, "Log in to Telegram (Settings) to read photo details"
            if Path(str(row["name"])).suffix.lower() in (".heic", ".heif", ".hif", ".avif"):
                b = tl_head(row["chat_id"], row["message_id"], 1, size=65536)             # HEIC: first 64 KB holds the index of the file
                out, need = _heic_meta(b)
                if need and need <= 4 * 1024 * 1024:                                      # the Exif block sits further in: fetch just up to its end
                    out, need = _heic_meta(tl_head(row["chat_id"], row["message_id"], -(-need // 65536), 60, size=65536))
                if not out["width"] and b[4:8] != b"ftyp":
                    out, ok = _head_meta(b)
            else:
                b = tl_head(row["chat_id"], row["message_id"], 1, size=65536)  # first 64 KB: enough for most photos
                out, ok = _head_meta(b)
                if not ok and len(b) >= 65536:                                  # big XMP / ICC / C2PA block before the pixels: read up to 1 MB
                    b = tl_head(row["chat_id"], row["message_id"], 16, 60, size=65536)
                    out, ok = _head_meta(b)
    except Exception as e:
        return out, (str(e)[:120] or "error")
    with db() as c:
        c.execute("INSERT OR REPLACE INTO kv(key,value) VALUES(?,?)", (key, json.dumps({k: out.get(k) for k in _META_KEYS})))
    if row["kind"] == "image" and tp.is_file() and out.get("width"):          # old thumbnail without details: put them in now
        thumb_meta_embed(tp, out)
    return out, None


@bp_library.get("/api/files/<int:fid>/meta")
def file_meta(fid):
    """Dimensions, camera + location (EXIF) of one photo - works for 'cloud only' photos too (see _meta_for_row)."""
    empty = {"ok": True, "width": None, "height": None, "camera": "", "location": None, "exp": None}
    if getattr(g, "guest", None):
        return jsonify(empty)
    with db() as c:
        row = c.execute("SELECT * FROM files WHERE id=?", (fid,)).fetchone()
    if not row:
        abort(404)
    if row["kind"] != "image":
        return jsonify(empty)
    out, err = _meta_for_row(row)
    res = {**empty, **(out or {})}
    if not res.get("camera"):
        res["camera"] = _name_hint(row["name"])
    if err:
        res["error"] = err
    return jsonify(res)


def meta_backfill_worker():
    """Background: every image (old backups + new ones) gets its size / camera / GPS read ONCE and remembered,
    so the info sheet is instant. Slow and gentle: a few photos per round, only while Telegram is logged in."""
    try:
        for _f in CACHE.glob("meta_*"):          # leftovers of the old whole-photo download
            _f.unlink(missing_ok=True)
    except Exception:
        pass
    time.sleep(60)
    while True:
        try:
            with db() as c:
                rows = c.execute("SELECT * FROM files WHERE kind='image' AND trashed_at IS NULL "
                                 "AND NOT EXISTS (SELECT 1 FROM kv WHERE key='meta6:'||files.sha256) "
                                 "AND NOT EXISTS (SELECT 1 FROM kv WHERE key='metafail:'||files.id) "
                                 "ORDER BY (status='backed_up') ASC, id DESC LIMIT 8").fetchall()
            for r in rows:
                if BIG_BUSY[0]:
                    break
                out, err = _meta_for_row(r)
                if err and "Log in" not in err:
                    with db() as c:          # unreadable / too big: do not try again every round
                        c.execute("INSERT OR REPLACE INTO kv(key,value) VALUES(?,?)", (f"metafail:{r['id']}", err))
                time.sleep(1.5)
            time.sleep(8 if rows else 300)
        except Exception:
            time.sleep(120)


def daily_summary_watchdog():
    """Every night (after 22:00) send ONE Telegram message: 'aaj N photos backup hui, M fail'."""
    while True:
        time.sleep(300)
        try:
            if not cfg_get("daily_summary"):
                continue
            dt = datetime.now()
            today = dt.strftime("%Y-%m-%d")
            if dt.hour < 22 or cfg_get("summary_last") == today:
                continue
            with db() as c:
                ok = c.execute("SELECT COUNT(*) n FROM files WHERE status='backed_up' AND backed_at LIKE ?", (today + "%",)).fetchone()["n"]
                bad = c.execute("SELECT COUNT(*) n FROM files WHERE status='failed' AND skip=0 AND trashed_at IS NULL").fetchone()["n"]
            cfg_update({"summary_last": today})
            bots, chat = cfg_bots(), cfg_get("chat_id")
            if (not ok and not bad) or not bots or not chat:
                continue
            tgapi_call(bots[0]["token"], "sendMessage", {"chat_id": chat, "text": f"Cloud Vault: aaj {ok} photos backup hui, {bad} fail"}, timeout=30)
        except Exception:
            pass


@bp_library.get("/api/files/stamp")
def files_stamp():
    """Tiny change-detector: the browser only reloads the (big) file list when this value changed."""
    return jsonify(ok=True, stamp=_files_stamp_value())


@bp_library.get("/api/live")
def api_live():
    """LIVE pulse (polled every few seconds by every open page, owner and LAN guests): two short strings, nothing else.
    cfg   = the owner's look (theme, background photo, scroll options) + what this guest is allowed to do
    files = the library (see _files_stamp_value)"""
    gst = _guest()
    look = cfg_public()
    look["_perms"] = (gst or {}).get("perms") or {}
    cfg = format(zlib.crc32(json.dumps(look, sort_keys=True, default=str).encode()), "x")
    can_view = (not gst) or bool(gst["perms"].get("view"))
    return jsonify(ok=True, cfg=cfg, files=_files_stamp_value() if can_view else None)


# ── Locked Folder pictures: their thumbnails / previews are kept in MEMORY only; no picture file is left in the thumbs / previews folders ──
_SEAL, _SEAL_ID, _SEAL_LK, _SEAL_B, SEAL_MAX = {}, {}, threading.Lock(), [0], 64 * 1024 * 1024
_SEAL_SWEPT = [False]


def _seal_wipe(fid):
    """Remove every picture file of this id from the thumbs / previews folders (turned copies too)."""
    try:
        thumb_path(fid).unlink(missing_ok=True)
        preview_path(fid).unlink(missing_ok=True)
        for q in PREVIEWS.glob(f"rot{fid}_*"):
            q.unlink(missing_ok=True)
    except OSError:
        pass


def _seal_sweep():
    """Once per start (and when photos are hidden): old thumbnail files of hidden photos are deleted."""
    for fid in list(LOCKED_IDS):
        _seal_wipe(fid)
    _SEAL_SWEPT[0] = True


def _sealed_image(r, tag):
    """Thumbnail (tag 't') or preview ('p') of a hidden picture as an answer built from memory. None = nothing to show (normal path decides)."""
    fid = r["id"]
    rot = _rot_of(r) if r["kind"] == "image" else 0
    key = (tag, fid, rot)
    data = _SEAL.get(key)
    if data is None:
        with _SEAL_LK:
            lk = _SEAL_ID.setdefault(fid, threading.Lock())
        with lk:
            data = _SEAL.get(key)
            if data is None:
                src = None
                try:
                    src = (make_preview(r) or get_thumb(r)) if tag == "p" else get_thumb(r)
                    if src and Path(src).exists():
                        data = Path(rot_image(Path(src), fid, tag, rot)).read_bytes()
                except Exception:
                    data = None
                _seal_wipe(fid)                      # the file that was just made is removed at once
                if data:
                    with _SEAL_LK:
                        _SEAL[key] = data
                        _SEAL_B[0] += len(data)
                        while _SEAL_B[0] > SEAL_MAX and len(_SEAL) > 1:
                            old = next(iter(_SEAL))
                            _SEAL_B[0] -= len(_SEAL.pop(old))
    if not data:
        return None
    resp = Response(data, mimetype="image/jpeg")
    resp.headers.update({"Cache-Control": "private, no-store", "X-Content-Type-Options": "nosniff"})
    return resp


@bp_library.get("/thumb/<int:fid>")
def thumb(fid):
    r = _row(fid)
    if not r:
        return "", 404
    if r["locked"] and r["kind"] in ("image", "video"):
        sealed = _sealed_image(r, "t")
        if sealed is not None:
            return sealed
    p = get_thumb(r)
    rot = _rot_of(r) if r["kind"] == "image" else 0
    if p and p.exists():
        return send_file(rot_image(p, fid, "t", rot), mimetype="image/jpeg", max_age=31536000)
    lp = local_path(r)
    if lp and r["kind"] == "image" and lp.suffix.lower() in (".jpg", ".jpeg", ".png", ".webp", ".gif", ".bmp", ".avif"):
        if rot:
            q = rot_image(lp, fid, "o", rot, 1600)
            if q != lp:
                return send_file(q, mimetype="image/jpeg", max_age=3600)
        return send_file(lp, mimetype=r["mime"] or "image/jpeg", max_age=3600)      # no sharp preview possible: show the real picture
    if p and p.exists():
        return send_file(p, mimetype="image/jpeg", max_age=300)
    return "", 404


@bp_library.get("/preview/<int:fid>")
def preview(fid):
    r = _row(fid)
    if not r:
        return "", 404
    if r["locked"] and r["kind"] == "image":
        sealed = _sealed_image(r, "p")
        if sealed is not None:
            return sealed
    p = make_preview(r) if r["kind"] == "image" else None
    if not p and r["kind"] == "image":
        p = get_thumb(r)            # blurry-but-visible beats a black screen
    if p and p.exists():
        return send_file(rot_image(p, fid, "p", _rot_of(r) if r["kind"] == "image" else 0), mimetype="image/jpeg", max_age=31536000)
    return "", 404


HD_PROG = {}          # file id -> [bytes received from Telegram, total bytes] while an HD view pulls a cloud-only picture back


def _hd_cb(fid):
    box = HD_PROG[fid] = [0, 0]

    def cb(done, total):
        box[0], box[1] = int(done or 0), int(total or 0)
    return cb


@bp_library.get("/api/hdp/<int:fid>")
def hd_progress(fid):
    """How much of the HD picture the server has already received from Telegram (the browser adds the second half itself)."""
    b = HD_PROG.get(fid)
    return jsonify(ok=True, done=b[0] if b else 0, total=b[1] if b else 0)


def _serve_sealed(r):
    """HD view of a picture in the Locked Folder that lives only in Telegram: it is received block by block into MEMORY and sent to the
    screen. Nothing is written to cache / storage, so no file manager can show or copy it."""
    fid, size = r["id"], int(r["size"])
    box = HD_PROG[fid] = [0, size]
    buf = bytearray()
    try:
        for i in range(-(-size // STREAM_B)):
            want = min(STREAM_B, size - i * STREAM_B)
            data = None
            for attempt in range(3):
                try:
                    data = tl_run(_stream_fetch(r["chat_id"], r["message_id"], i * STREAM_B, size), 90)
                    if len(data) >= want:
                        break
                    raise RuntimeError("short block")
                except Exception:
                    _stream_doc.pop((str(r["chat_id"]), int(r["message_id"])), None)
                    if attempt == 2:
                        raise
                    time.sleep(1 + attempt)
            buf += data[:want]
            box[0] = len(buf)
    except Exception as e:
        return f"Could not get this file: {e}", 503
    finally:
        HD_PROG.pop(fid, None)
    mime = r["mime"] if (r["mime"] or "").startswith("image/") else (mimetypes.guess_type(r["name"])[0] or "image/jpeg")
    resp = Response(bytes(buf), mimetype=mime)
    resp.headers.update({"X-Content-Type-Options": "nosniff", "Content-Security-Policy": "sandbox", "Cache-Control": "no-store"})
    return resp


HD_CONVERT_EXT = (".heic", ".heif", ".tif", ".tiff")


def _hd_jpeg(row, src):
    """HD view of a picture the browser cannot show (HEIC / HEIF / TIFF): a full-quality JPEG (long side up to 4096 px) is made from the
    original and cached in previews/. Returns Path or None. The original file is never changed (Download still gives it)."""
    try:
        out = PREVIEWS / f"hd{row['id']}_{int(Path(src).stat().st_mtime)}.jpg"
        if out.exists() and out.stat().st_size > 0:
            return out
        ensure_dirs()
        for old in PREVIEWS.glob(f"hd{row['id']}_*"):
            old.unlink(missing_ok=True)
        tmp = out.with_name(out.name + f".{time.time_ns()}.tmp")
        full = Path(str(tmp) + ".full.jpg")

        def _shrink(a):
            from PIL import Image, ImageOps
            with Image.open(a) as im:
                im = ImageOps.exif_transpose(im)
                im.thumbnail((4096, 4096), Image.LANCZOS)
                im.convert("RGB").save(tmp, "JPEG", quality=90, optimize=True)
        ok = False
        try:
            try:
                _shrink(src); ok = True                          # Pillow (+ pillow-heif)
            except Exception:
                tmp.unlink(missing_ok=True)
            if not ok and Path(src).suffix.lower() in (".heic", ".heif") and _heic_cli(src, full):      # libheif tools (Termux: pkg install libheif-progs)
                try:
                    _shrink(full); ok = True
                except Exception:
                    tmp.unlink(missing_ok=True)
                    os.replace(full, tmp); ok = True             # no Pillow: the converted full-size JPEG itself
            if not ok and shutil.which("ffmpeg"):
                try:
                    subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-i", str(src), "-frames:v", "1", "-q:v", "2", "-f", "image2", str(tmp)],
                                   timeout=120, check=True)
                    ok = tmp.exists() and tmp.stat().st_size > 0
                except Exception:
                    ok = False
            if ok and tmp.exists() and tmp.stat().st_size > 0:
                os.replace(tmp, out)
                return out
        finally:
            tmp.unlink(missing_ok=True)
            full.unlink(missing_ok=True)
    except Exception:
        pass
    return None


def _serve(fid, inline):
    r = _row(fid)
    if not r:
        return "File not found", 404
    was_local = local_path(r) is not None
    if not inline and not was_local:
        parts = done_parts(r)
        if parts:                                       # big file stored as parts: stream it merged, parts arrive in parallel
            return stream_parts(r, parts)
    _sx = Path(r["name"]).suffix.lower()
    _is_aud = _sx in AUDIO_MIME or (r["mime"] or "").startswith("audio/")
    if (inline and not was_local and (r["kind"] == "video" or _is_aud) and r["status"] == "backed_up" and r["chat_id"] and r["message_id"]
            and int(r["size"] or 0) > 0 and not done_parts(r) and tl_ready()):
        if _is_aud:
            vm = AUDIO_MIME.get(_sx) or (r["mime"] if (r["mime"] or "").startswith("audio/") else "audio/mpeg")
        else:
            vm = r["mime"] if (r["mime"] or "").startswith("video/") else (mimetypes.guess_type(r["name"])[0] or "video/mp4")
            if not vm.startswith("video/"):
                vm = "video/mp4"
        return stream_response(r, vm, request.headers.get("Range"), VCAP.get(fid, VCAP_DEFAULT))
    if (inline and not was_local and r["locked"] and r["kind"] == "image" and Path(r["name"]).suffix.lower() != ".svg"
            and r["status"] == "backed_up" and r["chat_id"] and r["message_id"]
            and 0 < int(r["size"] or 0) <= 48 * 1024 * 1024 and not done_parts(r) and tl_ready()):
        return _serve_sealed(r)                          # hidden picture: HD goes straight to the screen, NO file is written to the phone
    xid = None
    if not inline and request.method != "HEAD":
        xid = xfer_begin("download", r["name"], r["size"], None, "" if was_local else "Fetching from Telegram ...", fid=r["id"])
    hdp = ((inline and request.args.get("hd") == "1") or request.args.get("prog") == "1") and not was_local          # HD view of a cloud-only picture: real % of the Telegram part
    try:
        p = restore_local(r, progress=_hd_cb(fid) if hdp else None)
    except Exception as e:
        if hdp:
            HD_PROG.pop(fid, None)
        if xid:
            xfer_end(xid, False, "Could not get the file")
        return f"Could not get this file: {e}", 503
    if hdp:
        HD_PROG.pop(fid, None)
    if xid:
        xfer_note(xid, "")
    if not was_local and r["status"] == "backed_up":
        TEMP_CACHE[fid] = time.time()
    mime = r["mime"] if (r["mime"] or "").startswith(("image/", "video/", "audio/")) else None
    mime = mime or mimetypes.guess_type(r["name"])[0] or "application/octet-stream"
    _ae = Path(r["name"]).suffix.lower()
    if _ae in AUDIO_MIME and not mime.startswith("audio/"):
        mime = AUDIO_MIME[_ae]
    is_pdf = _ae == ".pdf" or mime == "application/pdf"
    _hdconv = False
    if inline and request.args.get("hd") == "1" and r["kind"] == "image" and _ae in HD_CONVERT_EXT:
        _hj = _hd_jpeg(r, p)                              # HEIC & co: the browser gets a JPEG made from the original
        if _hj:
            p, mime, _hdconv = _hj, "image/jpeg", True
        else:
            return "This HEIC picture could not be converted for HD. Install the HEIC tools (Termux: pkg install libheif-progs, and pip install pillow-heif) - Download still gives the original.", 415
    show = inline and (mime.startswith(("image/", "video/", "audio/")) or is_pdf) and mime != "image/svg+xml"
    if is_pdf:
        mime = "application/pdf"
    if show and mime.startswith(("video/", "audio/")) and request.headers.get("Range"):
        capped = range_response(p, mime, request.headers.get("Range"), VCAP.get(fid, VCAP_DEFAULT))
        if capped is not None:
            return capped
    resp = send_file(p, as_attachment=not show, download_name=r["name"],
                     mimetype=mime if show else "application/octet-stream", conditional=True)
    resp.headers["X-Content-Type-Options"] = "nosniff"
    if _hdconv:
        resp.headers["X-HD-Converted"] = "1"
    if not (show and is_pdf):
        resp.headers["Content-Security-Policy"] = "sandbox"
    if xid:
        xfer_wrap(resp, xid)
    return resp


@bp_library.get("/api/transfers")
def api_transfers():
    """Everything that is being downloaded (or just was): this device, LAN guests, share links, FTP - with percentages."""
    items = xfer_list()
    gst = _guest()
    if gst:                                              # a LAN guest sees only the downloads of their own device
        mine = {x["id"] for x in XFERS.values() if x.get("uid") == gst["uid"]}
        items = [x for x in items if x["id"] in mine]
    return jsonify(ok=True, items=items)


@bp_library.get("/api/transfers/history")
def api_transfers_history():
    """file id -> who downloaded it last (Web browser, LAN ip, FTP ip, Share link ip)."""
    if not DLLOG:
        dllog_load()
    dllog_prune()                                        # finished long ago -> removed (the file too, when empty)
    gst = _guest()
    if gst:
        return jsonify(ok=True, by={k: v["by"] for k, v in DLLOG.items() if gst["uid"] in v.get("u", [])})
    return jsonify(ok=True, by={k: v["by"] for k, v in DLLOG.items()})


@bp_library.post("/api/transfers/history/clear")
def api_transfers_history_clear():
    """Downloads page > select > Clear: those files leave the download log; the last one out deletes download_log.json."""
    if _guest():
        return jsonify(ok=True, removed=0)                # a LAN guest only hides things in their own browser
    ids = (request.get_json(force=True, silent=True) or {}).get("ids") or []
    return jsonify(ok=True, removed=dllog_remove([str(i) for i in ids][:5000]), left=len(DLLOG))


@bp_library.post("/api/transfers/clear")
def api_transfers_clear():
    with _xf_lock:
        for k in [k for k, x in XFERS.items() if x["status"] != "running"]:
            XFERS.pop(k, None)
    return jsonify(ok=True)


@bp_library.get("/media/<int:fid>")
def media(fid):
    return _serve(fid, True)


@bp_library.get("/download/<int:fid>")
def download(fid):
    return _serve(fid, False)


@bp_library.get("/api/hd/clear")
def hd_clear():
    """The HD view of a cloud-only picture ended (next / back / close): the original that was pulled back from Telegram for it
    is removed from the cache folder right away (otherwise the janitor does it after 30 minutes). Pictures that live on this phone are never touched."""
    fid = request.args.get("id", "")
    if not fid.isdigit():
        return jsonify(ok=False), 400
    fid = int(fid)
    for _hp in PREVIEWS.glob(f"hd{fid}_*"):               # the JPEG made for a HEIC picture's HD view goes away with the HD view
        _hp.unlink(missing_ok=True)
    if fid in TEMP_CACHE:
        TEMP_CACHE.pop(fid, None)
        try:
            with db() as c:
                r = c.execute("SELECT cache_name, source_path FROM files WHERE id=? AND status='backed_up'", (fid,)).fetchone()
                if r and r["cache_name"] and not (r["source_path"] and Path(r["source_path"]).is_file()):
                    (CACHE / r["cache_name"]).unlink(missing_ok=True)
                    c.execute("UPDATE files SET cache_name=NULL WHERE id=?", (fid,))
        except Exception:
            pass
    return jsonify(ok=True)


class _Sink(io.RawIOBase):
    """Write-only, non-seekable buffer so zip can be streamed to the browser."""
    def __init__(self):
        self.chunks, self.pos = [], 0
    def writable(self):
        return True
    def write(self, b):
        self.chunks.append(bytes(b)); self.pos += len(b); return len(b)
    def tell(self):
        return self.pos
    def drain(self):
        data, self.chunks = b"".join(self.chunks), []
        return data


@bp_library.get("/download/zip")
def download_zip():
    """?ids=1,2,3   or   ?all=1&kind=image|video"""
    if request.args.get("all"):
        kind = request.args.get("kind", "")
        with db() as c:
            rows = c.execute("SELECT * FROM files WHERE locked=0 AND trashed_at IS NULL" + (" AND kind=?" if kind else "") + " ORDER BY taken_at DESC",
                             (kind,) if kind else ()).fetchall()
    else:
        ids = [int(x) for x in request.args.get("ids", "").split(",") if x.strip().isdigit()][:5000]
        if not ids:
            return "No files selected", 400
        with db() as c:
            rows = c.execute(f"SELECT * FROM files WHERE id IN ({','.join('?' * len(ids))})", ids).fetchall()
        if not _unlocked():
            rows = [r for r in rows if not r["locked"]]                      # hidden photos are never zipped while the folder is locked
    if not rows:
        return "No files", 404
    fname = f"vault_{time.strftime('%Y%m%d_%H%M%S')}.zip"
    xid = xfer_begin("zip", fname, sum(int(r["size"] or 0) for r in rows), None, f"{len(rows)} files")

    def gen():
        sink, used = _Sink(), set()
        with zipfile.ZipFile(sink, "w", zipfile.ZIP_STORED, allowZip64=True) as zf:
            missing = []
            for r in rows:
                was_local = local_path(r) is not None
                p = None
                xfer_note(xid, ("" if was_local else "Fetching from Telegram: ") + r["name"])
                for attempt in range(3):                # a short Telegram hiccup must not silently drop a file from the ZIP
                    try:
                        p = restore_local(r)
                        break
                    except Exception as e:
                        if attempt == 2:
                            missing.append(f"{r['name']}: {e}")
                        else:
                            time.sleep(2)
                if p is None:
                    continue
                if not was_local and r["status"] == "backed_up":
                    TEMP_CACHE[r["id"]] = time.time()
                name, n = safe_name(r["name"]), 1
                while name in used:
                    n += 1
                    name = f"{Path(r['name']).stem}_{n}{Path(r['name']).suffix}"
                used.add(name)
                zi = zipfile.ZipInfo(name, time.localtime(p.stat().st_mtime)[:6])
                with zf.open(zi, "w", force_zip64=True) as dest, open(p, "rb") as src:
                    while True:
                        chunk = src.read(512 * 1024)
                        if not chunk:
                            break
                        dest.write(chunk)
                        data = sink.drain()
                        if data:
                            yield data
            if missing:                                 # tell the user exactly which files could not be fetched
                zf.writestr("_NOT_DOWNLOADED.txt", "These files could not be fetched:\n\n" + "\n".join(missing))
        xfer_end(xid, True)
        yield sink.drain()

    return Response(_Count(gen(), xid), mimetype="application/zip",
                    headers={"Content-Disposition": f'attachment; filename="{fname}"', "Cache-Control": "no-store"})


def drop_if_stale(row):
    """True when this library file was deleted in Telegram (and its stale row was removed), so the same file can be added again."""
    try:
        if row["status"] != "backed_up" or not row["message_id"] or not tl_ready():
            return False
        chat = row["chat_id"] or cfg_load()["chat_id"]
        mids = {int(row["message_id"])} | {int(x) for x in part_mids(row["id"])}
        gone = tl_run(_missing_msgs(chat, mids), 60)
        if not (gone & mids):
            return False
        mark_gone(chat, *mids)
        with db() as c:
            c.execute("DELETE FROM files WHERE id=?", (row["id"],))
            c.execute("DELETE FROM parts WHERE file_id=?", (row["id"],))
        purge_local(row["id"], row["cache_name"])
        return True
    except Exception:
        return False


@bp_library.post("/api/upload")
def upload():
    """Manual add from the browser (files are kept in storage/cache and queued for backup)."""
    items = [x for x in request.files.getlist("files") if x.filename]
    if not items:
        return jsonify(ok=False, error="Choose at least one file."), 400
    ensure_dirs()
    gst = _guest()
    results, added = [], 0
    _mt = request.form.getlist("mtimes")
    for _i, item in enumerate(items):
        original = item.filename.replace("\\", "/").split("/")[-1][:240] or "file"
        try:
            _t = float(_mt[_i]) / 1000.0
            taken = iso_from_ts(_t) if 0 < _t <= time.time() + 86400 else now()
        except Exception:
            taken = now()
        tmp = TMP / f"up_{time.time_ns()}.tmp"
        try:
            item.save(tmp)
            digest, size = sha256_file(tmp)
            with db() as c:
                old = c.execute("SELECT * FROM files WHERE sha256=?", (digest,)).fetchone()
            if old and drop_if_stale(old):
                old = None
            with db() as c:
                if old:
                    tmp.unlink(missing_ok=True)
                    results.append({"name": original, "duplicate": True})
                    continue
                cache_name = f"{digest[:12]}_{safe_name(original)}"
                os.replace(tmp, CACHE / cache_name)
                mime = item.mimetype or mimetypes.guess_type(original)[0]
                c.execute("""INSERT INTO files(name,kind,mime,size,sha256,cache_name,taken_at,added_at,status,uploader)
                             VALUES(?,?,?,?,?,?,?,?,'pending',?)""",
                          (original, kind_for(original, mime), mime, size, digest, cache_name, taken, now(), gst["uid"] if gst else None))
            added += 1
            results.append({"name": original, "duplicate": False})
            try:
                with db() as c:
                    _nr = c.execute("SELECT id FROM files WHERE sha256=?", (digest,)).fetchone()
                if _nr:
                    def _bg(i=_nr["id"]):
                        try:
                            rr = _row(i)
                            if rr:
                                make_thumb(rr)
                        except Exception:
                            pass
                    threading.Thread(target=_bg, daemon=True).start()
            except Exception:
                pass
        except Exception as e:
            tmp.unlink(missing_ok=True)
            results.append({"name": original, "error": str(e)})
    return jsonify(ok=True, added=added, results=results)


@bp_library.delete("/api/files/<int:fid>")
def delete_file(fid):
    """Remove from this library (index + cache + preview). Never deletes the original or the Telegram message."""
    r = _row(fid)
    if not r:
        return jsonify(ok=False, error="File not found"), 404
    with db() as c:
        c.execute("DELETE FROM files WHERE id=?", (fid,))
        c.execute("DELETE FROM parts WHERE file_id=?", (fid,))
    purge_local(fid, r["cache_name"])
    return jsonify(ok=True)


def purge_local(fid, cache_name=None):
    """Remove every local trace of one library file, whatever its type (photo, video, .py, .zip, .apk, .pdf ...):
    the cache copy, any half-downloaded '.part', temp thumbnail pulls, thumbnail and preview. The user's ORIGINAL file stays."""
    names = set()
    if cache_name:
        names.add(CACHE / cache_name)
    for d, pat in ((CACHE, f"{fid}_*"), (TMP, f"th_{fid}_*"), (TMP, f"dl_{fid}_*")):
        try:
            names.update(d.glob(pat))
        except OSError:
            pass
    for p in names:
        try:
            if p.is_dir():
                shutil.rmtree(p, ignore_errors=True)
            else:
                p.unlink(missing_ok=True)
        except OSError:
            pass
    for p in (thumb_path(fid), preview_path(fid)):
        p.unlink(missing_ok=True)
    for p in list(PREVIEWS.glob(f"rot{fid}_*")) + list(PREVIEWS.glob(f"hd{fid}_*")):
        p.unlink(missing_ok=True)
    shutil.rmtree(TMP / "stream" / str(fid), ignore_errors=True)
    TEMP_CACHE.pop(fid, None)
    THUMB_FAIL.pop(fid, None)


def mark_gone(chat_id, *mids):
    """Remember messages we deleted on purpose so a later Sync can never bring them back."""
    with db() as c:
        for m in mids:
            if m:
                c.execute("INSERT INTO kv(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                          (f"gone:{chat_id}:{m}", "1"))


def _tg_delete_one(cid, mid, bots):
    """Delete ONE Telegram message and make sure it is really gone.
    1) every bot is tried (the uploader first). 'message to delete not found' from ONE bot does NOT mean the message is
       gone (a different bot / your account may own it), so the next bot is tried instead of stopping.
    2) the logged-in account then CHECKS whether the message still exists; if it does, the account deletes it.
    Raises when the message is still there, so the file stays in Recently Deleted and the error is shown."""
    last, bot_ok, not_found = None, False, False
    for b in bots:
        for attempt in range(6):
            try:
                tgapi_call(b["token"], "deleteMessage", {"chat_id": cid, "message_id": mid}, timeout=30)
                bot_ok = True
                break
            except TgRetry as e:
                last = e
                time.sleep(min(e.retry_after + 1, 30))
            except RuntimeError as e:
                last = e
                if "message to delete not found" in str(e).lower():
                    not_found = True
                    break                               # maybe another bot / the account owns it -> keep trying
                if "Network error" in str(e) and attempt < 2:
                    time.sleep(2)
                    continue
                break                                   # this bot may not delete it -> next bot
        if bot_ok:
            break
    if tl_ready():
        try:
            still = tl_exists(cid, mid)
        except Exception as e:
            still, last = None, e                       # could not check -> fall back to what the bots said
        if still is False:
            return
        if still:
            try:
                tl_delete(cid, [mid])
            except Exception as e:
                last = e
            try:
                if not tl_exists(cid, mid):
                    return
            except Exception:
                if not last:
                    return
            raise RuntimeError("Telegram still shows this file: give the bot / your account the 'Delete messages' "
                               "admin right in the channel" + (f" ({str(last)[:120]})" if last else "") + ".")
    if bot_ok or (not_found and not tl_ready()):
        return                                          # cannot double-check (no account login): trust the bots
    raise RuntimeError(str(last) if last else "No bot is connected to delete this message.")


def delete_remote(row, bots):
    # Delete the Telegram copy of a file: the file message (or ALL its part messages) AND its small thumb.jpg message.
    cid = row["chat_id"] or cfg_load()["chat_id"]
    mids = part_mids(row["id"])
    if not mids and row["message_id"]:
        mids = [int(row["message_id"])]
    if not (cid and mids):
        return
    ordered = sorted(bots, key=lambda b: 0 if b["name"] == row["bot_name"] else 1)
    for m in mids:
        _tg_delete_one(cid, int(m), ordered)
    th_ids = [int(row["thumb_message_id"])] if row["thumb_message_id"] else []
    if not th_ids and tl_ready():                       # thumbnail id not saved: look for the "VT <id>" thumb.jpg message next to the file
        try:
            for lst in tl_find_thumbs(cid, [int(m) for m in mids]).values():
                th_ids += lst
        except Exception:
            pass
    for t in th_ids:
        try:
            _tg_delete_one(cid, int(t), ordered)
        except Exception:
            pass                                        # a leftover thumbnail must not block removing the file


def delete_remote_batch(rows, bots):
    """Delete the Telegram copies of MANY files at once (all part messages + thumbnails).
    1) logged-in account: 100 messages per request + one verification call  (very fast)
    2) only messages that survived go through the slow per-message path (bots, 8 in parallel).
    Returns {file_id: error_text}; files that are not in the dict were removed completely."""
    from concurrent.futures import ThreadPoolExecutor
    errors, by_chat = {}, {}
    for r in rows:
        cid = r["chat_id"] or cfg_load()["chat_id"]
        mids = [int(m) for m in part_mids(r["id"])]
        if not mids and r["message_id"]:
            mids = [int(r["message_id"])]
        if not (cid and mids):
            continue
        thumb = int(r["thumb_message_id"]) if r["thumb_message_id"] else None
        by_chat.setdefault(cid, []).append((r, mids, thumb))
    for cid, items in by_chat.items():
        extra = set()                                   # thumbnails whose message id the library never saved: found by their "VT <id>" caption
        if tl_ready():
            need = [m for _, mids, th in items if not th for m in mids]
            if need:
                try:
                    for lst in tl_find_thumbs(cid, need).values():
                        extra.update(lst)
                except Exception:
                    pass
        everything = sorted({m for _, mids, th in items for m in mids + ([th] if th else [])} | extra)
        # SAFETY: never delete a Telegram message that another (kept) library file still points to
        doomed = {r["id"] for r, _, _ in items}
        with db() as c:
            used = set()
            for fr in c.execute("SELECT id,message_id,thumb_message_id FROM files").fetchall():
                if fr["id"] in doomed:
                    continue
                for v in (fr["message_id"], fr["thumb_message_id"]):
                    if v:
                        used.add(int(v))
            for pr in c.execute("SELECT file_id,message_id FROM parts WHERE message_id IS NOT NULL").fetchall():
                if pr["file_id"] not in doomed:
                    used.add(int(pr["message_id"]))
        everything = [m for m in everything if m not in used]
        left = set(everything)
        if tl_ready():
            try:
                left = set(tl_purge(cid, everything))
            except Exception:
                left = set(everything)
        if left:
            def one(mid):
                try:
                    _tg_delete_one(cid, mid, bots)
                    return mid, None
                except Exception as e:
                    return mid, str(e)[:200]
            with ThreadPoolExecutor(max_workers=8) as ex:
                bad = dict(ex.map(one, sorted(left)))
        else:
            bad = {}
        for r, mids, th in items:
            for m in mids:                                  # a leftover thumbnail never blocks the file
                if bad.get(m):
                    errors[r["id"]] = bad[m]
                    break
    return errors


@bp_library.post("/api/files/delete")
def delete_many():
    d = request.get_json(force=True, silent=True) or {}
    ids = [int(x) for x in d.get("ids", []) if str(x).isdigit()][:3000]
    remote = d.get("remote", True)
    gst = _guest()
    if gst:
        with db() as c:
            own = []
            for fid in ids:
                row = c.execute("SELECT uploader FROM files WHERE id=?", (fid,)).fetchone()
                if row and row["uploader"] and row["uploader"] == gst["uid"]:
                    own.append(fid)
        if not own:
            return jsonify(ok=False, error="You can delete only the files you uploaded."), 403
        ids, d = own, {}
    if not d.get("permanent"):      # normal delete = move to Recently Deleted; nothing is removed from Telegram yet
        n = 0
        with db() as c:
            for fid in ids:
                n += c.execute("UPDATE files SET trashed_at=? WHERE id=? AND trashed_at IS NULL", (now(), fid)).rowcount
        _bk_kick()
        return jsonify(ok=True, deleted=n, trashed=n, failed=[])
    bots = cfg_bots()
    done, failed = 0, []
    rows = [r for r in (_row(fid) for fid in ids) if r]
    errs = {}
    if remote and rows:
        errs = delete_remote_batch(rows, bots)
    for r in rows:
        fid = r["id"]
        if fid in errs:
            failed.append({"id": fid, "name": r["name"], "error": errs[fid]})
            continue
        cid = r["chat_id"] or cfg_load()["chat_id"]
        if remote and cid:
            mark_gone(cid, r["message_id"], r["thumb_message_id"], *part_mids(fid))
        with db() as c:
            c.execute("DELETE FROM files WHERE id=?", (fid,))
            c.execute("DELETE FROM parts WHERE file_id=?", (fid,))
        purge_local(fid, r["cache_name"])
        done += 1
    return jsonify(ok=True, deleted=done, failed=failed)


def _tg_rename_caption(row, newname):
    """Best effort: the caption under the Telegram message carries NAME: - update it (single-message files, sent by one of our bots)."""
    try:
        d = cfg_load()
        cid = row["chat_id"] or d["chat_id"]
        if not (d["vault_code"] and cid and row["message_id"]) or part_mids(row["id"]):
            return
        sha = row["sha256"] if row["sha256"] and not str(row["sha256"]).startswith("cloud:") else None
        cap = make_caption(d["vault_code"], newname, sha)
        for b in cfg_bots():
            try:
                tgapi_call(b["token"], "editMessageCaption", {"chat_id": cid, "message_id": int(row["message_id"]), "caption": cap})
                return
            except Exception:
                continue
    except Exception:
        pass


@bp_library.post("/api/files/<int:fid>/rename")
def rename_file(fid):
    """Rename = the real file on the phone (original location and / or cache), the name in the library (grid + info) and, when
    possible, the caption in Telegram."""
    if _guest():
        return jsonify(ok=False, error="Not allowed."), 403
    d = request.get_json(force=True, silent=True) or {}
    row = _row(fid)
    if not row:
        abort(404)
    new = safe_name(str(d.get("name", "")).strip())[:120]
    if not new or new in (".", ".."):
        return jsonify(ok=False, error="Type a file name."), 400
    old_ext = Path(row["name"] or "").suffix
    if not Path(new).suffix and old_ext:
        new = (new + old_ext)[:120]
    if new == row["name"]:
        return jsonify(ok=True, name=new)
    sp, cache = row["source_path"], row["cache_name"]
    new_sp = new_cache = None
    if sp and Path(sp).is_file():
        t = Path(sp).with_name(new)
        if t.exists():
            return jsonify(ok=False, error="A file with this name already exists in that folder."), 400
        try:
            os.rename(sp, t)
        except OSError as e:
            return jsonify(ok=False, error=f"Could not rename the file: {e}"), 400
        new_sp = str(t)
    if cache and (CACHE / cache).is_file():
        nc = (cache.split("_", 1)[0] + "_" + new) if "_" in cache else new
        if nc != cache and not (CACHE / nc).exists():
            try:
                os.rename(CACHE / cache, CACHE / nc)
                new_cache = nc
            except OSError:
                pass
    with db() as c:
        c.execute("UPDATE files SET name=?, source_path=COALESCE(?, source_path), cache_name=COALESCE(?, cache_name) WHERE id=?",
                  (new, new_sp, new_cache, fid))
    if row["status"] == "backed_up":
        threading.Thread(target=_tg_rename_caption, args=(row, new), daemon=True, name="rename-caption").start()
    return jsonify(ok=True, name=new)


