bp_backup = Blueprint("backup_api", __name__)


@bp_backup.post("/api/backup")
def start_backup():
    return jsonify(ok=True, job_id=job_submit("backup", "Back up now", run_full)["id"])


def _restore_favs(job=None):
    """Put the favorites that Reload Cloud Vault remembered back (matched by Telegram message, or by the file's hash). Returns how many."""
    if not FAV_KEEP.exists():
        return 0
    try:
        items = json.loads(sec_read(FAV_KEEP))
    except Exception:
        FAV_KEEP.unlink(missing_ok=True)
        return 0
    n = 0
    with db() as c:
        for it in items:
            w = (str(it.get("c") or ""), it.get("m"), it.get("s") or "")
            if it.get("f", 1):
                n += c.execute("UPDATE files SET fav=1 WHERE fav=0 AND ((chat_id=? AND message_id=?) OR sha256=?)", w).rowcount
            if it.get("r"):
                c.execute("UPDATE files SET rot=? WHERE rot=0 AND ((chat_id=? AND message_id=?) OR sha256=?)", (int(it["r"]),) + w)
            if it.get("t"):
                c.execute("UPDATE files SET trashed_at=? WHERE trashed_at IS NULL AND ((chat_id=? AND message_id=?) OR sha256=?)", (str(it["t"]),) + w)
    if job is not None:
        job_log(job, f"Favorites put back: {n}")
    return n


def run_sync_fav(job, full=False):
    """Sync, then (only if Reload Cloud Vault left favorites waiting) put the favorites back. The note stays until a sync finished without error."""
    run_sync(job, full)
    _restore_favs(job)
    if not job.get("error") and not job.get("cancel"):
        FAV_KEEP.unlink(missing_ok=True)


@bp_backup.post("/api/sync")
def start_sync():
    full = bool((request.get_json(force=True, silent=True) or {}).get("full"))
    label = "Full sync" if full else "Sync now"
    return jsonify(ok=True, job_id=job_submit("sync", label, run_sync_fav, full)["id"])


@bp_backup.post("/api/vault/reload")
def vault_reload():
    """Settings > Reload Cloud Vault: vault.sqlite3 (the library index) is deleted, a new empty one is made, and a full Sync loads the whole
    library again from Telegram. Settings, Telegram login, bots and vault code live in storage/config and are never touched."""
    global _db_ready
    with LOCK:
        if any(j["status"] in ("queued", "running") for j in JOBS.values()):
            return jsonify(ok=False, error="A backup/sync job is running - stop it first."), 409
    try:
        freed, _n = _clear_cache_core()           # Clear cache runs first (it needs the index to know which copies are safe in Telegram)
    except Exception:
        freed = 0
    _lock_keep_write()                            # hidden photos are remembered too: they stay hidden once the library is loaded again
    try:                                          # favorites are remembered first (Telegram message + hash); the file is only deleted after a sync that finished
        with db() as c:
            favs = [{"c": str(r["chat_id"] or ""), "m": r["message_id"], "s": r["sha256"]}
                    for r in c.execute("SELECT chat_id, message_id, sha256 FROM files WHERE fav=1").fetchall()]
        ensure_dirs()
        tmpf = FAV_KEEP.with_suffix(".tmp")
        sec_write(tmpf, json.dumps(favs))
        os.replace(tmpf, FAV_KEEP)
    except Exception as e:
        return jsonify(ok=False, error=f"Could not remember your favorites, nothing was deleted: {e}"), 500
    with _db_guard:
        _db_ready = False
        for suf in ("", "-wal", "-shm", "-journal"):
            try:
                Path(str(DB) + suf).unlink(missing_ok=True)
            except OSError:
                pass
    TEMP_CACHE.clear()
    THUMB_FAIL.clear()
    _db_ensure()                      # new empty index (the old previews / thumbnails are named after the old ids, so they are removed there)
    job_id = None
    if not need_setup():
        job_id = job_submit("sync", "Reload Cloud Vault", run_sync_fav, True)["id"]
    return jsonify(ok=True, job_id=job_id, freed_human=human_size(freed), favs=len(favs))


