@bp_backup.post("/api/files/clear")
def clear_waiting_files():
    """Backup page -> 'Clear pending' / 'Clear failed': take those files out of the queue.
    Files that only exist in the vault cache (added with 'Add files') are deleted; files that live on the device are just excluded."""
    st = "failed" if (request.get_json(force=True, silent=True) or {}).get("status") == "failed" else "pending"
    with LOCK:
        if any(j["status"] in ("queued", "running") for j in JOBS.values()):
            return jsonify(ok=False, error="A backup/sync job is running - stop it first."), 409
    with db() as c:
        rows = c.execute("SELECT id,cache_name,source_path FROM files WHERE status=? AND skip=0 AND trashed_at IS NULL", (st,)).fetchall()
    for r in rows:
        if r["source_path"]:
            with db() as c:
                c.execute("UPDATE files SET skip=1, error=NULL WHERE id=?", (r["id"],))
        else:
            with db() as c:
                c.execute("DELETE FROM files WHERE id=?", (r["id"],))
                c.execute("DELETE FROM parts WHERE file_id=?", (r["id"],))
            purge_local(r["id"], r["cache_name"])
    return jsonify(ok=True, removed=len(rows))


def _waiting_rows(status, err=None, q=""):
    """Files shown in the Backup page 3-dot lists. Same rules as the counters on the page (excluded files are left out)."""
    enabled = [f["path"] for f in cfg_get("folders") if f["enabled"]]
    sql = "SELECT * FROM files WHERE " + ("" if status == "local" else "locked=0 AND ") + "trashed_at IS NULL AND "   # 'local' counts hidden files too (like the counter)
    args = []
    if status in ("done", "local"):
        sql += "status='backed_up'"
    else:
        sql += "status=? AND skip=0"
        args.append("failed" if status == "failed" else "pending")
    if err is not None:
        sql += " AND COALESCE(error,'')=?"
        args.append(err)
    if q:
        sql += " AND name LIKE ?"
        args.append("%" + q.replace("%", "").replace("_", "") + "%")
    sql += " ORDER BY id DESC" if status in ("done", "local") else " ORDER BY taken_at DESC, id DESC"
    with db() as c:
        rows = c.execute(sql, args).fetchall()
    if status == "local":                              # backed up AND a copy is still on this phone (same rule as the 'local' counter)
        rows = [r for r in rows if local_path(r)]
    elif status != "done":
        rows = [r for r in rows if not r["folder"] or r["folder"] in enabled]
    return rows


@bp_backup.get("/api/backup/list")
def backup_list():
    """3-dot menu on the Backup page: status = pending | failed | done | error."""
    st = request.args.get("status", "pending")
    if st not in ("pending", "failed", "done", "error", "local"):
        return jsonify(ok=False, error="bad status"), 400
    if st == "error":                                  # failed files grouped by the reason Telegram / the app gave
        groups = {}
        for r in _waiting_rows("failed"):
            g = groups.setdefault(r["error"] or "", {"error": r["error"] or "Unknown error", "raw": r["error"] or "", "count": 0, "names": [], "tries": 0})
            g["count"] += 1
            g["tries"] = max(g["tries"], int(r["tries"] or 0))
            if len(g["names"]) < 3:
                g["names"].append(r["name"])
        return jsonify(ok=True, groups=sorted(groups.values(), key=lambda g: -g["count"]))
    try:
        off = max(0, int(request.args.get("offset", 0)))
        lim = max(1, min(500, int(request.args.get("limit", 150))))
    except ValueError:
        off, lim = 0, 150
    err = request.args.get("err")
    rows = _waiting_rows(st, err if err is not None else None, (request.args.get("q") or "").strip()[:80])
    hidden = 0
    if st == "local" and not _unlocked():              # files of the Locked Folder: counted, but their names stay hidden while it is locked
        hidden = sum(1 for r in rows if r["locked"])
        rows = [r for r in rows if not r["locked"]]
    items = []
    for r in rows[off:off + lim]:
        j = to_json(r)
        j["tries"] = int(r["tries"] or 0)
        if st == "local":
            j["orig"] = bool(r["source_path"] and Path(r["source_path"]).is_file())     # the local copy is the user's own original file
        items.append(j)
    return jsonify(ok=True, items=items, total=len(rows), offset=off, hidden=hidden, bytes=sum(int(r["size"] or 0) for r in rows))


def _ids_of(d):
    return [int(x) for x in (d.get("ids") or []) if str(x).isdigit()][:5000]


@bp_backup.post("/api/files/<int:fid>/restore_thumb")
def restore_thumb(fid):
    """Viewer -> 'Restore thumbnail' (works on EVERY photo): the thumbnail is rebuilt from the file itself (pulled from Telegram if needed)
    and posted to Telegram. If the photo already had a thumb.jpg message, the new one replaces it (old one is deleted only after the new one is safe)."""
    if _guest():
        return jsonify(ok=False, error="Not allowed."), 403
    row = _row(fid)
    if not row or not _thumb_restorable(row):
        return jsonify(ok=False, error="This file cannot get a thumbnail."), 409
    bots = cfg_bots()
    if not bots or not cfg_load().get("chat_id") or not cfg_load().get("vault_code"):
        return jsonify(ok=False, error="Bot / chat / vault code is not set up."), 400
    old_mid = int(row["thumb_message_id"] or 0)
    try:
        # 1) the thumbnail already sits in Telegram -> only download it (NO new upload, no duplicate thumb.jpg message)
        if tl_ready():
            st, _p = _linked_thumb(row, force=True)
            if st == "ok":
                return jsonify(ok=True, v=int(time.time()), existed=True)
            if st == "error":
                return jsonify(ok=False, error="Telegram did not answer - try again (nothing was uploaded)."), 502
        elif old_mid:
            lp = thumb_path(fid)
            if (lp.exists() and lp.stat().st_size > 0) or fetch_bot_thumb(row):
                return jsonify(ok=True, v=int(time.time()), existed=True)
        # 2) really no thumbnail in Telegram (it was deleted there) -> build a new one from the file and upload it once
        if old_mid:
            with db() as c:
                c.execute("UPDATE files SET thumb_message_id=NULL, thumb_file_id=NULL WHERE id=?", (fid,))
            old_mid = 0
            thumb_path(fid).unlink(missing_ok=True)
        if not _thumb_from_file(row):
            return jsonify(ok=False, error="Could not build a thumbnail from this file."), 500
        for b in _bots_for(row)[:3]:
            th = upload_thumb(row, b, int(row["message_id"]))
            if th:
                with db() as c:
                    c.execute("UPDATE files SET thumb_file_id=?, thumb_message_id=? WHERE id=?", (th[0], th[1], fid))
                    c.execute("DELETE FROM kv WHERE key=?", (f"thumbup:{fid}",))
                if old_mid and old_mid != int(th[1]) and row["chat_id"]:
                    try:
                        tl_purge(row["chat_id"], [old_mid])    # old thumb.jpg message goes away (best effort)
                    except Exception:
                        pass
                return jsonify(ok=True, v=int(time.time()))
    except Exception as e:
        return jsonify(ok=False, error=str(e)[:200]), 500
    return jsonify(ok=False, error="Thumbnail could not be posted to Telegram - try again."), 502


@bp_backup.post("/api/backup/orphan/<int:fid>/file")
def backup_orphan_file(fid):
    """Pending list: a thumbnail without its file ('File is not available') - the chosen file is accepted and uploaded."""
    item = request.files.get("file")
    if not item or not item.filename:
        return jsonify(ok=False, error="Choose a file."), 400
    row = _row(fid)
    if not row or not _is_orphan(row):
        return jsonify(ok=False, error="This item is not waiting for its file any more."), 409
    ensure_dirs()
    tmp = TMP / f"up_{time.time_ns()}.tmp"
    try:
        item.save(tmp)
        digest, size = sha256_file(tmp)
        with db() as c:
            old = c.execute("SELECT * FROM files WHERE sha256=? AND id<>?", (digest, fid)).fetchone()
        if old and drop_if_stale(old):
            old = None
        if old:
            tmp.unlink(missing_ok=True)
            return jsonify(ok=False, error="This file is already in your library."), 409
        original = item.filename.replace("\\", "/").split("/")[-1][:240] or "file"
        keep = row["name"] and not row["name"].startswith("thumb VT ")
        name = row["name"] if keep else original
        mime = item.mimetype or mimetypes.guess_type(original)[0]
        cache_name = f"{digest[:12]}_{safe_name(original)}"
        os.replace(tmp, CACHE / cache_name)
        with db() as c:
            c.execute("UPDATE files SET name=?, kind=?, mime=?, size=?, sha256=?, cache_name=?, status='pending', error=NULL, tries=0, skip=0 WHERE id=?",
                      (name, kind_for(name, mime), mime, size, digest, cache_name, fid))
    except Exception as e:
        tmp.unlink(missing_ok=True)
        return jsonify(ok=False, error=str(e)), 500
    return jsonify(ok=True, job_id=job_submit("backup", f"Back up {name}", run_selected, [fid])["id"])


@bp_backup.post("/api/backup/selected")
def backup_selected():
    """Pending / Failed list: 'Backup start' for the ticked files only."""
    ids = _ids_of(request.get_json(force=True, silent=True) or {})
    if not ids:
        return jsonify(ok=False, error="Nothing selected."), 400
    q = ",".join("?" * len(ids))
    with db() as c:
        c.execute(f"UPDATE files SET status='pending', error=NULL, skip=0 WHERE status IN ('pending','failed') AND trashed_at IS NULL AND id IN ({q})", ids)
        n = c.execute(f"SELECT COUNT(*) n FROM files WHERE status='pending' AND trashed_at IS NULL AND id IN ({q})", ids).fetchone()["n"]
    if not n:
        return jsonify(ok=False, error="These files are not waiting any more."), 409
    return jsonify(ok=True, count=n, job_id=job_submit("backup", f"Back up selected ({n})", run_selected, ids)["id"])


@bp_backup.post("/api/backup/remove")
def backup_remove():
    """Pending / Failed list: take the ticked files out of the queue (same rules as 'Clear pending / Clear failed')."""
    ids = _ids_of(request.get_json(force=True, silent=True) or {})
    if not ids:
        return jsonify(ok=False, error="Nothing selected."), 400
    with LOCK:
        if any(j["status"] in ("queued", "running") for j in JOBS.values()):
            return jsonify(ok=False, error="A backup/sync job is running - stop it first."), 409
    q = ",".join("?" * len(ids))
    with db() as c:
        rows = c.execute(f"SELECT id,cache_name,source_path FROM files WHERE status IN ('pending','failed') AND trashed_at IS NULL AND id IN ({q})", ids).fetchall()
    for r in rows:
        if r["source_path"]:
            with db() as c:
                c.execute("UPDATE files SET skip=1, error=NULL WHERE id=?", (r["id"],))
        else:
            with db() as c:
                c.execute("DELETE FROM files WHERE id=?", (r["id"],))
                c.execute("DELETE FROM parts WHERE file_id=?", (r["id"],))
            purge_local(r["id"], r["cache_name"])
    return jsonify(ok=True, removed=len(rows))


@bp_backup.post("/api/backup/remove_local")
def backup_remove_local():
    """Backup page > Local: delete the phone copy of the ticked files. Only files that are already in Telegram (backed_up) are touched,
    they stay in the library as cloud files. The user's ORIGINAL file (a file in a watched folder) is never deleted."""
    ids = _ids_of(request.get_json(force=True, silent=True) or {})
    if not ids:
        return jsonify(ok=False, error="Nothing selected."), 400
    with LOCK:
        if any(j["status"] in ("queued", "running") for j in JOBS.values()):
            return jsonify(ok=False, error="A backup/sync job is running - stop it first."), 409
    q = ",".join("?" * len(ids))
    with db() as c:
        rows = c.execute(f"SELECT * FROM files WHERE status='backed_up' AND trashed_at IS NULL AND id IN ({q})", ids).fetchall()
    if not _unlocked():
        rows = [r for r in rows if not r["locked"]]     # hidden files can only be handled while the Locked Folder is open
    removed = kept = 0
    for r in rows:
        purge_local(r["id"], r["cache_name"])
        with db() as c:
            c.execute("UPDATE files SET cache_name=NULL WHERE id=?", (r["id"],))
        TEMP_CACHE.pop(r["id"], None)
        if local_path(_row(r["id"])):
            kept += 1                                   # the original file is still there: it is not ours to delete
        else:
            removed += 1
    _ftp_forget()
    return jsonify(ok=True, removed=removed, kept=kept)


@bp_backup.get("/api/disk")
def disk_info():
    """Real size of everything uploaded to Telegram so far (files in Recently Deleted still count: they are still in Telegram),
    plus what is still waiting - used by the Browse storage line."""
    with db() as c:
        up = c.execute("SELECT COALESCE(SUM(size),0) n FROM files WHERE status='backed_up'").fetchone()["n"]
        wait = c.execute("SELECT COALESCE(SUM(size),0) n FROM files WHERE status IN ('pending','failed') "
                         "AND skip=0 AND trashed_at IS NULL").fetchone()["n"]
    return jsonify(ok=True, used=int(up), pending=int(wait))


def _roots():
    cands = ["/storage/emulated/0", "/sdcard", str(Path.home()), "/"]
    return [c for c in cands if os.path.isdir(c)]


@bp_backup.get("/api/fs/list")
def fs_list():
    """Folder picker for 'Manage Backup Folders' (folders of the device that runs this server)."""
    path = request.args.get("path") or (_roots() or ["/"])[0]
    p = Path(path).expanduser()
    try:
        p = p.resolve()
        dirs = sorted((d for d in p.iterdir() if d.is_dir() and not d.name.startswith(".")), key=lambda d: d.name.lower())
    except Exception as e:
        return jsonify(ok=False, error=f"Cannot open this folder: {e}"), 400
    media = 0
    try:
        media = sum(1 for f in p.iterdir() if f.is_file() and f.suffix.lower() in MEDIA_EXT)
    except Exception:
        pass
    return jsonify(ok=True, path=str(p), parent=str(p.parent) if p.parent != p else None, media=media,
                   dirs=[{"name": d.name, "path": str(d)} for d in dirs[:500]], roots=_roots())


