@bp_tg.post("/api/bot/verify")
def bot_verify():
    d = request.get_json(force=True, silent=True) or {}
    cur = cfg_load()
    token = str(d.get("token") or cur["bot_token"]).strip()
    chat = str(d.get("chat_id") or cur["chat_id"]).strip()
    if not token or not chat:
        return _err("Bot token and Chat ID are required.")
    if not TOKEN_RE.fullmatch(token):
        return _err("The bot token looks invalid (it should look like 123456789:ABC...).")
    try:
        msg, _ = tgapi_verify(token, chat)
        return jsonify(ok=True, message=msg)
    except Exception as e:
        return _err(e)


@bp_tg.post("/api/bots/health")
def bots_health():
    """Bot health screen: is every bot working, how many uploads it did, when its rate limit ends. {check:true} also asks Telegram."""
    d = request.get_json(force=True, silent=True) or {}
    bots, chat = cfg_bots(), cfg_get("chat_id")
    if d.get("check") and chat:
        def one(b):
            st = _bs(b["token"])
            try:
                tgapi_verify(b["token"], chat)
                st["live"], st["live_err"], st["dead"] = True, "", False
            except Exception as e:
                st["live"], st["live_err"] = False, str(e)[:160]
            st["live_at"] = time.time()
        with concurrent.futures.ThreadPoolExecutor(max_workers=8) as ex:
            list(ex.map(one, bots))
    today = datetime.now().strftime("%Y-%m-%d")
    with db() as c:
        total = {r["bot_name"]: r["n"] for r in c.execute("SELECT bot_name, COUNT(*) n FROM files WHERE status='backed_up' AND bot_name IS NOT NULL GROUP BY bot_name")}
        for r in c.execute("SELECT bot_name, COUNT(*) n FROM parts WHERE message_id IS NOT NULL AND bot_name IS NOT NULL GROUP BY bot_name"):
            total[r["bot_name"]] = total.get(r["bot_name"], 0) + r["n"]
        day = {r["bot_name"]: r["n"] for r in c.execute("SELECT bot_name, COUNT(*) n FROM files WHERE status='backed_up' AND backed_at LIKE ? GROUP BY bot_name", (today + "%",))}
    t, out = time.time(), []
    for b in bots:
        st = _bs(b["token"])
        limit = max(st["limit_until"], TG_COOLDOWN[0]) - t
        if st["dead"] or st.get("live") is False:
            state, why = "down", st.get("live_err") if st.get("live") is False else st["last_err"]
        elif limit > 0:
            state, why = "limited", ""
        else:
            state, why = "ok", ""
        tot = st["ok"] + st["fail"]
        if state == "down":
            hp = 0
        elif state == "limited":
            hp = 50 - min(limit, 300) / 300 * 30            # just limited ~50, a long wait ~20
        else:
            hp = 100 - (st["fail"] / tot * 60 if tot else 0) - (20 if t - st["err_at"] < 600 and st["last_err"] else 0)
        out.append({"health": int(max(0, min(100, hp))), "name": b["name"], "token": b["token"][:6] + "..." + b["token"][-4:], "state": state, "why": why or "",
                    "uploads": total.get(b["name"], 0), "today": day.get(b["name"], 0), "session_ok": st["ok"], "session_fail": st["fail"],
                    "limit_in": int(limit) + 1 if limit > 0 else 0, "last_err": st["last_err"], "checked": bool(st.get("live_at"))})
    return jsonify(ok=True, bots=out)


@bp_tg.post("/api/bot/add")
def bot_add():
    d = request.get_json(force=True, silent=True) or {}
    cur = cfg_load()
    token = str(d.get("token", "")).strip()
    if not cur["chat_id"]:
        return _err("Set the Chat ID in Account first - all bots send to the same channel.")
    if not TOKEN_RE.fullmatch(token):
        return _err("The bot token looks invalid.")
    if token == cur["bot_token"] or any(b["token"] == token for b in cur["bot_pool"]):
        return _err("This bot is already added.")
    if len(cur["bot_pool"]) >= MAX_BOTS:
        return _err(f"Bot pool is full ({MAX_BOTS}).")
    try:
        msg, info = tgapi_verify(token, cur["chat_id"])
    except Exception as e:
        return _err(e)
    name = ("@" + info["username"]) if info.get("username") else (str(d.get("name") or "Bot"))
    pool = cur["bot_pool"] + [{"name": name, "token": token}]
    return jsonify(ok=True, message=msg, config=cfg_update({"bot_pool": pool}))


@bp_tg.post("/api/bot/disconnect")
def bot_disconnect():
    return jsonify(ok=True, config=cfg_update({"bot_token": "", "chat_id": ""}))


@bp_tg.post("/api/bot/add_many")
def bot_add_many():
    """Add many bots at once (one token per line). Tokens are verified in parallel."""
    d = request.get_json(force=True, silent=True) or {}
    cur = cfg_load()
    if not cur["chat_id"]:
        return _err("Set the Chat ID in Account first - all bots send to the same channel.")
    raw = d.get("tokens", "")
    items = raw if isinstance(raw, list) else re.split(r"[\s,;]+", str(raw))
    known = {cur["bot_token"]} | {b["token"] for b in cur["bot_pool"]}
    todo, seen, failed = [], set(), []
    for t in items:
        t = str(t).strip()
        if not t or t in seen:
            continue
        seen.add(t)
        tag = t[:6] + "..." + t[-4:] if len(t) > 12 else t
        if not TOKEN_RE.fullmatch(t):
            failed.append({"token": tag, "error": "token format is invalid"})
        elif t in known:
            failed.append({"token": tag, "error": "already added"})
        else:
            todo.append(t)
    room = max(0, MAX_BOTS - len(cur["bot_pool"]))
    for t in todo[room:]:
        failed.append({"token": t[:6] + "..." + t[-4:], "error": f"limit of {MAX_BOTS} bots reached"})
    todo = todo[:room]
    if not todo and not failed:
        return _err("Paste at least one bot token.")

    def check(t):
        try:
            _, info = tgapi_verify(t, cur["chat_id"])
            return t, (("@" + info["username"]) if info.get("username") else "Bot"), None
        except Exception as e:
            return t, None, str(e).replace(t, "***")

    added = []
    if todo:
        with concurrent.futures.ThreadPoolExecutor(max_workers=6) as ex:
            for t, name, err in ex.map(check, todo):
                if err:
                    failed.append({"token": t[:6] + "..." + t[-4:], "error": err[:160]})
                else:
                    added.append({"name": name, "token": t})
    cfg = cfg_load()
    if added:
        cfg = cfg_update({"bot_pool": cfg["bot_pool"] + added})
    msg = f"Added {len(added)} bot(s)" + (f", {len(failed)} skipped/failed" if failed else "") + f". Pool: {len(cfg['bot_pool'])}."
    return jsonify(ok=True, message=msg, added=len(added), failed=failed, config=cfg)


# ── chat viewer (read-only; uses the logged-in Telegram account, nothing is ever sent or deleted) ──
CHATVIEW = STORAGE / "chatview"
CV_SEM = threading.BoundedSemaphore(4)
CV_FULL_MAX = 30 * 1024 * 1024
CV_TTL = 6 * 3600
_cv_pruned = [0.0]


def _cv_name(ent):
    n = " ".join(x for x in (getattr(ent, "first_name", None), getattr(ent, "last_name", None)) if x)
    return n or getattr(ent, "title", None) or getattr(ent, "username", None) or "Unknown"


def _cv_kind(m):
    mime = (getattr(getattr(m, "file", None), "mime_type", "") or "")
    if getattr(m, "photo", None):
        return "photo"
    if getattr(m, "sticker", None):
        return "sticker"
    if getattr(m, "gif", None) or getattr(m, "video", None) or getattr(m, "video_note", None):
        return "video"
    if getattr(m, "voice", None):
        return "voice"
    if getattr(m, "audio", None):
        return "audio"
    if getattr(m, "document", None):
        return "photo" if mime.startswith("image/") else "file"
    return "text"


def _cv_msg(m):
    if getattr(m, "action", None) and not m.message and not getattr(m, "media", None):
        return None                                   # "X joined", pinned notice ... not shown
    s = getattr(m, "sender", None)
    f = getattr(m, "file", None)
    return {"id": m.id, "date": m.date.astimezone().isoformat(timespec="seconds") if m.date else "",
            "sender": _cv_name(s) if s else (getattr(m, "post_author", None) or ""),
            "text": (m.message or "")[:4000], "kind": _cv_kind(m),
            "name": (getattr(f, "name", None) or "") if f else "",
            "size": int(getattr(f, "size", 0) or 0) if f else 0}


async def _cv_list(chat_id, limit, before, after):
    c = await _client()
    ent = await _entity(c, chat_id)
    kw = {"limit": limit}
    if before:
        kw["offset_id"] = before
    if after:
        kw["min_id"] = after
    out, got = [], 0
    async for m in c.iter_messages(ent, **kw):
        got += 1
        d = _cv_msg(m)
        if d:
            out.append(d)
    out.reverse()
    return {"title": _cv_name(ent), "messages": out, "more": got >= limit}


def cv_list(chat_id, limit=40, before=0, after=0):
    if not tl_ready():
        raise RuntimeError("Log in with Telegram first (Settings -> Log in with Telegram). Reading a chat uses your own account.")
    return tl_run(_cv_list(chat_id, limit, before, after), 60)


def _cv_pick_thumb(m):
    obj = m.photo or m.document
    sizes = getattr(obj, "sizes", None) or getattr(obj, "thumbs", None) or []
    cand = [(max(getattr(s, "w", 0), getattr(s, "h", 0)), s) for s in sizes if getattr(s, "w", 0)]
    if not cand:
        return -1
    cand.sort(key=lambda x: x[0])
    for side, s in cand:
        if side >= 320:
            return s
    return cand[-1][1]


def _cv_prune():
    if time.time() - _cv_pruned[0] < 600 or not CHATVIEW.is_dir():
        return
    _cv_pruned[0] = time.time()
    for p in CHATVIEW.iterdir():
        try:
            if time.time() - p.stat().st_mtime > CV_TTL:
                p.unlink()
        except OSError:
            pass


async def _cv_media(chat_id, mid, thumb):
    c = await _client()
    ent = await _entity(c, chat_id)
    m = await c.get_messages(ent, ids=mid)
    if not m or not (m.photo or m.document):
        raise RuntimeError("This message has no media.")
    CHATVIEW.mkdir(parents=True, exist_ok=True)
    try:
        (CHATVIEW / ".nomedia").write_bytes(b"")
    except OSError:
        pass
    _cv_prune()
    key = hashlib.sha1(f"{getattr(ent, 'id', chat_id)}:{mid}".encode()).hexdigest()[:16]
    if thumb:
        dest = CHATVIEW / f"{key}_t.jpg"
        if not dest.exists():
            r = await c.download_media(m, file=str(dest), thumb=_cv_pick_thumb(m))
            if not r:
                raise RuntimeError("No preview available.")
        return Path(dest), "image/jpeg"
    if _cv_kind(m) != "photo":
        raise RuntimeError("Only photos can be opened here.")
    if int(getattr(m.file, "size", 0) or 0) > CV_FULL_MAX:
        raise RuntimeError("This photo is too large to open here.")
    have = list(CHATVIEW.glob(f"{key}_f.*"))
    if have:
        p = have[0]
    else:
        r = await c.download_media(m, file=str(CHATVIEW / f"{key}_f"))
        if not r:
            raise RuntimeError("Could not load the photo.")
        p = Path(r)
    return p, mimetypes.guess_type(p.name)[0] or "image/jpeg"


def cv_media(chat_id, mid, thumb):
    if not tl_ready():
        raise RuntimeError("Log in with Telegram first.")
    with CV_SEM:
        return tl_run(_cv_media(chat_id, mid, thumb), 120)


