# ── telegram account (Telethon) ──────────────────────────────────────────
@bp_tg.get("/api/chat/locate")
def chat_locate():
    """Long-press 'Locate' in the chat viewer: which library file belongs to this Telegram message?
    The message can be the file itself, our thumb.jpg message (id in thumb_message_id) or the thumb's 'VT <file message id>' caption."""
    a = request.args
    try:
        mid = int(a.get("id") or 0)
    except ValueError:
        return _err("Bad request.")
    vt = re.search(r"VT\s*(\d+)", a.get("text") or "")
    order = [mid] + ([int(vt.group(1))] if vt else [])
    norm = lambda x: re.sub(r"^-?100", "", str(x or "").strip()).lstrip("-")
    want = norm(a.get("chat_id"))
    with db() as c:
        rows = c.execute("SELECT id, chat_id, message_id, thumb_message_id FROM files WHERE trashed_at IS NULL AND "
                         "(message_id IN (?,?) OR thumb_message_id IN (?,?))", (order[0], order[-1], order[0], order[-1])).fetchall()
    rows = [r for r in rows if not r["chat_id"] or not want or norm(r["chat_id"]) == want]
    for key, val in [("message_id", v) for v in order] + [("thumb_message_id", mid)]:
        for r in rows:
            if r[key] == val:
                return jsonify(ok=True, file_id=r["id"])
    return _err("This message is not in your Timeline.", 404)


