@bp_tg.post("/api/tg/login")
def tg_login():
    if not TL_HAVE:
        return _err("Telethon is not installed. Run: pip install telethon - then restart run.py")
    d = request.get_json(force=True, silent=True) or {}
    api_id, api_hash = str(d.get("api_id", "")).strip(), str(d.get("api_hash", "")).strip()
    phone = re.sub(r"[\s-]", "", str(d.get("phone", "")))
    if not api_id.isdigit() or len(api_hash) < 20 or not re.fullmatch(r"\+\d{7,15}", phone):
        return _err("Enter the numeric API ID, the API hash and your phone with country code (+91...).")
    cfg_update({"api_id": api_id, "api_hash": api_hash, "phone": phone})
    try:
        r = tl_send_code(phone)
        if r == "already":
            return jsonify(ok=True, already=True, message="Already logged in.")
        return jsonify(ok=True, message="Login code sent to your Telegram app (or SMS).")
    except Exception as e:
        return _err(e)


@bp_tg.post("/api/tg/verify")
def tg_verify():
    d = request.get_json(force=True, silent=True) or {}
    phone = cfg_get("phone")
    code = re.sub(r"\D", "", str(d.get("code", "")))
    try:
        r = tl_sign_in(phone, code, str(d.get("password", "")) or None)
        if r == "password":
            return jsonify(ok=True, needs_password=True, message="2-step verification is on: enter your password.")
        p = tl_profile()
        cfg_update({"profile": p, "phone": p["phone"] or phone})
        msg = "Logged in."
        try:
            got = adopt_code_from_pin()
            if got:
                msg = f"Logged in. Vault code {got} taken from the pinned message."
            code_pin_kick()
        except Exception:
            pass
        return jsonify(ok=True, profile=p, message=msg, config=cfg_load())
    except Exception as e:
        return _err(e)


