# LAN PORTS + GUEST RULES + SHARE LINKS + VIDEO RANGE CAP + CODE CHUNKS
# ============================================================================
# * The owner uses the normal port (127.0.0.1). "Create LAN" opens ANOTHER port on 0.0.0.0 that shows the same
#   website to people on the same Wi-Fi. Everything a person on such a port may do is decided here (default = deny).
# * A share link opens its own random port that serves exactly ONE file (view only) until it expires.
import hmac
import html as _html
import random
from flask import current_app, g
from werkzeug.serving import make_server
from werkzeug.utils import send_file as wz_send_file
from werkzeug.wrappers import Request as WzRequest

LAN_MAX = 10
LAN_PERMS = ("view", "download", "upload", "theme", "clear_cache", "share")
LANS = {}                      # id -> {id, port, password, perms, srv (None = stopped), sessions, fails, created}
SHARES = {}                    # port -> {port, token, fid, exp, srv, created}
SHARE_MAX = 60
_lan_lock = threading.RLock()
MAIN_PORT = [8080]
LAN_STATE_FILE = CONFIG_DIR / "lan_state.json"      # OLD single file (only read once to move its content into the folders below)
LAN_DIR = CONFIG_DIR / "lan"                         # storage/config/lan/
SHARE_DIR = LAN_DIR / "share"                        #   share/<token>.json  = ONE file per share link
GUEST_DIR = LAN_DIR / "guest"                        #   guest/<id>.json     = ONE file per guest LAN
                                                     # delete a link in the app = its file is cut (deleted) from here at once


class _WaitressSrv:
    """LAN / share ports on waitress (keep-alive + fixed thread pool, like the main port). werkzeug's server closes the connection after EVERY
    request, so each thumbnail, script and click needed a new connection - that was the LAN lag. Same methods as werkzeug's server object."""
    def __init__(self, host, port, app):
        from waitress import create_server
        self._s = create_server(app, host=host, port=port, threads=32, channel_timeout=120, connection_limit=300, ident="vault",
                                send_bytes=262144, max_request_body_size=int(os.environ.get("VAULT_MAX_UPLOAD_MB", "2048")) * 1024 * 1024)
        self.server_port = getattr(self._s, "effective_port", None) or port

    def serve_forever(self):
        self._s.run()

    def shutdown(self):
        self._s.close()

    def server_close(self):
        pass


def _make_srv(host, port, app):
    """waitress when it is installed (smooth), otherwise werkzeug (works, but slower)."""
    if os.environ.get("VAULT_WAITRESS", "1") != "0":
        try:
            import waitress  # noqa: F401
            return _WaitressSrv(host, port, app)
        except OSError:
            raise                                   # port taken: the callers try another one
        except Exception:
            pass                                    # waitress missing / odd version -> werkzeug below
    return make_server(host, port, app, threaded=True)


def _lan_write_json(path, obj):
    tmp = path.with_suffix(".tmp")
    sec_write(tmp, json.dumps(obj, indent=2))
    os.replace(tmp, path)


def _lan_sync_dir(folder, items):
    """items = {file stem: dict}. Writes one file per item and DELETES every file whose item no longer exists."""
    folder.mkdir(parents=True, exist_ok=True)
    keep = set()
    for stem, obj in items.items():
        stem = re.sub(r"[^A-Za-z0-9_-]", "_", str(stem))
        keep.add(stem + ".json")
        _lan_write_json(folder / (stem + ".json"), obj)
    for f in folder.iterdir():
        if f.suffix in (".json", ".tmp") and f.name not in keep:
            try:
                f.unlink()
            except OSError:
                pass


def _lan_stem(x):
    return re.sub(r"[^A-Za-z0-9_-]", "_", str(x))


def _share_files_cut(port=None, token=None):
    """Go into storage/config/lan/share and delete EVERY file that belongs to this link (matched by its port or its token,
    read from inside the file) - it does not matter what the file is called or whether the server still remembers the link."""
    cut = []
    try:
        files = list(SHARE_DIR.glob("*.json"))
    except OSError:
        files = []
    for f in files:
        hit = False
        try:
            e = json.loads(f.read_text("utf-8"))
            hit = isinstance(e, dict) and ((token and str(e.get("token")) == str(token)) or (port and int(e.get("port") or 0) == int(port)))
        except Exception:
            hit = bool(token) and f.stem == _lan_stem(token)
        if hit:
            try:
                f.unlink()
                cut.append(f.name)
            except OSError:
                pass
    return cut


def _lan_unlink(folder, stem):
    try:
        (folder / (re.sub(r"[^A-Za-z0-9_-]", "_", str(stem)) + ".json")).unlink()
    except OSError:
        pass


def _lan_save():
    """Every guest LAN and every share link lives in its OWN file (storage/config/lan/guest and .../share)."""
    try:
        with _lan_lock:
            lans = {l["id"]: {"id": l["id"], "port": l["port"], "password": l["password"], "perms": l["perms"],
                              "running": bool(l["srv"]), "sessions": sorted(l["sessions"]), "created": l["created"]}
                    for l in LANS.values()}
            shares = {s["token"]: {"port": s["port"], "token": s["token"], "fids": s["fids"], "exp": s["exp"], "created": s["created"],
                                   "running": bool(s["srv"])} for s in SHARES.values()}
        ensure_dirs()
        _lan_sync_dir(GUEST_DIR, lans)
        _lan_sync_dir(SHARE_DIR, shares)
        with _lan_lock:
            for l in LANS.values():
                l["filed"] = True
            for sh in SHARES.values():
                sh["filed"] = True
    except Exception as e:
        print("  could not save LAN / share files:", e, flush=True)


def _lan_load_files():
    data = {"lans": [], "shares": []}
    for key, folder in (("lans", GUEST_DIR), ("shares", SHARE_DIR)):
        try:
            files = sorted(folder.glob("*.json"), key=lambda f: f.stat().st_mtime)
        except OSError:
            files = []
        for f in files:
            try:
                e = json.loads(sec_read(f))
                if isinstance(e, dict):
                    data[key].append(e)
            except Exception:
                continue
    if not data["lans"] and not data["shares"] and LAN_STATE_FILE.exists():      # one-time move from the old single file
        try:
            old = json.loads(LAN_STATE_FILE.read_text("utf-8"))
            if isinstance(old, dict):
                data["lans"], data["shares"] = list(old.get("lans") or []), list(old.get("shares") or [])
            LAN_STATE_FILE.rename(LAN_STATE_FILE.with_suffix(".old"))
        except Exception:
            pass
    return data


def _lan_restore(app_obj):
    """At start-up: reopen every LAN that was running (same port), keep stopped ones stopped,
    reopen share links that have no time limit or have not expired yet."""
    data = _lan_load_files()
    with _lan_lock:
        for e in data.get("lans") or []:
            try:
                if len(LANS) >= LAN_MAX:
                    break
                l = {"id": str(e["id"]), "port": int(e.get("port") or 0), "password": str(e.get("password") or ""),
                     "perms": {k: bool((e.get("perms") or {}).get(k, True)) for k in LAN_PERMS},
                     "srv": None, "sessions": set(e.get("sessions") or []), "fails": {}, "created": e.get("created") or now()}
                if e.get("running"):                          # it was ON before the restart -> ON again (stopped ones stay stopped)
                    srv, port = _lan_open(app_obj, l["port"])
                    if srv:
                        l["srv"], l["port"] = srv, port
                LANS[l["id"]] = l
            except Exception:
                continue
        for e in data.get("shares") or []:
            try:
                exp = e.get("exp")
                if exp and time.time() > exp:                 # time limit is over -> gone
                    continue
                if len(SHARES) >= SHARE_MAX:
                    break
                token = str(e["token"])
                if not e.get("running", True):                 # it was stopped before the restart -> stays stopped (Start link brings it back)
                    sp = int(e.get("port") or 0)
                    if sp and sp not in SHARES:
                        SHARES[sp] = {"port": sp, "token": token, "fids": [int(x) for x in e.get("fids") or []], "srv": None,
                                      "created": e.get("created") or now(), "exp": exp or None}
                    continue
                w = _ShareWsgi(token)
                gov = _Governed(w)
                srv = None
                for want in (int(e.get("port") or 0), 0):
                    try:
                        srv = _make_srv("0.0.0.0", want, gov)
                        break
                    except OSError:
                        srv = None
                if srv is None:
                    continue
                port = srv.server_port
                w.port = port
                SHARES[port] = {"port": port, "token": token, "fids": [int(x) for x in e.get("fids") or []], "srv": srv,
                                "created": e.get("created") or now(), "exp": exp or None}
                threading.Thread(target=srv.serve_forever, daemon=True, name=f"share-{port}").start()
            except Exception:
                continue
    _lan_save()


def _lan_by_port(port):
    """The RUNNING LAN that listens on this port (stopped ones have srv = None)."""
    for l in LANS.values():
        if l["srv"] and l["port"] == port:
            return l
    return None


def _lan_port_taken(port):
    return port == MAIN_PORT[0] or port in SHARES or _lan_by_port(port) is not None


def _lan_open(app_obj, want=0):
    """Open a LAN server. Tries the wanted port first (when restarting), otherwise the OS gives a free RANDOM port."""
    w = None
    for p in ([want] if want else []) + [0]:
        try:
            w = _LanWsgi(app_obj, p)
            srv = _make_srv("0.0.0.0", p, _Governed(w))
        except OSError:
            continue
        w.port = srv.server_port
        threading.Thread(target=srv.serve_forever, daemon=True, name=f"lan-{w.port}").start()
        return srv, w.port
    return None, 0

