STICKY_IP_FILE = CONFIG_DIR / "sticky_ip.txt"
_IP_RE = re.compile(r"\d{1,3}(\.\d{1,3}){3}")


def _sticky_ip():
    """The first IP ever shown. It is remembered on disk and never changes by itself,
    so the address stays the same after switching Wi-Fi / mobile data / restarting.
    To reset it, delete config/sticky_ip.txt."""
    try:
        v = sec_read(STICKY_IP_FILE).strip()
        if _IP_RE.fullmatch(v):
            return v
    except Exception:
        pass
    return ""


def _remember_ip(ip):
    try:
        if ip and not _sticky_ip():
            CONFIG_DIR.mkdir(parents=True, exist_ok=True)
            sec_write(STICKY_IP_FILE, ip)
    except Exception:
        pass


def ftp_ips():
    """FTP only. Keeps the first-seen IP in front while it still exists on this device
    (stable order when Wi-Fi + hotspot are both on). If the device has no network IP right now
    (Wi-Fi off / mobile data only) we return nothing, so the caller falls back to localhost,
    which always works on the same phone."""
    cur = lan_ips()
    if not cur:
        return []
    st = _sticky_ip()
    if not st:
        _remember_ip(cur[0])
        st = cur[0]
    if st in cur:
        return [st] + [i for i in cur if i != st]
    return cur


def _iface_ips():
    """Ask the kernel for each interface's IPv4 directly (ioctl SIOCGIFADDR). Termux on newer Android often blocks
    `ip addr`, `ifconfig` and /proc/net/fib_trie, and a hotspot with a random subnet is not found by probing - this finds it."""
    out = []
    try:
        import fcntl, struct
    except ImportError:
        return out
    names = []
    try:
        names += [n for _, n in socket.if_nameindex()]
    except Exception:
        pass
    try:
        names += os.listdir("/sys/class/net")
    except Exception:
        pass
    names += ["wlan0", "wlan1", "wlan2", "ap0", "ap1", "swlan0", "swlan1", "softap0", "rndis0", "usb0", "ncm0", "eth0", "eth1", "p2p0", "br0"]
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        for n in dict.fromkeys(names):
            if n == "lo" or n.startswith(("rmnet", "ccmni", "dummy", "v4-", "tun", "tap", "ppp", "ifb", "sit")):
                continue                                   # mobile data / VPN / tunnels are no use for a local network
            try:
                raw = fcntl.ioctl(s.fileno(), 0x8915, struct.pack("256s", n.encode()[:15]))
                out.append(socket.inet_ntoa(raw[20:24]))
            except Exception:
                continue
    finally:
        s.close()
    return out


def lan_ips():
    """Every private IPv4 this device has (Wi-Fi, own hotspot, router, ...) - best first.
    A hotspot interface is often NOT the default route, so we look at all interfaces, not only one."""
    found = []

    def add(ip):
        if ip and re.fullmatch(r"\d{1,3}(\.\d{1,3}){3}", ip) and not ip.startswith(("127.", "0.", "169.254.", "255.")) and ip not in found:
            found.append(ip)

    for target in ("10.255.255.255", "192.168.1.1", "192.168.43.1", "172.20.10.1", "8.8.8.8"):
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        try:
            s.connect((target, 1))
            add(s.getsockname()[0])
        except Exception:
            pass
        finally:
            s.close()
    try:
        for ip in _iface_ips():
            add(ip)
    except Exception:
        pass
    try:
        for ip in socket.gethostbyname_ex(socket.gethostname())[2]:
            add(ip)
    except Exception:
        pass
    try:
        txt = Path("/proc/net/fib_trie").read_text()
        for ip in re.findall(r"\|--\s+(\d+\.\d+\.\d+\.\d+)\s*\n\s*/32 host LOCAL", txt):
            add(ip)
    except Exception:
        pass
    for cmd in (["ip", "-4", "-o", "addr", "show"], ["ifconfig"]):
        try:
            out = subprocess.run(cmd, capture_output=True, text=True, timeout=2).stdout
            for ip in re.findall(r"inet (?:addr:)?(\d+\.\d+\.\d+\.\d+)", out):
                add(ip)
        except Exception:
            pass

    def rank(ip):
        o = [int(x) for x in ip.split(".")]
        if o[0] == 192 and o[1] == 168:
            return 0
        if o[0] == 172 and 16 <= o[1] <= 31:
            return 1
        if o[0] == 10:
            return 2
        if o[0] == 100 and 64 <= o[1] <= 127:
            return 4
        return 3
    found = [ip for ip in found if all(0 <= int(x) <= 255 for x in ip.split("."))]
    return sorted(found, key=rank)


def ftp_ip():
    ips = ftp_ips()
    return ips[0] if ips else ""


def lan_ip():
    """Best single IP of this device on the Wi-Fi / hotspot / LAN."""
    ips = lan_ips()
    return ips[0] if ips else ""


