_G_OPEN_GET = re.compile(r"^/(static/.+|brand/[^/]+|favicon\.ico|apple-touch-icon\.png|manifest\.webmanifest|sw\.js|offline|api/config|api/live|api/guest/me|api/theme/bg/[^/]+)?$")
_G_VIEW_GET = re.compile(r"^/((thumb|preview|media)/\d+|api/(code|vcap|hdp)/\d+)$")


def _guest_allowed(path, method, perms, args):
    if method == "GET":
        if _G_OPEN_GET.match(path):
            return True
        if path == "/api/files":
            return bool(perms.get("view")) and args.get("trash") != "1"
        if path == "/api/files/stamp" or path == "/api/disk" or _G_VIEW_GET.match(path):
            return bool(perms.get("view"))
        if path in ("/api/transfers", "/api/transfers/history"):
            return bool(perms.get("download")) and bool(perms.get("view"))
        if re.match(r"^/download/(\d+|zip)$", path):
            return bool(perms.get("download")) and bool(perms.get("view"))
        return False
    if method == "POST":
        if path == "/lan/auth" or path == "/api/files/delete":
            return True
        if path in ("/api/upload", "/api/backup"):       # a guest who may upload may also press "Back up now" for what they added
            return bool(perms.get("upload"))
        if path == "/api/share":
            return bool(perms.get("share")) and bool(perms.get("view"))
        if path == "/api/guest/clear-cache":
            return bool(perms.get("clear_cache"))
    return False


