def _lan_gate():
    """before_request: decides what somebody on a LAN port may touch. The owner's port (no 'vault.lan') is never limited."""
    port = request.environ.get("vault.lan")
    g.guest = None
    if port is None:
        return None
    lan = _lan_by_port(port)
    if not lan:
        return Response("This LAN was stopped.", status=503, mimetype="text/plain")
    uid = request.cookies.get(f"vlg_{port}", "")
    if not re.fullmatch(r"[0-9a-f]{16}", uid):
        uid = secrets.token_hex(8)
        g.set_uid = uid
    g.guest = {"port": port, "perms": lan["perms"], "uid": f"{port}:{uid}", "lan": lan}
    path, method = request.path, request.method
    if lan["password"] and request.cookies.get(f"vla_{port}", "") not in lan["sessions"]:
        if path == "/lan/auth" and method == "POST":
            return None
        if path == "/" and method == "GET":
            return Response(_GATE_HTML, mimetype="text/html")
        return jsonify(ok=False, error="Password needed."), 401
    if not _guest_allowed(path, method, lan["perms"], request.args):
        return jsonify(ok=False, error="Not allowed on this LAN."), 403
    return None


def range_response(p, mime, range_header, cap):
    """Answer a Range request with at most `cap` bytes (about 10 s of video). The player asks for the next piece when it needs it,
    and when the video is closed the browser drops the connection, so nothing more is sent."""
    size = p.stat().st_size
    m = re.match(r"^bytes=(\d*)-(\d*)$", (range_header or "").strip())
    if not m or not (m.group(1) or m.group(2)) or size <= 0:
        return None
    if m.group(1):
        start = int(m.group(1))
        end = min(int(m.group(2)), size - 1) if m.group(2) else size - 1
    else:                                                  # "last N bytes" (some players read the index at the end)
        start, end = max(0, size - int(m.group(2))), size - 1
    if start >= size or start > end:
        return Response(status=416, headers={"Content-Range": f"bytes */{size}"})
    if m.group(1) and end - start + 1 > cap:
        end = start + cap - 1
    length = end - start + 1

    def gen():
        with open(p, "rb") as f:
            f.seek(start)
            left = length
            while left > 0:
                b = f.read(min(1024 * 1024, left))
                if not b:
                    break
                left -= len(b)
                yield b

    resp = Response(gen(), status=206, mimetype=mime, direct_passthrough=True)
    resp.headers.update({"Content-Range": f"bytes {start}-{end}/{size}", "Content-Length": str(length), "Accept-Ranges": "bytes",
                         "X-Content-Type-Options": "nosniff", "Content-Security-Policy": "sandbox", "Cache-Control": "private, max-age=60"})
    return resp


def _utf8_trim(b):
    for k in range(4):
        try:
            b[:len(b) - k].decode("utf-8")
            return b[:len(b) - k]
        except UnicodeDecodeError:
            pass
    return b


# ── video streaming from Telegram (own account): only the blocks being watched are fetched, nothing is downloaded up front ──
STREAM_DIR = TMP / "stream"
STREAM_NAMES = {}                               # file id -> clean name used in its cache folder


def _sdir(fid, row=None):
    """Cache folder of one song / video: "<id> <name>" (for example "318 Bulleya - Papon"), so it is easy to see which file it is."""
    fid = int(fid)
    nm = STREAM_NAMES.get(fid)
    if nm is None:
        try:
            r = row if row is not None else _row(fid)
            raw = Path(str(r["name"] or "")).stem if r else ""
        except Exception:
            raw = ""
        raw = re.sub(r'[\\/:*?"<>|\x00-\x1f]', " ", raw)
        raw = re.sub(r"\s+", " ", raw).strip(" .")[:60].strip(" .")
        nm = STREAM_NAMES[fid] = raw
    return STREAM_DIR / (f"{fid} {nm}" if nm else str(fid))


def _sid(d):
    """File id of a cache folder ("318 Bulleya" or an old plain "318"), or None."""
    h = (d.name if hasattr(d, "name") else str(d)).split(" ", 1)[0]
    return int(h) if h.isdigit() else None
STREAM_B = 1024 * 1024                          # one cached block = 1 MB
STREAM_AHEAD_S = 15.0                           # never more than ~15 s are loaded ahead of the playhead
STREAM_REFILL_S = 10.0                          # a new piece is only sent when less than ~10 s are still buffered (so ~5 s after the last piece)
NETLV = ["ok"]                                  # network level reported by the player: turbo / fast / ok / slow
_AHEAD_BY_NET = {"turbo": 40.0, "fast": 24.0, "ok": 15.0, "slow": 12.0, "offline": 12.0}      # seconds loaded ahead of the playhead


def _ahead_s():
    return _AHEAD_BY_NET.get(NETLV[0], STREAM_AHEAD_S)
STREAM_GEN, FGEN = [0], {}                      # bumped when playback is stopped: blocks still on their way are then NOT written to the disk
VBPS, VPOS = {}, {}                             # file id -> bytes per second ; file id -> (playhead byte, time reported, paused)


def _playpos(fid):
    v = VPOS.get(fid)
    if v and time.time() - v[1] < (600 if v[2] else 8):
        return v[0]
    return None


def _livepos(fid):
    """Playhead byte of a song that is playing RIGHT NOW (reported within the last 8 s, not paused). A paused / old position must
    never hold a request back: it made songs with a big embedded cover (the player has to read past 0.5 MB before it knows the
    length) wait 12 s per request and stay at 0:00."""
    v = VPOS.get(fid)
    if v and not v[2] and time.time() - v[1] < 8:
        return v[0]
    return None


def _ahead_block(row, i, tok=None):
    """Prefetch job: skipped when the song was changed meanwhile (so an old song never refills its folder with far-away blocks)."""
    if tok is not None and tok != (STREAM_GEN[0], FGEN.get(row["id"], 0)):
        return                                           # queued before playback was stopped
    cur = CUR[0]
    if cur and row["id"] != cur and not (row["id"] in NEIGH and i < 2):
        return
    stream_block(row, i)


def _stale(fid, start, size=0):
    """A request of a song that is no longer the playing one, asking for something far from its start.
    Never "stale": the playing song, the previous / next song, and the last 3 MB of a file (the browser reads the tag / index
    at the end first - answering 410 there made the song stay at 0:00)."""
    if not CUR[0] or fid == CUR[0] or fid in NEIGH or start < 2 * STREAM_B:
        return False
    if size and size - start <= 3 * 1024 * 1024:
        return False
    return True


TAILB = {}         # file id -> index of its LAST 1 MB block: the browser reads the end of a song first (tags / length), so it is kept ready too


def _nkeep(fid, stem):
    """Blocks of the previous / next song that always stay: first two and the last one."""
    return fid in NEIGH and (stem in ("0", "1") or stem == str(TAILB.get(fid, -1)))


def stream_trim(fid, keep_lo, keep_hi):
    """Delete the 1 MB block files of this video / song that are behind the playhead or too far ahead."""
    d = _sdir(fid)
    try:
        for p in d.glob("*.bin"):
            try:
                i = int(p.stem)
            except ValueError:
                continue
            if (i < keep_lo or i > keep_hi) and i != TAILB.get(fid, -1):
                p.unlink(missing_ok=True)
    except OSError:
        pass
STREAM_NOW = concurrent.futures.ThreadPoolExecutor(8, thread_name_prefix="vstream")      # blocks the player is waiting for
STREAM_AHEAD = concurrent.futures.ThreadPoolExecutor(3, thread_name_prefix="vahead")     # blocks 10 s before / after the playhead
_stream_doc, _stream_locks, _stream_lk = {}, {}, threading.Lock()


async def _stream_fetch(chat_id, mid, off, size):
    c = await _client()
    key = (str(chat_id), int(mid))
    hit = _stream_doc.get(key)
    if not hit or time.time() - hit[0] > 1500:
        ent = await _entity(c, chat_id)
        m = await c.get_messages(ent, ids=int(mid))
        if not m or not getattr(m, "document", None):
            raise RuntimeError("That Telegram message no longer exists in the channel.")
        hit = _stream_doc[key] = (time.time(), m.document)
    buf = bytearray()
    async for chunk in c.iter_download(hit[1], offset=off, limit=1, request_size=STREAM_B, file_size=size):
        buf += chunk
    return bytes(buf)


def stream_block(row, i):
    """One 1 MB block of a cloud video: from the small disk cache, or fetched from Telegram once."""
    size = int(row["size"])
    want = min(STREAM_B, size - i * STREAM_B)
    d = _sdir(row["id"], row)
    path = d / f"{i}.bin"
    try:
        if path.stat().st_size == want:
            return path
    except OSError:
        pass
    with _stream_lk:
        lock = _stream_locks.setdefault((row["id"], i), threading.Lock())
    with lock:
        try:
            if path.stat().st_size == want:
                return path
        except OSError:
            pass
        tok = (STREAM_GEN[0], FGEN.get(row["id"], 0))
        data = None
        for attempt in range(3):
            try:
                data = tl_run(_stream_fetch(row["chat_id"], row["message_id"], i * STREAM_B, size), 90)
                if len(data) >= want:
                    break
                raise RuntimeError("short block")
            except Exception:
                _stream_doc.pop((str(row["chat_id"]), int(row["message_id"])), None)
                if attempt == 2:
                    raise
                time.sleep(1 + attempt)
        if tok != (STREAM_GEN[0], FGEN.get(row["id"], 0)):      # playback was stopped while this block was coming: nothing is saved
            with _stream_lk:
                _stream_locks.pop((row["id"], i), None)
            return path
        d.mkdir(parents=True, exist_ok=True)
        tmp = path.with_name(path.name + f".{time.time_ns()}.tmp")
        tmp.write_bytes(data[:want])
        os.replace(tmp, path)
    with _stream_lk:
        _stream_locks.pop((row["id"], i), None)
    return path


def stream_prune(max_bytes=192 * 1024 * 1024, max_age=120):
    if not STREAM_DIR.is_dir():
        return
    files = []
    for p in STREAM_DIR.rglob("*.bin"):
        try:
            if _nkeep(_sid(p.parent), p.stem):
                continue
            if GRACE.get(_sid(p.parent), 0) > time.time() or _sid(p.parent) == CUR[0]:
                continue                                 # a song in its 15 s, or the one playing now, keeps all its blocks
            st = p.stat()
            files.append((st.st_mtime, st.st_size, p))
        except OSError:
            pass
    files.sort()
    total = sum(f[1] for f in files)
    for mt, sz, p in files:
        if total > max_bytes or time.time() - mt > max_age:
            try:
                p.unlink()
                total -= sz
            except OSError:
                pass
    for d in STREAM_DIR.iterdir():                       # empty folders of finished songs / videos
        try:
            d.rmdir()
        except OSError:
            pass


def stream_response(row, mime, range_header, cap):
    """206 answer for a cloud video. The answer is about 10 s long (cap); blocks around it are prefetched, so playing and
    seeking stay smooth and a played part is not fetched twice."""
    size = int(row["size"])
    m = re.match(r"^bytes=(\d*)-(\d*)$", (range_header or "bytes=0-").strip())
    if not m or not (m.group(1) or m.group(2)):
        m = re.match(r"^bytes=(\d*)-(\d*)$", "bytes=0-")
    if m.group(1):
        start = int(m.group(1))
        end = min(int(m.group(2)), size - 1) if m.group(2) else size - 1
    else:
        start, end = max(0, size - int(m.group(2))), size - 1
    if start >= size or start > end:
        return Response(status=416, headers={"Content-Range": f"bytes */{size}"})
    cap = max(STREAM_B, int(cap))
    if end - start + 1 > cap and m.group(1):
        end = start + cap - 1
    length = end - start + 1
    first, last = start // STREAM_B, end // STREAM_B
    nblocks = -(-size // STREAM_B)
    fid = row["id"]
    if _stale(fid, start, size):
        return Response("Song was changed", status=410, mimetype="text/plain")
    bps = VBPS.get(fid)
    # hold the request while more than ~10 s are already buffered: the player only gets the next piece when ~5 s are left
    if bps and start > 512 * 1024 and size - start > 3 * 1024 * 1024:         # (file start and the end of an mp4 are always served at once)
        pp = _livepos(fid)
        t_end = time.time() + 12
        while pp is not None and start > pp + STREAM_REFILL_S * (_ahead_s() / STREAM_AHEAD_S) * bps and time.time() < t_end:
            time.sleep(0.25)
            pp = _livepos(fid)
            if _stale(fid, start, size):
                return Response("Song was changed", status=410, mimetype="text/plain")
    pp = _playpos(fid)
    base = start if pp is None else max(0, min(int(pp), start))
    ahead_last = min(nblocks - 1, int((base + (_ahead_s() * bps if bps else 2 * STREAM_B)) // STREAM_B))
    ahead_last = max(ahead_last, last)
    keep_lo = min(first, base // STREAM_B)
    stream_trim(fid, keep_lo, ahead_last)                    # everything behind the playhead / beyond 15 s ahead is deleted
    futs = [STREAM_NOW.submit(stream_block, row, i) for i in range(first, last + 1)]
    for i in range(last + 1, ahead_last + 1):
        STREAM_AHEAD.submit(_ahead_block, row, i, (STREAM_GEN[0], FGEN.get(fid, 0)))            # only up to 15 s ahead of the playhead, never the whole file
    try:
        futs[0].result()                                    # the first block decides: Telegram error -> clean 503, no broken player
    except Exception as e:
        print(f"[stream] block {first} of file {fid} failed: {e}", flush=True)
        return Response(f"Could not stream this video: {e}", status=503, mimetype="text/plain")

    def gen():
        left = length
        for k, f in enumerate(futs):
            pth = Path(f.result())
            try:
                data = pth.read_bytes()
            except OSError:                                  # trimmed by a newer request meanwhile: fetch it again
                data = Path(stream_block(row, first + k)).read_bytes()
            lo = start - (first + k) * STREAM_B if k == 0 else 0
            piece = data[lo:lo + left]
            left -= len(piece)
            yield piece
            if left <= 0:
                break

    resp = Response(gen(), status=206, mimetype=mime, direct_passthrough=True)
    resp.headers.update({"Content-Range": f"bytes {start}-{end}/{size}", "Content-Length": str(length), "Accept-Ranges": "bytes",
                         "X-Content-Type-Options": "nosniff", "Content-Security-Policy": "sandbox", "Cache-Control": "private, max-age=60"})
    return resp


@bp_library.get("/api/code/<int:fid>")
def code_chunk(fid):
    """Read-only text for the code viewer, one piece (~48 KB, cut at a line end) per call: ?off=<byte offset>."""
    r = _row(fid)
    if not r or r["trashed_at"]:
        return jsonify(ok=False, error="File not found"), 404
    ext = Path(r["name"]).suffix.lower()
    if ext not in CODE_EXT and not (r["mime"] or "").startswith("text/"):
        return jsonify(ok=False, error="This is not a text / code file."), 415
    try:
        p = restore_local(r)
    except Exception as e:
        return jsonify(ok=False, error=str(e)), 503
    try:
        off = max(0, int(request.args.get("off", 0)))
    except ValueError:
        off = 0
    size = p.stat().st_size
    with open(p, "rb") as f:
        f.seek(off)
        data = f.read(CODE_CHUNK)
    if off == 0 and b"\x00" in data[:4096]:
        return jsonify(ok=True, binary=True, text="", off=0, next=size, size=size, eof=True)
    eof = off + len(data) >= size
    if not eof:
        cut = data.rfind(b"\n")
        data = data[:cut + 1] if cut > 0 else _utf8_trim(data)
    text = data.decode("utf-8", errors="replace")
    nxt = off + len(data)
    return jsonify(ok=True, text=text, off=off, next=nxt, size=size, eof=nxt >= size, binary=False)


@bp_library.get("/api/tags/<int:fid>")
def song_tags(fid):
    r = _row(fid)
    if not r:
        return jsonify(ok=False), 404
    try:
        t = audio_tags(r)
    except Exception:
        t = {}
    return jsonify(ok=True, **t)


def _lrclib(path, params, timeout=7):
    import urllib.request, urllib.parse, urllib.error, ssl
    url = "https://lrclib.net/api/" + path + "?" + urllib.parse.urlencode(params)
    req = urllib.request.Request(url, headers={"User-Agent": "CloudVault v1 (song lyrics)", "Accept": "application/json"})
    ctx, last = None, None
    for n in range(3):                       # lrclib.net is sometimes busy (HTTP 503 / 502 / 429): wait a moment and ask again
        try:
            with urllib.request.urlopen(req, timeout=timeout, context=ctx) as r:
                return json.loads(r.read().decode("utf-8", "replace"))
        except urllib.error.HTTPError as e:
            if e.code not in (429, 500, 502, 503, 504) or n == 2:
                raise
            last = e
        except Exception as e:
            if ctx is None and ("CERTIFICATE" in str(e).upper() or isinstance(e, ssl.SSLError)):
                ctx = ssl._create_unverified_context()          # phones without a proper certificate store (only public lyrics text is read)
                continue
            if n == 2:
                raise
            last = e
        time.sleep(0.4 * (n + 1))
    raise last


def _lyr_clean(t):
    t = re.sub(r"\s*[\(\[][^\)\]]*[\)\]]", "", t or "")      # "(From Mickey Virus)", "[Official]" ...
    t = re.split(r"\s+-\s+", t)[0]
    return re.sub(r"\s+", " ", t).strip()


def song_lyrics(row, dur=0):
    """Time-synced lyrics (LRC text) of a song from the public LRCLIB database (only the song name / artist is sent).
    Cached next to the cover tags; a song with no lyrics is looked up again after one day. Switch off with VAULT_NO_LYRICS=1.
    Returns {"err": reason} when the network failed (nothing is remembered, tried again next time)."""
    jp = PREVIEWS / f"{row['id']}.lyrics.json"
    try:
        c = json.loads(jp.read_text("utf-8"))
        if c.get("v") == 2 and (c.get("synced") or time.time() - c.get("at", 0) < 86400):      # v2: plain-only lyrics are looked up again after a day (a timed version may exist by then)
            return c
    except Exception:
        pass
    if os.environ.get("VAULT_NO_LYRICS") == "1":
        return {"v": 2, "synced": "", "plain": "", "at": time.time()}
    import urllib.error
    try:
        t = audio_tags(row) or {}
    except Exception:
        t = {}
    title = (t.get("title") or "").strip()
    artist = re.split(r"\s*[;/,&]\s*", (t.get("artist") or "").strip())[0] if t.get("artist") else ""
    fname = _lyr_clean(_clean_title(row["name"]))
    ctitle = _lyr_clean(title) or fname
    st = {"fail": False, "err": ""}

    def call(path, prm):
        try:
            return _lrclib(path, prm)
        except urllib.error.HTTPError as e:
            if e.code != 404:
                st["fail"] = True
                st["err"] = f"HTTP {e.code}"
            return None
        except Exception as e:
            st["fail"] = True
            st["err"] = (type(e).__name__ + ": " + str(e))[:90]
            return None

    def good(x):
        return isinstance(x, dict) and (x.get("syncedLyrics") or x.get("plainLyrics"))

    # every lookup is asked at the SAME time (before: one after the other, each could wait several seconds); the best answer wins
    jobs = []
    if artist:
        for tt in dict.fromkeys([title, ctitle]):
            if tt:
                prm = {"track_name": tt, "artist_name": artist}
                if t.get("album") and tt == title:
                    prm["album_name"] = t["album"]
                if dur > 0:
                    prm["duration"] = int(dur)
                jobs.append(("get", prm))
    words = [w for w in re.split(r"\W+", ctitle.lower()) if len(w) >= 3][:2]
    for term in dict.fromkeys([(ctitle + " " + artist).strip(), ctitle, fname]):
        if term:
            jobs.append(("search", {"q": term}))
    res = []
    if jobs:
        with concurrent.futures.ThreadPoolExecutor(max_workers=min(5, len(jobs))) as ex:
            res = list(ex.map(lambda j: call(*j), jobs))
    # collect every answer, then choose: TIMED lyrics first (a plain-only exact match no longer beats a timed search result),
    # and among the timed ones the version whose length is closest to the real song (a different cut = lines come too early / late)
    cands = []
    for (kind, _prm), r in zip(jobs, res):
        if kind == "get":
            if good(r):
                cands.append((r, True))
        else:
            for x in r if isinstance(r, list) else []:
                if isinstance(x, dict):
                    cands.append((x, False))

    def pick(field):
        best, bd = None, 1e9
        for x, exact in cands:
            if not x.get(field):
                continue
            d = x.get("duration") or 0
            gap = abs(d - dur) if (dur > 0 and d) else 4
            if dur > 0 and d and gap > 8:
                continue
            if not exact:
                blob = ((x.get("trackName") or "") + " " + (x.get("artistName") or "")).lower()
                if words and not all(w in blob for w in words):
                    continue
                gap += 0.5                    # on a tie the exact title + artist lookup wins
            if gap < bd:
                best, bd = x, gap
        return best

    hit = pick("syncedLyrics") or pick("plainLyrics")
    if not hit and st["fail"]:
        return {"err": st["err"] or "no answer from lrclib.net"}
    out = {"v": 2, "synced": (hit or {}).get("syncedLyrics") or "", "plain": (hit or {}).get("plainLyrics") or "", "at": time.time()}
    try:
        ensure_dirs()
        jp.write_text(json.dumps(out), "utf-8")
    except Exception:
        pass
    return out


@bp_library.get("/api/lyrics/<int:fid>")
def song_lyrics_route(fid):
    r = _row(fid)
    if not r:
        return jsonify(ok=False, msg="song not found"), 404
    try:
        dur = float(request.args.get("dur", 0) or 0)
    except ValueError:
        dur = 0
    try:
        c = song_lyrics(r, dur)
    except Exception as e:
        c = {"err": (type(e).__name__ + ": " + str(e))[:90]}
    if c.get("err"):
        return jsonify(ok=False, msg=c["err"])
    return jsonify(ok=True, synced=c.get("synced", ""), plain=c.get("plain", ""))


_TR_PRESETS = {
    "openai": ("https://api.openai.com/v1/chat/completions", "gpt-4o-mini"),
    "gemini": ("https://generativelanguage.googleapis.com/v1beta/openai/chat/completions", "gemini-2.0-flash"),
    "groq": ("https://api.groq.com/openai/v1/chat/completions", "llama-3.3-70b-versatile"),
    "openrouter": ("https://openrouter.ai/api/v1/chat/completions", "openai/gpt-4o-mini"),
    "deepseek": ("https://api.deepseek.com/chat/completions", "deepseek-chat"),
    "anthropic": ("https://api.anthropic.com/v1/messages", "claude-haiku-5-5"),
}


def _tr_http(url, headers, body):
    import urllib.request, urllib.error, ssl
    h = dict(headers)
    h["Content-Type"] = "application/json"
    h["User-Agent"] = "CloudVault v1"
    req = urllib.request.Request(url, data=json.dumps(body).encode("utf-8"), headers=h, method="POST")

    def go(ctx=None):
        with urllib.request.urlopen(req, timeout=75, context=ctx) as r:
            return json.loads(r.read().decode("utf-8", "replace"))
    try:
        return go()
    except urllib.error.HTTPError as e:
        try:
            msg = e.read().decode("utf-8", "replace")[:200]
        except Exception:
            msg = ""
        raise RuntimeError("API error %s %s" % (e.code, msg))
    except Exception as e:
        if "CERTIFICATE" not in str(e).upper() and not isinstance(e, ssl.SSLError):
            raise
    return go(ssl._create_unverified_context())


def _tr_batch(cfg, lines, lang):
    prov = cfg.get("lyr_prov") or "openai"
    url, model = _TR_PRESETS.get(prov, ("", ""))
    url = (cfg.get("lyr_url") or "").strip() or url
    model = (cfg.get("lyr_model") or "").strip() or model
    key = (cfg.get("lyr_key") or "").strip()
    if not key:
        raise RuntimeError("API key is not set (Settings -> Accessibility -> Lyrics translator)")
    if not url or not model:
        raise RuntimeError("API URL and model are needed for the custom provider")
    sysmsg = ("You translate song lyrics into %s. The user sends a JSON array of lines. Reply with ONLY a JSON array of strings: "
              "same length, same order, item i = translation of line i. Keep each line short and natural. "
              "If a line is already in %s, return it unchanged. No notes, no markdown." % (lang, lang))
    user = json.dumps(lines, ensure_ascii=False)
    if prov == "anthropic":
        j = _tr_http(url, {"x-api-key": key, "anthropic-version": "2023-06-01"},
                     {"model": model, "max_tokens": 4096, "system": sysmsg, "messages": [{"role": "user", "content": user}]})
        txt = "".join(b.get("text", "") for b in (j.get("content") or []) if isinstance(b, dict))
    else:
        j = _tr_http(url, {"Authorization": "Bearer " + key},
                     {"model": model, "messages": [{"role": "system", "content": sysmsg}, {"role": "user", "content": user}]})
        txt = (((j.get("choices") or [{}])[0].get("message")) or {}).get("content", "")
    txt = (txt or "").strip()
    a, b = txt.find("["), txt.rfind("]")
    if a < 0 or b < a:
        raise RuntimeError("the AI did not return a list")
    arr = json.loads(txt[a:b + 1])
    if not isinstance(arr, list):
        raise RuntimeError("bad answer from the AI")
    arr = [str(x) for x in arr]
    return (arr + [""] * len(lines))[:len(lines)]


@bp_library.post("/api/lyrics/translate")
def lyrics_translate():
    d = request.get_json(force=True, silent=True) or {}
    lines = d.get("lines")
    lang = str(d.get("lang") or "").strip()[:60]
    if not isinstance(lines, list) or not lines or not lang:
        return jsonify(ok=False, msg="nothing to translate"), 400
    lines = [str(x)[:300] for x in lines[:500]]
    cfg = cfg_load()
    if not cfg.get("lyr_tr"):
        return jsonify(ok=False, msg="Lyrics translator is switched off")
    h = hashlib.md5((cfg.get("lyr_prov", "") + "|" + lang + "\n" + "\n".join(lines)).encode("utf-8")).hexdigest()
    cp = PREVIEWS / ("tr_%s.json" % h)
    try:
        if cp.exists():
            return jsonify(ok=True, lines=json.loads(cp.read_text("utf-8")))
    except Exception:
        pass
    try:
        out = []
        for k in range(0, len(lines), 60):
            out += _tr_batch(cfg, lines[k:k + 60], lang)
    except Exception as e:
        return jsonify(ok=False, msg=(type(e).__name__ + ": " + str(e))[:200])
    try:
        cp.write_text(json.dumps(out, ensure_ascii=False), "utf-8")
    except Exception:
        pass
    return jsonify(ok=True, lines=out)


@bp_library.get("/api/vcap/<int:fid>")
def video_cap(fid):
    """The player tells us its bitrate (bytes/second) so each answer is about 10 seconds of video."""
    try:
        bps = float(request.args.get("bps", 0))
    except ValueError:
        bps = 0
    try:
        sec = max(2.0, min(20.0, float(request.args.get("sec", 10))))
    except ValueError:
        sec = 10.0
    if bps > 0:
        VCAP[fid] = int(max(128 * 1024, min(48 * 1024 * 1024, bps * sec)))
        VBPS[fid] = bps
    return jsonify(ok=True)


NEIGH = set()      # ids of the previous / next song: only their first 2 blocks (0 and 1) are kept ready
CUR = [0]          # id of the song / video that is playing right now
PRE_SEQ = [0]      # bumped on every song change: an older neighbour chain stops when it sees a newer number
STREAM_CHAIN = concurrent.futures.ThreadPoolExecutor(2, thread_name_prefix="vchain")


def _preload_chain(seq, cur, cur_futs, rows, gen):
    """Order of work after a click: 1) the clicked song's blocks 0 and 1  2) previous song block 0  3) next song block 0
    4) their block 1. Neighbours do not start before the clicked song's first 2 MB are on the disk, so they never steal the
    connection from the song the person is waiting for."""
    def live():
        return seq == PRE_SEQ[0] and CUR[0] == cur and gen == STREAM_GEN[0]
    for f in cur_futs:
        try:
            f.result(60)
        except Exception:
            pass
    for r in rows:
        TAILB[r["id"]] = -(-int(r["size"]) // STREAM_B) - 1
    for b in (0, 1, "tail"):
        for r in rows:
            if not live():
                return
            nbk = -(-int(r["size"]) // STREAM_B)
            bi = nbk - 1 if b == "tail" else b
            if bi < nbk and (b != "tail" or bi > 1):
                try:
                    stream_block(r, bi)
                except Exception:
                    pass


@bp_library.get("/api/preload")
def stream_preload():
    """?cur=<playing id>&ids=<next>,<previous>: blocks 0 and 1 (the first 2 MB) of those two are fetched; every other stream block of
    any other file is deleted. So a song change starts at once, and nothing else is left on the disk."""
    try:
        cur = int(request.args.get("cur") or 0)
    except ValueError:
        cur = 0
    ids = [int(x) for x in (request.args.get("ids") or "").split(",") if x.strip().isdigit() and int(x) != cur][:2]
    NEIGH.clear()
    NEIGH.update(ids)
    CUR[0] = cur
    lv = (request.args.get("net") or "").lower()
    if lv in _AHEAD_BY_NET:
        NETLV[0] = lv
    if cur:
        VPOS.pop(cur, None)                              # a song that (re)starts: an old playhead position must not delay its first requests
    rc = _row(cur) if cur else None
    PRE_SEQ[0] += 1                                      # a newer click cancels the older neighbour chain at once
    seq = PRE_SEQ[0]
    cur_futs = []
    if rc and _cloud_streamable(rc):
        nb_c = -(-int(rc["size"]) // STREAM_B)
        TAILB[cur] = nb_c - 1
        for b in sorted({*range(min(2, nb_c)), nb_c - 1}):                # the song that starts now: first 2 blocks + the last one, all at once, FIRST
            cur_futs.append(STREAM_NOW.submit(stream_block, rc, b))
    GRACE.pop(cur, None)                                 # the song that starts now is no longer counting down
    _grace_mark()                                        # every other song keeps its blocks for 15 s more (click it again -> it continues from the disk)
    nrows = []
    for fid in ids:                                      # order given by the player: previous song first, then the next one
        r = _row(fid)
        if r and _cloud_streamable(r):
            nrows.append(r)
    if nrows:
        STREAM_CHAIN.submit(_preload_chain, seq, cur, cur_futs, nrows, STREAM_GEN[0])
    return jsonify(ok=True)


GRACE = {}         # file id -> time after which its stream blocks may go. A stopped / changed song keeps its blocks for GRACE_S seconds,
GRACE_S = 15       # so clicking it again within 15 s continues from the disk (no new download).


def _grace_mark(only=None):
    """Every stream folder that is not the playing song starts its 15 s countdown (a folder already counting keeps its time)."""
    try:
        now = time.time()
        for d in STREAM_DIR.iterdir():
            fid = _sid(d)
            if fid is None or fid == CUR[0] or (only is not None and fid != only):
                continue
            GRACE.setdefault(fid, now + GRACE_S)
    except OSError:
        pass
    t = threading.Timer(GRACE_S + 0.7, _grace_sweep)
    t.daemon = True
    t.start()


def _grace_sweep():
    """Deletes the blocks of songs whose 15 s are over (blocks 0 and 1 of the previous / next song always stay)."""
    now = time.time()
    for fid, t in list(GRACE.items()):
        if fid == CUR[0]:
            GRACE.pop(fid, None)
            continue
        if t > now:
            continue
        GRACE.pop(fid, None)
        try:
            for d in list(STREAM_DIR.iterdir()):
                if _sid(d) != fid:
                    continue
                for p in d.glob("*.bin"):
                    if not _nkeep(fid, p.stem):
                        p.unlink(missing_ok=True)
                try:
                    d.rmdir()
                except OSError:
                    pass
        except OSError:
            pass


def _clear_stream_files(fid=None):
    try:
        if fid is not None:
            if fid != CUR[0] and fid not in NEIGH:
                for p in _sdir(fid).glob("*.bin"):
                    p.unlink(missing_ok=True)
        else:
            for p in STREAM_DIR.rglob("*.bin"):
                p.unlink(missing_ok=True)
        for d in STREAM_DIR.iterdir():
            try:
                d.rmdir()
            except OSError:
                pass
    except OSError:
        pass


@bp_library.get("/api/stream/clear")
def stream_clear():
    """Playback stopped: ?id=<file> removes that file's block files (unless it is the playing / neighbour song); no id removes ALL of them.
    Blocks still on their way are not saved any more, and a second sweep a few seconds later catches anything that slipped through."""
    fid = request.args.get("id", "")
    n = int(fid) if fid.isdigit() else None
    if n is not None:
        if n == CUR[0] or n in NEIGH:
            return jsonify(ok=True)
        FGEN[n] = FGEN.get(n, 0) + 1
        VPOS.pop(n, None)
    else:
        STREAM_GEN[0] += 1
        CUR[0] = 0
        NEIGH.clear()
        VPOS.clear()
    _grace_mark(n)                                       # blocks stay 15 s, then they are removed (a click within 15 s uses them again)
    return jsonify(ok=True)


@bp_library.get("/api/warm/<int:fid>")
def stream_warm(fid):
    """A finger touched a song / video in a grid: its first 2 blocks (0 and 1) are fetched NOW, in parallel, at top priority,
    so the real click finds them on the disk. Nothing else is touched (unused blocks are removed by the next song change / 2 min cleanup)."""
    r = _row(fid)
    if r and not r["trashed_at"] and _cloud_streamable(r) and int(r["size"] or 0) > 0:
        sx = Path(r["name"]).suffix.lower()
        if r["kind"] == "video" or sx in AUDIO_MIME or (r["mime"] or "").startswith("audio/"):
            for b in range(min(2, -(-int(r["size"]) // STREAM_B))):
                STREAM_NOW.submit(stream_block, r, b)
    return jsonify(ok=True)


@bp_library.get("/api/vpos/<int:fid>")
def video_pos(fid):
    """The player reports where it is (second t, paused or not): the server then keeps only ~15 s ahead of that point."""
    try:
        t = max(0.0, float(request.args.get("t", 0)))
        bps = float(request.args.get("bps", 0))
    except ValueError:
        return jsonify(ok=False)
    if bps > 0:
        VBPS[fid] = bps
    b = VBPS.get(fid)
    if b:
        VPOS[fid] = (t * b, time.time(), request.args.get("p") == "1")
        if len(VPOS) > 64:
            for k in sorted(VPOS, key=lambda x: VPOS[x][1])[:32]:
                VPOS.pop(k, None)
    return jsonify(ok=True)


# ── LAN ports ──────────────────────────────────────────────────────────────────────────────────────────────
bp_lan = Blueprint("lan", __name__)


class _LanWsgi:
    def __init__(self, app, port):
        self.app, self.port = app, port

    def __call__(self, environ, start_response):
        environ["vault.lan"] = self.port
        return self.app(environ, start_response)


def _stop_server(srv):
    def run():
        try:
            srv.shutdown()
            srv.server_close()
        except Exception:
            pass
    threading.Thread(target=run, daemon=True).start()


def _host_ip():
    h = request.host.rsplit(":", 1)[0].strip("[]")
    return h if h and not h.startswith("127.") and h != "localhost" else (lan_ip() or h)


def _all_ips(ip):
    """The main ip first, then every other address of this device (so the link works on any network)."""
    return [ip] + [i for i in lan_ips() if i != ip]


def _lan_json(l, ip):
    return {"id": l["id"], "port": l["port"], "running": bool(l["srv"]), "url": f"http://{ip}:{l['port']}", "urls": [f"http://{i}:{l['port']}" for i in _all_ips(ip)], "password": bool(l["password"]), "perms": l["perms"], "created": l["created"]}


def _share_json(s, ip):
    r = _row(s["fids"][0])
    nm = (r["name"] if r else "?") if len(s["fids"]) == 1 else f"{len(s['fids'])} files"
    return {"port": s["port"], "name": nm, "count": len(s["fids"]), "exp": s["exp"], "running": bool(s["srv"]), "url": f"http://{ip}:{s['port']}/{s['token']}", "urls": [f"http://{i}:{s['port']}/{s['token']}" for i in _all_ips(ip)], "created": s["created"]}


@bp_lan.get("/api/guest/me")
def guest_me():
    gst = _guest()
    if not gst:
        return jsonify(ok=True, guest=False)
    return jsonify(ok=True, guest=True, port=gst["port"], perms=gst["perms"], uid=gst["uid"])


@bp_lan.get("/api/lan")
def lan_list():
    if _guest():
        abort(403)
    _share_sweep()
    ip = lan_ip() or _host_ip()
    with _lan_lock:
        return jsonify(ok=True, ip=lan_ip(), ips=lan_ips(), max=LAN_MAX, main_port=MAIN_PORT[0],
                       lans=[_lan_json(l, ip) for l in LANS.values()], shares=[_share_json(s, ip) for s in SHARES.values()])


@bp_lan.post("/api/lan")
def lan_create():
    if _guest():
        abort(403)
    d = request.get_json(force=True, silent=True) or {}
    password = str(d.get("password") or "")[:64]
    perms = {k: bool((d.get("perms") or {}).get(k, True)) for k in LAN_PERMS}
    with _lan_lock:
        if len(LANS) >= LAN_MAX:
            return jsonify(ok=False, error=f"Maximum {LAN_MAX} LANs. Delete one first."), 409
        srv, port = _lan_open(current_app._get_current_object())          # random port, chosen automatically
        if not srv:
            return jsonify(ok=False, error="Could not open a port. Try again."), 409
        lid = secrets.token_hex(4)
        LANS[lid] = {"id": lid, "port": port, "password": password, "perms": perms, "srv": srv, "sessions": set(), "fails": {}, "created": now()}
        _lan_save()
        ip = lan_ip() or _host_ip()
        return jsonify(ok=True, lan=_lan_json(LANS[lid], ip), ip=ip)


def _lan_halt(l):
    srv, l["srv"] = l["srv"], None
    l["sessions"].clear()
    if srv:
        _stop_server(srv)


@bp_lan.post("/api/lan/<lid>/stop")
def lan_stop(lid):
    if _guest():
        abort(403)
    with _lan_lock:
        l = LANS.get(lid)
        if not l:
            return jsonify(ok=False, error="Not found."), 404
        _lan_halt(l)
        _lan_save()
    return jsonify(ok=True)


@bp_lan.post("/api/lan/<lid>/start")
def lan_start(lid):
    if _guest():
        abort(403)
    with _lan_lock:
        l = LANS.get(lid)
        if not l:
            return jsonify(ok=False, error="Not found."), 404
        if not l["srv"]:
            srv, port = _lan_open(current_app._get_current_object(), l["port"])
            if not srv:
                return jsonify(ok=False, error="Could not open a port. Try again."), 409
            l["srv"], l["port"] = srv, port
        _lan_save()
        return jsonify(ok=True, lan=_lan_json(l, lan_ip() or _host_ip()))


@bp_lan.post("/api/lan/<lid>/edit")
def lan_edit(lid):
    if _guest():
        abort(403)
    d = request.get_json(force=True, silent=True) or {}
    with _lan_lock:
        l = LANS.get(lid)
        if not l:
            return jsonify(ok=False, error="Not found."), 404
        if isinstance(d.get("perms"), dict):
            l["perms"] = {k: bool(d["perms"].get(k, l["perms"].get(k, True))) for k in LAN_PERMS}
        if "password" in d:
            pw = str(d.get("password") or "")[:64]
            if pw != l["password"]:
                l["password"] = pw
                l["sessions"].clear()                      # everybody must enter the new password
        _lan_save()
        return jsonify(ok=True, lan=_lan_json(l, lan_ip() or _host_ip()))


@bp_lan.delete("/api/lan/<lid>")
def lan_delete(lid):
    if _guest():
        abort(403)
    with _lan_lock:
        l = LANS.pop(lid, None)
        _lan_unlink(GUEST_DIR, lid)
        if not l:
            _lan_save()
            return jsonify(ok=True)              # already gone = deleted
        _lan_halt(l)
        _lan_save()
    return jsonify(ok=True)


@bp_lan.post("/lan/auth")
def lan_auth():
    gst = _guest()
    if not gst:
        abort(404)
    lan = gst["lan"]
    d = request.get_json(force=True, silent=True) or {}
    ip, t = request.remote_addr or "?", time.time()
    cnt, until = lan["fails"].get(ip, (0, 0))
    if until > t:
        return jsonify(ok=False, error="Too many wrong tries. Wait a minute."), 429
    if hmac.compare_digest(str(d.get("password", "")).encode(), lan["password"].encode()):
        tok = secrets.token_urlsafe(24)
        lan["sessions"].add(tok)
        _lan_save()
        lan["fails"].pop(ip, None)
        resp = jsonify(ok=True)
        resp.set_cookie(f"vla_{lan['port']}", tok, max_age=86400 * 30, httponly=True, samesite="Lax")
        return resp
    cnt += 1
    lan["fails"][ip] = (0, t + 60) if cnt >= 5 else (cnt, 0)
    return jsonify(ok=False, error="Wrong password."), 403


@bp_lan.post("/api/guest/clear-cache")
def guest_clear_cache():
    """Guests may free the downloaded copies of files that are safely in Telegram. Waiting uploads are never touched."""
    return _clear_cache_now()


def _clear_cache_now():
    freed, n = _clear_cache_core()
    return jsonify(ok=True, freed_human=human_size(freed), files=n)


def _clear_cache_core():
    n = freed = 0
    with db() as c:
        rows = c.execute("SELECT id, cache_name FROM files WHERE status='backed_up' AND cache_name IS NOT NULL").fetchall()
        for r in rows:
            p = CACHE / r["cache_name"]
            try:
                if p.is_file():
                    freed += p.stat().st_size
                    p.unlink()
                n += 1
            except OSError:
                continue
            c.execute("UPDATE files SET cache_name=NULL WHERE id=?", (r["id"],))
    TEMP_CACHE.clear()
    # also empty chatview, previews, thumbs and tmp (incl. tmp/stream). The folders stay, only their contents go.
    # A song / video that is playing or loading right now (CUR) keeps its own stream folder, so playback never breaks.
    cur = CUR[0]
    if not cur:
        NEIGH.clear()
        STREAM_NAMES.clear()
    for d in (CHATVIEW, PREVIEWS, THUMBS, TMP):
        try:
            if not d.is_dir():
                continue
            for p in list(d.iterdir()):
                try:
                    if p.name == ".nomedia":
                        continue
                    if d is TMP and p == STREAM_DIR and cur:
                        for sub in list(p.iterdir()):
                            if _sid(sub) in (cur, *NEIGH):
                                continue
                            freed += sum(q.stat().st_size for q in sub.rglob("*") if q.is_file()) if sub.is_dir() else sub.stat().st_size
                            shutil.rmtree(sub, ignore_errors=True) if sub.is_dir() else sub.unlink()
                        continue
                    if p.is_dir() and not p.is_symlink():
                        for q in p.rglob("*"):
                            try:
                                if q.is_file():
                                    freed += q.stat().st_size
                            except OSError:
                                pass
                        shutil.rmtree(p, ignore_errors=True)
                    else:
                        freed += p.stat().st_size
                        p.unlink()
                except OSError:
                    pass
        except OSError:
            pass
    ensure_dirs()
    return freed, n


@bp_library.post("/api/files/clear-cache")
def files_clear_cache():
    """Timeline / Browse menu > Clear cache: same as the guest one - downloaded copies of files that are safe in Telegram go at once."""
    return _clear_cache_now()


# ── share links: one random port per link, serves ONE file, view only ─────────────────────────────────────
_AUD = {".mp3", ".wav", ".m4a", ".aac", ".flac", ".ogg", ".oga", ".opus", ".amr", ".mid", ".weba"}


# What other people SEE through a share link is small (fast, light). What they DOWNLOAD is always the original file.
SHARE_VIEW_PX = 320            # photos: longest side in the viewer (change here)
SHARE_VIEW_P = 144             # videos: height in the viewer, 144p (needs ffmpeg; without it the video shows a poster + Download)
_FFMPEG = shutil.which("ffmpeg")
_SHARE_LOCKS = {}


SHARE_ZOOM_PX = 1000           # photos: size loaded only when someone opens a photo to zoom


def _share_lowres_image(r, px=None):
    px = px or SHARE_VIEW_PX
    out = PREVIEWS / f"sh{r['id']}_{px}.jpg"
    if out.exists():
        return out
    with _SHARE_LOCKS.setdefault(("i", r["id"], px), threading.Lock()):
        if out.exists():
            return out
        try:
            from PIL import Image, ImageOps
            if px <= SHARE_VIEW_PX and local_path(r) is None:
                t = get_thumb(r)                                  # the small low-quality preview we already have (or Telegram's own)
                if t:
                    return t
            im = ImageOps.exif_transpose(Image.open(restore_local(r)))
            im.thumbnail((px, px))
            im.convert("RGB").save(out, "JPEG", quality=50 if px <= SHARE_VIEW_PX else 62, optimize=True, progressive=True)
            return out
        except Exception:
            return get_thumb(r) or make_preview(r)


def _share_lowres_video(r):
    out = PREVIEWS / f"sh{r['id']}_{SHARE_VIEW_P}p.mp4"
    if out.exists():
        return out
    with _SHARE_LOCKS.setdefault(("v", r["id"]), threading.Lock()):
        if out.exists():
            return out
        tmp = PREVIEWS / f"sh{r['id']}_{SHARE_VIEW_P}p.tmp.mp4"
        try:
            subprocess.run([_FFMPEG, "-y", "-i", str(restore_local(r)), "-vf", f"scale=-2:{SHARE_VIEW_P}", "-c:v", "libx264", "-preset", "veryfast",
                            "-crf", "33", "-c:a", "aac", "-b:a", "48k", "-movflags", "+faststart", str(tmp)],
                           check=True, timeout=900, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            tmp.replace(out)
            return out
        except Exception:
            try:
                tmp.unlink()
            except OSError:
                pass
            return None


def _fast(resp):
    """werkzeug sends files in 8 KB pieces by default - far too small for a big file over Wi-Fi. Use 2 MB pieces."""
    try:
        if hasattr(resp.response, "buffer_size"):
            resp.response.buffer_size = 2 * 1024 * 1024
    except Exception:
        pass
    return resp


_TILE = {"apk": "#3b82f6", "zip": "#f97316", "rar": "#f97316", "7z": "#f97316", "pdf": "#ef4444", "doc": "#2563eb", "docx": "#2563eb"}


def _share_card(r, token, i):
    if not r:
        return '<div class="c" style="--n:%d"><div class="pv"><div class="n">Not available any more.</div></div></div>' % i
    name = _html.escape(r["name"])
    ext = Path(r["name"]).suffix.lower()
    src = f"/{token}/m/{i}"
    dl = f'<a class="dl" href="/{token}/d/{i}">Download</a>'
    pb = '<span class="pb">&#9654;</span>'
    if r["kind"] == "image":
        # a div with a background picture (not an <img>): long-press gives no "download image" menu
        inner = f'<div class="pv z sk" data-k="i" data-i="{i}" data-n="{name}" data-bg="{src}"></div>'
    elif r["kind"] == "video" and not _FFMPEG:
        inner = f'<div class="pv sk" data-bg="{src}"></div>'
    elif r["kind"] == "video":
        inner = f'<div class="pv z vd sk" data-k="v" data-i="{i}" data-n="{name}" data-bg="/{token}/p/{i}">{pb}</div>'
    elif ext in _AUD or (r["mime"] or "").startswith("audio/"):
        # song: its cover picture (like the main website), tap = the same animated player
        inner = f'<div class="pv z au sk" data-k="a" data-i="{i}" data-n="{name}" data-bg="/{token}/p/{i}">{pb}</div>'
    else:
        col = _TILE.get(ext[1:], "#6b7280")
        inner = f'<div class="pv"><div class="ic" style="background:{col}">{_html.escape((ext[1:] or "file").upper()[:4])}</div></div>'
    try:
        dt = str(r["taken_at"] or "")[:10].replace("-", "/")
    except Exception:
        dt = ""
    rdt = f'<div class="rdt">{dt}</div>' if dt else ""
    if "pv z" in inner:
        dl = ""
    return f'<div class="c" style="--n:{i}">{inner}<div class="nm">{name}</div>{rdt}{dl}</div>'


