BRAND_B64 = {
    "logo.webp": "",
    "mark-128.png": "",
    "favicon-64.png": "",
    "icon-192.png": "",
    "icon-512.png": "",
    "icon-maskable-512.png": "",
    "apple-touch-icon.png": ""
}
BRAND_B64["badge-96.png"] = ""      # white one-colour cloud: the small status-bar icon of notifications (Android paints only its shape)
_BRAND_BYTES = {}


def _brand(name):
    if name not in BRAND_B64:
        abort(404)
    data = _BRAND_BYTES.setdefault(name, base64.b64decode(BRAND_B64[name]))
    resp = Response(data, mimetype="image/webp" if name.endswith(".webp") else "image/png")
    resp.headers["Cache-Control"] = "no-cache"          # always re-checked (ETag -> 304), so a new logo shows at once
    resp.add_etag()
    return resp.make_conditional(request)


@bp_pages.get("/brand/<name>")
def brand_asset(name):
    return _brand(name)


@bp_pages.get("/favicon.ico")
def favicon_ico():
    return _brand("favicon-64.png")


@bp_pages.get("/apple-touch-icon.png")
def apple_touch_icon():
    return _brand("apple-touch-icon.png")


@bp_pages.get("/manifest.webmanifest")
def web_manifest():
    """Makes the site installable: the logo becomes the app icon and shows in the phone's recent-apps (task) list."""
    icon = lambda f, sz, purpose: {"src": "/brand/" + f, "sizes": f"{sz}x{sz}", "type": "image/png", "purpose": purpose}
    m = {"name": "Cloud Vault", "short_name": "Cloud Vault", "description": "Premium digital security - your private cloud on Telegram",
         "id": "/", "start_url": "/", "scope": "/", "display": "standalone", "background_color": "#091930", "theme_color": "#091930",
         "icons": [icon("icon-192.png", 192, "any"), icon("icon-512.png", 512, "any"), icon("icon-maskable-512.png", 512, "maskable")]}
    resp = Response(json.dumps(m), mimetype="application/manifest+json")
    resp.headers["Cache-Control"] = "no-cache"
    return resp


SW_JS = r'''// Cloud Vault service worker: shows task notifications, and when the server cannot be reached it opens the small /offline page
// (status + paste a link / scan a QR to join another server). It caches only that page and the icon, so the app itself always loads fresh.
const OFF = "vault-offline-v1";
self.addEventListener("install", (e) => {
  e.waitUntil((async () => { try { const c = await caches.open(OFF); await c.addAll(["/offline", "/brand/icon-192.png"]); } catch (er) {} self.skipWaiting(); })());
});
self.addEventListener("activate", (e) => e.waitUntil((async () => {
  try { for (const k of await caches.keys()) if (k !== OFF && k.startsWith("vault-offline")) await caches.delete(k); } catch (er) {}
  await self.clients.claim();
})()));
self.addEventListener("fetch", (e) => {
  const r = e.request;
  if (r.mode !== "navigate") return;
  e.respondWith((async () => {
    const ctl = new AbortController(), t = setTimeout(() => ctl.abort(), 8000);
    try { const res = await fetch(r, { signal: ctl.signal }); clearTimeout(t); return res; }
    catch (er) {
      clearTimeout(t);
      try { const c = await caches.open(OFF); const o = await c.match("/offline"); if (o) return o; } catch (er2) {}
      return Response.error();
    }
  })());
});
async function songBack(k) {                                          // puts the song notifications back: Previous (top) > current > Next (bottom)
  const t0 = Date.now();
  for (let j = k.list.length - 1; j >= 0; j--) {
    const x = k.list[j];
    try { await self.registration.showNotification(x.t, { ...x.b, timestamp: t0 + (k.list.length - j), data: { now: 1, pack: k } }); } catch (er) {}
  }
}
self.addEventListener("notificationclose", (e) => {                         // the user swiped a song notification away: all of them come straight back
  const n = e.notification;
  if (n.tag !== "vault-now" && n.tag !== "vault-next" && n.tag !== "vault-prev") return;
  const k = n.data && n.data.pack;
  if (!k || !k.list) return;
  e.waitUntil(songBack(k));
});
let lastTap = 0;                                                            // time of the last tap on a song notification's body
self.addEventListener("notificationclick", (e) => {
  const n = e.notification, act = e.action;
  if (n.tag === "vault-now" || n.tag === "vault-next" || n.tag === "vault-prev") {                    // the "now playing" notification: its buttons control the song, a tap opens the app
    e.waitUntil((async () => {
      const all = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      if (act) { for (const c of all) { try { c.postMessage({ media: act }); } catch (er) {} } if (!all.length) n.close(); return; }
      const now = Date.now(), k = n.data && n.data.pack;
      if (now - lastTap > 900) {                                            // single tap: the app does NOT open, the notification stays as it is
        lastTap = now;
        if (k && k.list) await songBack(k); 
        return;
      }
      lastTap = 0;                                                          // two quick taps: open the app
      n.close();
      for (const c of all) { if ("focus" in c) { await c.focus(); return; } }
      await self.clients.openWindow("/");
    })());
    return;
  }
  e.notification.close();
  e.waitUntil((async () => {
    const all = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
    for (const c of all) {
      if ("focus" in c) { await c.focus(); try { c.postMessage({ go: "backup" }); } catch (er) {} return; }
    }
    await self.clients.openWindow("/#backup");
  })());
});
'''


@bp_pages.get("/sw.js")
def service_worker():
    resp = Response(SW_JS, mimetype="text/javascript")
    resp.headers["Cache-Control"] = "no-cache"
    resp.headers["Service-Worker-Allowed"] = "/"
    return resp


