# ==============================================================================
# LOCKED FOLDER  - chosen photos hidden behind a PIN / pattern / fingerprint-face
# ==============================================================================
# The secret is never stored, only a salted PBKDF2 hash (storage/config/lock.json). Hidden files get files.locked=1: they vanish from every
# list and their thumb / media / download URLs answer 403 until the folder is unlocked (a cookie session that expires after 10 idle minutes).
# Forgot the secret? A 6-digit code is sent to your Telegram; with it the lock can be changed or switched off.
LOCK_FILE = CONFIG_DIR / "lock.json"
bp_lock = Blueprint("lock", __name__)
LOCKED_IDS = set()
LOCK_SESS = {}                  # cookie token -> idle expiry
LOCK_IDLE = 600
_LOCK_FAIL = {"n": 0, "until": 0.0}
_OTP = {"hash": "", "exp": 0.0, "tries": 0, "sent": 0.0}
_RESET = {"tok": "", "exp": 0.0}
_LK_MUT = threading.Lock()
_PIN_RE = re.compile(r"^\d{4,8}$")
_PAT_RE = re.compile(r"^[0-8](-[0-8]){3,8}$")


LOCK_BAK = CONFIG_DIR / "lock.json.bak"            # second copy: if lock.json is deleted or damaged the lock is restored from here
LOCK_KEEP = CONFIG_DIR / "locked_keep.json"        # which photos are hidden (Telegram message + hash): they stay hidden after Reload / Sync / restore
_KEEP_TICK = {"tok": None}
# third copies in the PRIVATE Termux home (not in the shared storage folder): deleting / wiping the vault folder on the phone does NOT
# remove the lock. Only "turn the lock off" in the app removes it.
try:
    _LOCK_PRIV_DIR = Path(os.environ.get("VAULT_PRIV_DIR") or (Path.home() / ".vault_private"))
except Exception:
    _LOCK_PRIV_DIR = STORAGE / ".private"
LOCK_PRIV = _LOCK_PRIV_DIR / "lock.json"
KEEP_PRIV = _LOCK_PRIV_DIR / "locked_keep.json"


def _mirror(src, *dsts):
    for d in dsts:
        try:
            d.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(src, d)
            os.chmod(d, 0o600)
        except OSError:
            pass


def _lock_mirror():
    _mirror(LOCK_FILE, LOCK_BAK, LOCK_PRIV)


def _keep_mirror():
    _mirror(LOCK_KEEP, KEEP_PRIV)


def _lock_cfg():
    for f in (LOCK_FILE, LOCK_BAK, LOCK_PRIV):
        try:
            d = json.loads(sec_read(f))
            if isinstance(d, dict) and d.get("hash") and d.get("salt"):
                if f is not LOCK_FILE:
                    try:
                        shutil.copyfile(f, LOCK_FILE)                # the lock file was deleted / damaged: put it back
                    except OSError:
                        pass
                    _lock_mirror()
                return d
        except Exception:
            pass
    return {}


def _lock_save(d):
    ensure_dirs()
    if not d:
        for f in (LOCK_FILE, LOCK_BAK, LOCK_PRIV):               # only a deliberate "lock off" removes every copy
            f.unlink(missing_ok=True)
        lockbk_kick(off=True)                                    # an empty backup replaces the old one: a lock removed on purpose stays removed
        return
    tmp = LOCK_FILE.with_suffix(".tmp")
    sec_write(tmp, json.dumps(d))
    os.replace(tmp, LOCK_FILE)                                       # never a half-written file
    _lock_mirror()
    lockbk_kick()


# ── Lock backup in the Telegram channel ───────────────────────────────────────────────────────────────────────────────────────────
# The lock (PIN/pattern HASH, never the PIN) and the list of hidden photos are sent to the channel as ONE encrypted file
# "vault_lock.bin" - together with ALL settings, ALL bots, favorites / turned pictures / Recycle Bin, FTP + share links, wallpaper. The key comes from your Telegram api_id + api_hash (secret, from my.telegram.org), so people who merely see the
# channel cannot read it. After a re-install: log in to Telegram again -> the lock and the hidden-photo list come back by themselves.
# "Turn the lock off" replaces it by an empty one, so a lock you removed on purpose is not brought back.
_LOCKBK_LK = threading.Lock()


def _lockbk_key():
    cr = tl_creds()
    if not cr:
        return None
    return hashlib.pbkdf2_hmac("sha256", f"{cr[0]}:{cr[1]}".encode(), b"vault-lock-backup-v1", 100000)


_SETBK_SKIP = {"api_id", "api_hash", "phone", "profile", "chat_id", "view_chat", "summary_last"}    # login / identity of THIS phone and noise: never copied


def _setbk_settings():
    """All settings that travel inside the same encrypted file as the lock: theme, switches, folders, vault code and ALL bots (token + pool)."""
    d = cfg_load()
    return {k: d[k] for k in DEFAULTS if k not in _SETBK_SKIP}


def _setbk_apply(st):
    """Settings from the Telegram backup come into this phone (first time only): everything is taken, the bots are ADDED to the ones already here."""
    with _cfg_lock:
        d = cfg_load()
        for k, v in st.items():
            if k in _SETBK_SKIP or k in ("bot_token", "bot_pool") or k not in DEFAULTS:
                continue
            if k == "vault_code":
                code = str(v or "").upper()
                if not d["vault_code"] and VALID.match(code):
                    d["vault_code"] = code
            elif k in EDITABLE:
                d[k] = _cfg_clean(k, v)
        pool, seen = list(d["bot_pool"]), {d["bot_token"]} | {b["token"] for b in d["bot_pool"]}
        extra = ([{"name": "Bot", "token": st.get("bot_token", "")}] if st.get("bot_token") else []) + list(st.get("bot_pool") or [])
        for b in extra:
            t = str((b or {}).get("token", "")).strip()
            if t and t not in seen:
                seen.add(t)
                pool.append({"name": str(b.get("name", "")).strip() or "Bot", "token": t})
        if not d["bot_token"] and not pool and st.get("bot_token"):
            d["bot_token"] = str(st["bot_token"]).strip()
        d["bot_pool"] = _cfg_clean("bot_pool", pool)
        _cfg_write(d)


def _setbk_files():
    """Small personal files that are needed again after a re-install: FTP servers, LAN / share links, theme wallpaper, profile picture."""
    out, total = {}, 0
    cands = [CONFIG_DIR / "ftp_state.json", CONFIG_DIR / "download_log.json"]
    if (CONFIG_DIR / "lan").is_dir():
        cands += sorted((CONFIG_DIR / "lan").rglob("*.json"))
    for f in cands:
        try:
            if f.is_file() and f.stat().st_size <= (1 << 20):
                out[f.relative_to(CONFIG_DIR).as_posix()] = {"t": sec_read(f)}
                total += f.stat().st_size
        except Exception:
            pass
    for f in [AVATAR] + sorted(CONFIG_DIR.glob("bg_*")):
        try:
            lg = "avatar.jpg" if f is AVATAR else (f.name[:-5] if f.name.endswith(".json") else f.name)
            if f.is_file() and (f is AVATAR or BG_NAME_RE.match(lg)) and f.stat().st_size <= (2 << 20) and total < (8 << 20):
                out[lg] = {"b": base64.b64encode(f.read_bytes()).decode("ascii")}
                total += f.stat().st_size
        except Exception:
            pass
    return out


def _setbk_marks():
    """What you marked in the library: favorites, turned pictures, the Recycle Bin (matched again by Telegram message / hash). None = do not touch the copy in Telegram."""
    if FAV_KEEP.exists():
        return None                                      # a restore is still waiting for the first Sync: do not overwrite it with an empty library
    try:
        with db() as c:
            if not c.execute("SELECT 1 FROM files LIMIT 1").fetchone():
                return None                              # library not loaded yet on this phone
            rows = c.execute("SELECT chat_id,message_id,sha256,fav,rot,trashed_at FROM files WHERE fav=1 OR rot!=0 OR trashed_at IS NOT NULL").fetchall()
        return [{"c": str(r["chat_id"] or ""), "m": r["message_id"], "s": r["sha256"], "f": int(r["fav"] or 0), "r": int(r["rot"] or 0),
                 "t": r["trashed_at"] or ""} for r in rows]
    except Exception:
        return None


def _lockbk_payload():
    lock, keep = _lock_cfg(), []
    try:
        if LOCK_KEEP.exists():
            keep = json.loads(sec_read(LOCK_KEEP))
    except Exception:
        keep = []
    return {"v": 3, "lock": lock, "keep": keep, "settings": _setbk_settings(), "files": _setbk_files(), "marks": _setbk_marks()}


_BK_LAST = [0.0]


def _jsha(o):
    return hashlib.sha256(json.dumps(o, sort_keys=True).encode()).hexdigest()


_LOCKBK_ALIVE = [0.0]


def _lockbk_check_alive(chat):
    """The saved backup message was deleted from Telegram (by hand or by a bug)? Then forget 'already sent' so a fresh numbered copy goes up."""
    mid = kv_get(f"lockbk_mid:{chat}")
    if not (mid and str(mid).isdigit()) or time.time() - _LOCKBK_ALIVE[0] < 120:
        return
    _LOCKBK_ALIVE[0] = time.time()
    try:
        if tl_ready() and not tl_exists(chat, int(mid)):
            for k in ("lockbk_sha", "lockbk_ssha", "lockbk_mid"):
                kv_set(f"{k}:{chat}", "")
    except Exception:
        pass


def lockbk_sync(force=False, off=False, gap=0):
    """Whatever changed (settings, lock, bots, favorites ...): the NEW file goes up first, then the OLD one is deleted from the channel."""
    d = cfg_load()
    chat = d["chat_id"]
    bots, key = cfg_bots(), _lockbk_key()
    if not (chat and bots and key):
        return False
    if not kv_get(f"setbk_seen:{chat}"):
        return False                                     # the copy in Telegram was not read on this phone yet: never overwrite it blindly
    _lockbk_check_alive(chat)
    pay = _lockbk_payload()
    part = _jsha({"s": pay["settings"], "f": pay["files"], "m": pay["marks"]})
    if (not pay["lock"] and not off) or pay["marks"] is None:
        # lock data / library marks are not here (and were not removed on purpose): that part of the Telegram backup stays exactly as it is
        if part == kv_get(f"lockbk_ssha:{chat}") and not force and kv_get(f"lockbk_no:{chat}"):
            return True
        try:
            if not tl_ready():
                return False
            _m, blob = tl_run(_lockbk_find(chat), 90)
            old = json.loads(vopen(blob, key).decode("utf-8")) if blob else {}
        except Exception:
            return False
        if not pay["lock"] and not off:
            pay["lock"], pay["keep"] = old.get("lock") or {}, old.get("keep") or []
        if pay["marks"] is None:
            pay["marks"] = old.get("marks") or []
    sha = _jsha(pay)
    if sha == kv_get(f"lockbk_sha:{chat}") and not force and kv_get(f"lockbk_no:{chat}"):     # no number saved yet = the copy in Telegram is the old kind: send one numbered copy now
        return True
    if gap and time.time() - _BK_LAST[0] < gap and not force:
        return True                                      # busy files (share counters ...) are not sent more often than every few minutes
    with _LOCKBK_LK:
        if sha == kv_get(f"lockbk_sha:{chat}") and not force and kv_get(f"lockbk_no:{chat}"):
            return True                                  # another thread just uploaded this same backup while we waited for the lock: never send it twice
        tmp = TMP / f"lockbk_{time.time_ns()}.bin"
        try:
            ensure_dirs()
            tmp.write_bytes(vseal(json.dumps(pay, sort_keys=True).encode("utf-8"), key))
            tok = bots[0]["token"]
            slot = 2 if str(kv_get(f"lockbk_no:{chat}")) == "1" else 1       # No: 1 and No: 2 take turns - the other number is deleted after each upload
            res = tgapi_call(tok, "sendDocument", {"chat_id": chat, "caption": "VAULT LOCK BACKUP (encrypted)" + (f"\nCODE: {d['vault_code']}" if d.get("vault_code") else "") + f"\nNo: {slot}", "disable_notification": "true"},
                             file_path=str(tmp), upload_name="vault_lock.bin", timeout=120)
            old_mid = kv_get(f"lockbk_mid:{chat}")
            kv_set(f"lockbk_mid:{chat}", res["message_id"])
            kv_set(f"lockbk_no:{chat}", slot)
            kv_set(f"lockbk_sha:{chat}", sha)
            kv_set(f"lockbk_ssha:{chat}", part)
            _BK_LAST[0] = time.time()
            if old_mid and str(old_mid).isdigit():
                try:
                    tgapi_call(tok, "deleteMessage", {"chat_id": chat, "message_id": int(old_mid)}, timeout=30)      # the OLD file is deleted
                except Exception:
                    pass                                 # the newest message always wins when it is restored
            try:
                if tl_ready():                           # every other older vault_lock.bin of this vault (same CODE, or old ones without a CODE) goes too
                    old_ids = tl_run(_lockbk_olds(chat, res["message_id"], d.get("vault_code")), 90)
                    if old_ids:
                        tl_purge(chat, old_ids)
            except Exception:
                pass
            return True
        except Exception as e:
            print(f"[lock backup] not sent: {e}", flush=True)
            return False
        finally:
            tmp.unlink(missing_ok=True)


def lockbk_kick(off=False):
    if off:
        threading.Thread(target=lambda: lockbk_sync(off=True), daemon=True, name="lock-backup").start()
    else:
        threading.Thread(target=lambda: lockbk_step(True), daemon=True, name="lock-backup").start()


_SETBK_T = [None]


def setbk_kick():
    """Settings were saved: a few seconds later (many switches in a row = ONE upload) they go into the Telegram backup."""
    t = _SETBK_T[0]
    if t:
        t.cancel()
    t = threading.Timer(8.0, lambda: lockbk_step(True))
    t.daemon = True
    _SETBK_T[0] = t
    t.start()


async def _lockbk_olds(chat_id, keep_mid, code):
    """Ids of older vault_lock.bin messages of THIS vault (caption has our CODE, or no CODE at all = older versions). Other vaults' codes are left alone."""
    c = await _client()
    ent = await _entity(c, chat_id)
    out = []
    async for m in c.iter_messages(ent, search="VAULT LOCK BACKUP", limit=100):
        doc = getattr(m, "document", None)
        if not doc or m.id >= int(keep_mid) or not any(getattr(a, "file_name", "") == "vault_lock.bin" for a in (doc.attributes or [])):
            continue
        cm = CODE_RE.search(getattr(m, "message", "") or "")
        if not cm or not code or cm.group(1).upper() == code.upper():
            out.append(m.id)
    return out


async def _lockbk_find(chat_id):
    c = await _client()
    ent = await _entity(c, chat_id)
    async for m in c.iter_messages(ent, search="VAULT LOCK BACKUP", limit=30):         # newest first
        doc = getattr(m, "document", None)
        if doc and any(getattr(a, "file_name", "") == "vault_lock.bin" for a in (doc.attributes or [])):
            return m.id, await c.download_media(m, file=bytes)
    return None, None


def lockbk_restore():
    """The encrypted file in the Telegram channel brings back, by itself: (1) all settings + ALL bots (the first time on this phone),
    (2) the lock + the hidden-photo list (when the lock files are gone here). Needs: Telegram login + chat id + one bot token."""
    chat = cfg_load()["chat_id"]
    key = _lockbk_key()
    if not (chat and key and tl_ready()):
        return False
    seen = bool(kv_get(f"setbk_seen:{chat}"))
    need_lock = not _lock_cfg()
    if seen and not need_lock:
        return False
    try:
        mid, blob = tl_run(_lockbk_find(chat), 90)
    except Exception:
        return False                                     # network problem: nothing is marked, it is tried again later
    pay = {}
    if blob:
        try:
            pay = json.loads(vopen(blob, key).decode("utf-8"))
        except Exception:
            pay = {}                                     # not readable with this api id / hash: it will be replaced by a fresh one
    got = False
    if not seen:
        for rel, fv in (pay.get("files") or {}).items():            # wallpaper, FTP servers, share links ... (only what is missing here)
            try:
                dst = cfgimg(rel).resolve()
                if CONFIG_DIR.resolve() not in dst.parents or dst.exists() or not isinstance(fv, dict):
                    continue
                dst.parent.mkdir(parents=True, exist_ok=True)
                if "t" in fv:
                    sec_write(dst, str(fv["t"]))
                elif "b" in fv:
                    dst.write_bytes(base64.b64decode(fv["b"]))
            except Exception:
                pass
        marks = pay.get("marks")
        if isinstance(marks, list) and marks and not FAV_KEEP.exists():
            try:
                sec_write(FAV_KEEP, json.dumps(marks))                # favorites / turns / bin are put back by the first Sync
            except Exception:
                pass
        st = pay.get("settings")
        if isinstance(st, dict) and st:
            _setbk_apply(st)
            got = True
            print("  Settings and bots restored from the Telegram channel backup.", flush=True)
        if mid:
            kv_set(f"lockbk_mid:{chat}", mid)
        kv_set(f"setbk_seen:{chat}", "1")
    lock, keep = pay.get("lock") or {}, pay.get("keep") or []
    if need_lock and isinstance(lock, dict) and lock.get("hash") and lock.get("salt"):      # (an empty lock = it was removed on purpose)
        with _LK_MUT:
            if not _lock_cfg():
                kv_set(f"lockbk_mid:{chat}", mid)
                kv_set(f"lockbk_sha:{chat}", hashlib.sha256(json.dumps({"v": 1, "lock": lock, "keep": keep}, sort_keys=True).encode()).hexdigest())
                if keep:
                    tmpk = LOCK_KEEP.with_suffix(".tmp")
                    ensure_dirs()
                    sec_write(tmpk, json.dumps(keep))
                    os.replace(tmpk, LOCK_KEEP)
                    _keep_mirror()
                _lock_save(lock)
                _KEEP_TICK["tok"] = None
                got = True
                print("  Lock restored from the Telegram channel backup.", flush=True)
    return got


_HEAL_LAST = [0.0]


def lockbk_heal():
    """A small personal file the app needs (the wallpaper in use, the profile picture) is gone from this phone: it is taken from the
    Telegram backup again - as often as needed. Nothing is overwritten, only missing files come back."""
    d = cfg_load()
    chat, key = d["chat_id"], _lockbk_key()
    if not (chat and key and tl_ready() and kv_get(f"setbk_seen:{chat}")):
        return False
    want = []
    img = str((d.get("custom_theme") or {}).get("image", ""))
    if BG_NAME_RE.match(img) and not cfgimg(img).exists():
        want.append(img)
    if d.get("profile") and not AVATAR.exists():
        want.append("avatar.jpg")
    if not want or time.time() - _HEAL_LAST[0] < 600:
        return False                                     # nothing missing (or tried a few minutes ago)
    _HEAL_LAST[0] = time.time()
    try:
        _m, blob = tl_run(_lockbk_find(chat), 90)
        files = (json.loads(vopen(blob, key).decode("utf-8")).get("files") or {}) if blob else {}
    except Exception:
        return False
    got = False
    for rel in want:
        fv = files.get(rel)
        if isinstance(fv, dict) and fv.get("b"):
            try:
                cfgimg(rel).write_bytes(base64.b64decode(fv["b"]))
                got = True
            except Exception:
                pass
    return got


def lockbk_step(quick=False):
    """One round: read the Telegram copy when needed (first time / lock gone), then send the newest backup (quick = you just changed something)."""
    d = cfg_load()
    chat = d["chat_id"]
    if not (chat and cfg_bots() and _lockbk_key()):
        return False
    if (not kv_get(f"setbk_seen:{chat}") or not _lock_cfg()) and tl_ready():
        lockbk_restore()
    try:
        lockbk_heal()                                    # first bring back what is missing, only then send the newest copy
    except Exception:
        pass
    return lockbk_sync(gap=0 if quick else 240)


def lockbk_watchdog():
    time.sleep(20)
    while True:
        wait = 60
        try:
            lockbk_step()
            chat = cfg_load()["chat_id"]
            if chat and not kv_get(f"setbk_seen:{chat}"):
                wait = 20                                # fresh phone: look again soon (login / chat id / bot token may still be coming)
        except Exception:
            pass
        time.sleep(wait)


def _lock_is_set():
    """True when a PIN/pattern exists - or when hidden photos exist but the lock data is gone (then only the Telegram code can open it)."""
    return bool(_lock_cfg().get("hash")) or bool(LOCKED_IDS)


def _lock_keep_write():
    try:
        with db() as c:
            items = [{"c": str(r["chat_id"] or ""), "m": r["message_id"], "s": r["sha256"] or ""}
                     for r in c.execute("SELECT chat_id, message_id, sha256 FROM files WHERE locked=1")]
        if not items:
            LOCK_KEEP.unlink(missing_ok=True)
            KEEP_PRIV.unlink(missing_ok=True)
            lockbk_kick()
            return
        tmp = LOCK_KEEP.with_suffix(".tmp")
        sec_write(tmp, json.dumps(items))
        os.replace(tmp, LOCK_KEEP)
        _keep_mirror()
        lockbk_kick()
    except Exception:
        pass


def _lock_keep_tick():
    """Photos remembered in locked_keep.json are hidden again the moment they re-appear in the index (Reload Cloud Vault, Sync, restore)."""
    if not LOCK_KEEP.exists() and KEEP_PRIV.exists():
        _mirror(KEEP_PRIV, LOCK_KEEP)                            # the list of hidden photos was deleted: put it back
    if not LOCK_KEEP.exists():
        return
    if not (_lock_cfg().get("hash") or LOCKED_IDS):          # lock is off: remembered photos stay in the library until a new lock is made
        return
    tok = _db_token()
    if _KEEP_TICK["tok"] == tok:
        return
    with _LK_MUT:
        try:
            items = json.loads(sec_read(LOCK_KEEP))
            cm = {(str(i.get("c") or ""), i.get("m")) for i in items if i.get("m")}
            sh = {i["s"] for i in items if i.get("s")}
            with db() as c:
                ids = [r["id"] for r in c.execute("SELECT id, chat_id, message_id, sha256 FROM files WHERE locked=0")
                       if (str(r["chat_id"] or ""), r["message_id"]) in cm or r["sha256"] in sh]
                if ids:
                    c.executemany("UPDATE files SET locked=1 WHERE id=?", [(i,) for i in ids])
            LOCKED_IDS.update(ids)
        except Exception:
            return
        _KEEP_TICK["tok"] = _db_token()


def _lk_hash(secret, salt):
    return hashlib.pbkdf2_hmac("sha256", str(secret).encode(), bytes.fromhex(salt), 120000).hex()


def _lock_reload_ids():
    with db() as c:
        ids = {r[0] for r in c.execute("SELECT id FROM files WHERE locked=1")}
    LOCKED_IDS.clear()
    LOCKED_IDS.update(ids)


def _unlocked():
    t = request.cookies.get("vlk")
    exp = LOCK_SESS.get(t) if t else None
    if exp and exp > time.time():
        LOCK_SESS[t] = time.time() + LOCK_IDLE
        return True
    return False


def _lk_session(resp):
    now_t = time.time()
    for k in [k for k, v in LOCK_SESS.items() if v < now_t]:
        LOCK_SESS.pop(k, None)
    tok = secrets.token_urlsafe(24)
    LOCK_SESS[tok] = now_t + LOCK_IDLE
    resp.set_cookie("vlk", tok, httponly=True, samesite="Lax", max_age=86400)
    return resp


def _lk_valid(method, secret):
    return bool(_PIN_RE.fullmatch(secret or "") if method == "pin" else _PAT_RE.fullmatch(secret or "") and len(set(secret.split("-"))) == len(secret.split("-"))) \
        if method in ("pin", "pattern") else False


def _lk_throttle():
    if _LOCK_FAIL["until"] > time.time():
        return jsonify(ok=False, error=f"Too many wrong tries. Wait {int(_LOCK_FAIL['until'] - time.time()) + 1} s."), 429
    return None


def _lk_wrong():
    _LOCK_FAIL["n"] += 1
    if _LOCK_FAIL["n"] >= 5:
        _LOCK_FAIL.update(n=0, until=time.time() + 60)
    return jsonify(ok=False, error="Wrong PIN / pattern."), 403


def _lk_need():
    if not _unlocked():
        return jsonify(ok=False, error="Locked Folder is locked."), 403
    return None


@bp_lock.before_request
def _lk_guard():
    if _guest():
        return jsonify(ok=False, error="Not allowed"), 403


@bp_lock.get("/api/lock/status")
def lock_status():
    _lock_keep_tick()
    d = _lock_cfg()
    return jsonify(ok=True, set=_lock_is_set(), method=d.get("method", "pin"), bio=bool(d.get("bio")), unlocked=_unlocked(),
                   lost=bool(not d.get("hash") and LOCKED_IDS))


@bp_lock.post("/api/lock/setup")
def lock_setup():
    j = request.get_json(force=True, silent=True) or {}
    if _lock_is_set():
        return jsonify(ok=False, error="A PIN / pattern already exists (or hidden photos need it). Use Forgot PIN / pattern."), 409
    m, sec = j.get("method"), str(j.get("secret") or "")
    if not _lk_valid(m, sec):
        return jsonify(ok=False, error="PIN: 4-8 digits. Pattern: connect at least 4 dots."), 400
    salt = secrets.token_hex(16)
    _lock_save({"method": m, "salt": salt, "hash": _lk_hash(sec, salt), "bio": []})
    _KEEP_TICK["tok"] = None
    _lock_keep_tick()                                        # photos that were locked before come back into the lock
    return _lk_session(jsonify(ok=True))


@bp_lock.post("/api/lock/unlock")
def lock_unlock():
    d = _lock_cfg()
    if not d.get("hash"):
        return jsonify(ok=False, error="The lock data was lost. Tap Forgot PIN / pattern to get a code on Telegram." if LOCKED_IDS else "No PIN / pattern set yet."), 400
    t = _lk_throttle()
    if t:
        return t
    sec = str((request.get_json(force=True, silent=True) or {}).get("secret") or "")
    if not hmac.compare_digest(_lk_hash(sec, d["salt"]), d["hash"]):
        return _lk_wrong()
    _LOCK_FAIL["n"] = 0
    return _lk_session(jsonify(ok=True))


@bp_lock.post("/api/lock/lock")
def lock_lock():
    LOCK_SESS.pop(request.cookies.get("vlk"), None)
    return jsonify(ok=True)


@bp_lock.post("/api/lock/off")
def lock_off():
    """Menu > Unlock: the CURRENT PIN / pattern is checked, then the lock is removed for good and every hidden file goes back to the library.
    It stays that way until a file is locked again (that asks for a new PIN / pattern)."""
    d = _lock_cfg()
    if not d.get("hash"):
        return jsonify(ok=False, error="No PIN / pattern is set."), 400
    t = _lk_throttle()
    if t:
        return t
    sec = str((request.get_json(force=True, silent=True) or {}).get("secret") or "")
    if not hmac.compare_digest(_lk_hash(sec, d["salt"]), d["hash"]):
        return _lk_wrong()
    _LOCK_FAIL["n"] = 0
    with _LK_MUT:
        with db() as c:
            n = c.execute("SELECT COUNT(*) FROM files WHERE locked=1").fetchone()[0]
        _lock_keep_write()                                   # remember them: they go back into the lock when a new lock is made
        with db() as c:
            c.execute("UPDATE files SET locked=0 WHERE locked=1")
        LOCKED_IDS.clear()
    _lock_save(None)
    LOCK_SESS.pop(request.cookies.get("vlk"), None)
    FTP_LK_STATE["until"] = 0.0
    _ftp_forget()
    return jsonify(ok=True, unhidden=n)


@bp_lock.post("/api/lock/change")
def lock_change():
    bad = _lk_need()
    if bad:
        return bad
    j = request.get_json(force=True, silent=True) or {}
    m, sec = j.get("method"), str(j.get("secret") or "")
    if not _lk_valid(m, sec):
        return jsonify(ok=False, error="PIN: 4-8 digits. Pattern: connect at least 4 dots."), 400
    d = _lock_cfg()
    d.update(method=m, salt=secrets.token_hex(16))
    d["hash"] = _lk_hash(sec, d["salt"])
    _lock_save(d)
    return jsonify(ok=True)


@bp_lock.post("/api/lock/bio")
def lock_bio():
    """Fingerprint / face: the phone does the check (WebAuthn); this device keeps a random key that the server only knows as a hash."""
    bad = _lk_need()
    if bad:
        return bad
    d = _lock_cfg()
    if (request.get_json(force=True, silent=True) or {}).get("enable"):
        key = secrets.token_urlsafe(24)
        d["bio"] = (d.get("bio") or [])[-4:] + [hashlib.sha256(key.encode()).hexdigest()]
        _lock_save(d)
        return jsonify(ok=True, secret=key)
    d["bio"] = []
    _lock_save(d)
    return jsonify(ok=True)


@bp_lock.post("/api/lock/bio_unlock")
def lock_bio_unlock():
    d = _lock_cfg()
    t = _lk_throttle()
    if t:
        return t
    key = hashlib.sha256(str((request.get_json(force=True, silent=True) or {}).get("secret") or "").encode()).hexdigest()
    if not any(hmac.compare_digest(key, h) for h in (d.get("bio") or [])):
        return _lk_wrong()
    _LOCK_FAIL["n"] = 0
    return _lk_session(jsonify(ok=True))


OTP_TTL = 300                        # a "forgot PIN / pattern" code lives 5 minutes, then it stops working AND its Telegram message is deleted


def _otp_send(text):
    """Sends the code to Telegram; returns (where, ref) - ref lets _otp_forget() delete that message again."""
    if TL_HAVE and tl_ready():
        async def _m():
            c = await _client()
            m = await c.send_message("me", text)
            return getattr(m, "id", None)
        mid = tl_run(_m(), 30)
        return "your Telegram (Saved Messages)", ("tl", mid)
    bots, chat = cfg_bots(), cfg_get("chat_id")
    if bots and chat:
        r = tgapi_call(bots[0]["token"], "sendMessage", {"chat_id": chat, "text": text}, timeout=30)
        return "your Telegram vault chat", ("bot", bots[0]["token"], chat, (r or {}).get("message_id"))
    raise RuntimeError("Telegram is not connected. Log in to Telegram (Settings > Account) or add a bot first.")


def _otp_forget(ref):
    """Deletes the code message from Telegram (best effort; never raises)."""
    try:
        if not ref or not ref[-1]:
            return
        if ref[0] == "tl":
            async def _d():
                c = await _client()
                await c.delete_messages("me", [ref[1]])
            tl_run(_d(), 30)
        else:
            tgapi_call(ref[1], "deleteMessage", {"chat_id": ref[2], "message_id": ref[3]}, timeout=30)
    except Exception:
        pass


def _otp_expire(ref, exp):
    """Runs when the 5 minutes are over: the code is dead and the message disappears from Telegram."""
    if _OTP.get("exp") == exp:                       # (a newer code may have replaced it - leave that one alone)
        _OTP.update(hash="", exp=0.0)
    _otp_forget(ref)


@bp_lock.post("/api/lock/forgot")
def lock_forgot():
    if not _lock_is_set():
        return jsonify(ok=False, error="No PIN / pattern set yet."), 400
    if time.time() - _OTP["sent"] < 30:
        return jsonify(ok=False, error="A code was just sent. Wait 30 seconds."), 429
    code = f"{secrets.randbelow(1000000):06d}"
    try:
        where, ref = _otp_send(f"Cloud Vault code: {code}\nUse it to reset your Locked Folder PIN / pattern. Valid for 5 minutes - then this message is deleted. If this was not you, ignore it.")
    except Exception as e:
        return jsonify(ok=False, error=str(e)), 502
    exp = time.time() + OTP_TTL
    _OTP.update(hash=hashlib.sha256(code.encode()).hexdigest(), exp=exp, tries=0, sent=time.time())
    t = threading.Timer(OTP_TTL + 1, _otp_expire, args=(ref, exp)); t.daemon = True; t.start()
    return jsonify(ok=True, message=f"Code sent to {where}.")


@bp_lock.post("/api/lock/otp")
def lock_otp():
    code = str((request.get_json(force=True, silent=True) or {}).get("otp") or "").strip()
    if not _OTP["hash"] or _OTP["exp"] < time.time():
        return jsonify(ok=False, error="No valid code. Send a new one."), 400
    _OTP["tries"] += 1
    if _OTP["tries"] > 5:
        _OTP["hash"] = ""
        return jsonify(ok=False, error="Too many wrong codes. Send a new one."), 429
    if not hmac.compare_digest(hashlib.sha256(code.encode()).hexdigest(), _OTP["hash"]):
        return jsonify(ok=False, error="Wrong code."), 403
    _OTP["hash"] = ""
    _RESET.update(tok=secrets.token_urlsafe(20), exp=time.time() + 300)
    return jsonify(ok=True, token=_RESET["tok"])


@bp_lock.post("/api/lock/reset")
def lock_reset():
    j = request.get_json(force=True, silent=True) or {}
    if not _RESET["tok"] or _RESET["exp"] < time.time() or not hmac.compare_digest(str(j.get("token") or ""), _RESET["tok"]):
        return jsonify(ok=False, error="Code expired. Start again."), 403
    if j.get("action") == "off":                                    # lock switched off: every hidden photo goes back to the library
        with _LK_MUT:
            _lock_keep_write()                               # remember them: they go back into the lock when a new lock is made
            with db() as c:
                c.execute("UPDATE files SET locked=0 WHERE locked=1")
            LOCKED_IDS.clear()
        _lock_save(None)
        _RESET["tok"] = ""
        return jsonify(ok=True)
    m, sec = j.get("method"), str(j.get("secret") or "")
    if not _lk_valid(m, sec):
        return jsonify(ok=False, error="PIN: 4-8 digits. Pattern: connect at least 4 dots."), 400
    salt = secrets.token_hex(16)
    _lock_save({"method": m, "salt": salt, "hash": _lk_hash(sec, salt), "bio": []})
    _RESET["tok"] = ""
    return _lk_session(jsonify(ok=True))


def _lk_ids():
    return [int(i) for i in ((request.get_json(force=True, silent=True) or {}).get("ids") or []) if str(i).isdigit()][:5000]


@bp_lock.post("/api/lock/hide")
def lock_hide():
    if not _lock_is_set():                       # hiding photos needs no PIN (only OPENING / unhiding does) - but a PIN / pattern must exist
        return jsonify(ok=False, error="Create a PIN or pattern first.", need_setup=True), 403
    ids = _lk_ids()
    if not ids:
        return jsonify(ok=False, error="Select photos first."), 400
    with _LK_MUT:
        with db() as c:
            c.execute(f"UPDATE files SET locked=1 WHERE id IN ({','.join('?' * len(ids))})", ids)
        LOCKED_IDS.update(ids)
        _lock_keep_write()
        for _i in ids:
            _seal_wipe(_i)                               # their thumbnail / preview files are removed (shown from memory from now on)
        try:                                             # old readable cache copies (earlier HD views) of photos that are safe in Telegram are removed
            with db() as c:
                for r in c.execute(f"SELECT id, cache_name, source_path FROM files WHERE id IN ({','.join('?' * len(ids))}) AND status='backed_up' "
                                   "AND chat_id IS NOT NULL AND message_id IS NOT NULL AND cache_name IS NOT NULL", ids).fetchall():
                    if r["source_path"] and Path(r["source_path"]).is_file():
                        continue
                    (CACHE / r["cache_name"]).unlink(missing_ok=True)
                    TEMP_CACHE.pop(r["id"], None)
                    c.execute("UPDATE files SET cache_name=NULL WHERE id=?", (r["id"],))
        except Exception:
            pass
    _ftp_forget()
    return jsonify(ok=True, hidden=len(ids))


@bp_lock.post("/api/lock/unhide")
def lock_unhide():
    bad = _lk_need()
    if bad:
        return bad
    ids = _lk_ids()
    if not ids:
        return jsonify(ok=False, error="Select photos first."), 400
    with _LK_MUT:
        with db() as c:
            c.execute(f"UPDATE files SET locked=0 WHERE id IN ({','.join('?' * len(ids))})", ids)
        LOCKED_IDS.difference_update(ids)
        _lock_keep_write()
    _ftp_forget()
    return jsonify(ok=True, unhidden=len(ids))


@bp_lock.get("/api/lock/files")
def lock_files():
    bad = _lk_need()
    if bad:
        return bad
    _lock_keep_tick()
    if not _SEAL_SWEPT[0]:
        _seal_sweep()
    with db() as c:
        rows = c.execute("SELECT * FROM files WHERE locked=1 AND trashed_at IS NULL ORDER BY taken_at DESC, id DESC LIMIT 5000").fetchall()
    return jsonify(ok=True, files=[to_json(r, cfg_get("vault_code")) for r in rows])


_LOCK_PATH_RE = re.compile(r"^/(?:thumb|preview|media|download)/(\d+)|^/api/files/(\d+)/")


def _lock_gate():
    """Hidden photos: their picture / file URLs answer 403 while the folder is locked (and always for LAN guests)."""
    m = _LOCK_PATH_RE.match(request.path)
    if m:
        _lock_keep_tick()
        if int(m.group(1) or m.group(2)) in LOCKED_IDS and (_guest() or not _unlocked()):
            return Response("Locked.", status=403, mimetype="text/plain")


# ==============================================================================
# APP FACTORY + START  (was vault/__init__.py + run.py)
# ==============================================================================
# ── LANES: the page never gets stuck, however many things are clicked at the same time ───────────────────────────────────────
# Slow requests (pictures / songs / videos that may have to come from Telegram, downloads) each get their OWN small lane with a
# fixed number of places and a short waiting line. When a lane is full the extra request waits its turn (or is told "busy, try again
# in a second" at once) - it never takes a thread away from the normal clicks (lists, buttons, settings, job progress), which are
# always answered immediately. Total threads = lanes + a reserve for the light requests.
LANE_FAST_RE = re.compile(r"^/(media|thumb|preview)/\d+|^/api/(tags|chat/media)")
LANE_BULK_RE = re.compile(r"^/(download/|api/(zip|download))")
LANE_FAST = int(os.environ.get("VAULT_LANE_FAST", "10"))        # pictures / songs being prepared at the same moment
LANE_BULK = int(os.environ.get("VAULT_LANE_BULK", "4"))         # big downloads at the same moment


class _Lane:
    def __init__(self, places, line, wait):
        self.sem, self.line, self.wait, self.waiting, self.lk = threading.BoundedSemaphore(places), line, wait, 0, threading.Lock()

    def enter(self):
        if self.sem.acquire(blocking=False):
            return True
        with self.lk:
            if self.waiting >= self.line:
                return False                                   # the waiting line is full: answer "busy" at once, keep the thread free
            self.waiting += 1
        try:
            return self.sem.acquire(timeout=self.wait)
        finally:
            with self.lk:
                self.waiting -= 1


class _Lanes:
    def __init__(self, app):
        self.app = app
        self.fast = _Lane(LANE_FAST, LANE_FAST * 2, 25)
        self.bulk = _Lane(LANE_BULK, LANE_BULK + 2, 60)

    def __call__(self, environ, start_response):
        path = environ.get("PATH_INFO", "")
        lane = self.fast if LANE_FAST_RE.match(path) else (self.bulk if LANE_BULK_RE.match(path) else None)
        if lane is None:
            return self.app(environ, start_response)
        if not lane.enter():
            return Response("Busy - try again in a moment.", status=503, mimetype="text/plain", headers={"Retry-After": "1"})(environ, start_response)
        try:
            it = self.app(environ, start_response)
        except BaseException:
            lane.sem.release()
            raise
        return _Closing(it, lane.sem.release)


def create_app(max_upload_mb=None):
    max_upload_mb = max_upload_mb or int(os.environ.get("VAULT_MAX_UPLOAD_MB", "2048"))      # per file, browser upload
    ensure_dirs()
    app = Flask(__name__, static_folder=None)
    app.config["MAX_CONTENT_LENGTH"] = max_upload_mb * 1024 * 1024
    app.config["SEND_FILE_MAX_AGE_DEFAULT"] = 0

    for b in (bp_pages, bp_config, bp_library, bp_backup, bp_tg, bp_lan, bp_lock):
        app.register_blueprint(b)

    app.wsgi_app = _Lanes(app.wsgi_app)               # slow requests wait in their own lane, normal clicks are never blocked
    app.before_request(_lan_gate)                   # first of all: who is asking (owner or LAN guest) and what may they touch
    app.before_request(_lock_gate)                  # hidden photos stay closed while the Locked Folder is locked

    @app.after_request
    def guest_cookie(resp):
        uid, gst = getattr(g, "set_uid", None), getattr(g, "guest", None)
        if uid and gst:
            resp.set_cookie(f"vlg_{gst['port']}", uid, max_age=86400 * 365, httponly=True, samesite="Lax")
        return resp

    @app.before_request
    def no_direct_open():
        if (request.path.startswith(("/thumb/", "/preview/", "/media/", "/api/chat/media"))
                and request.headers.get("Sec-Fetch-Dest") in ("document", "iframe", "embed", "object", "frame")):
            return "Use the Download button inside the app.", 403

    @app.before_request
    def block_cross_origin():
        if request.method in ("POST", "PUT", "PATCH", "DELETE"):
            o = request.headers.get("Origin")
            if o and urlparse(o).netloc != request.host:
                return jsonify(ok=False, error="Cross-origin request blocked."), 403

    @app.after_request
    def squeeze(resp):
        try:
            if (resp.status_code == 200 and not resp.direct_passthrough and "gzip" in request.headers.get("Accept-Encoding", "")
                    and not resp.headers.get("Content-Encoding") and resp.mimetype in ("application/json", "text/html", "text/css", "text/javascript", "application/javascript", "image/svg+xml")):
                data = resp.get_data()
                if len(data) > 700:
                    resp.set_data(gzip.compress(data, 4))
                    resp.headers["Content-Encoding"] = "gzip"
                    resp.headers["Vary"] = "Accept-Encoding"
        except Exception:
            pass
        return resp

    @app.errorhandler(Exception)
    def on_error(e):
        if isinstance(e, HTTPException):
            if request.path.startswith("/api/"):
                return jsonify(ok=False, error=e.description), e.code
            return e
        app.logger.exception("Unhandled error")
        log_problem("Server", f"{request.method} {request.path}: {e}")
        return jsonify(ok=False, error=f"Server error: {e}"), 500

    _lock_reload_ids()
    try:                                                # vault_lock.bin that an earlier version imported into the library by mistake
        with db() as c:
            c.execute("DELETE FROM files WHERE name='vault_lock.bin'")
    except Exception:
        pass
    thumb_upgrade()
    job_start()
    threading.Thread(target=_share_janitor, daemon=True, name='share-janitor').start()
    threading.Thread(target=cache_janitor, daemon=True, name='cache-janitor').start()
    threading.Thread(target=retry_watchdog, daemon=True, name='retry-watchdog').start()
    threading.Thread(target=trash_watchdog, daemon=True, name='trash-watchdog').start()
    threading.Thread(target=code_pin_watchdog, daemon=True, name='code-pin').start()
    threading.Thread(target=lockbk_watchdog, daemon=True, name='lock-backup-watch').start()
    threading.Thread(target=auto_clear_watchdog, daemon=True, name='auto-clear').start()
    threading.Thread(target=daily_summary_watchdog, daemon=True, name='daily-summary').start()
    threading.Thread(target=meta_backfill_worker, daemon=True, name='meta-backfill').start()
    threading.Thread(target=ocr_worker, daemon=True, name='ocr-worker').start()
    threading.Thread(target=lambda: tl_ready(True), daemon=True).start()    # warm up login state
    return app


import logging as _logging, gc as _gc
_logging.getLogger("werkzeug").setLevel(_logging.ERROR)     # no "GET /thumb/123 200" line for every picture
_gc.set_threshold(20000, 20, 20)                            # fewer garbage-collector pauses while thousands of small objects are built

app = create_app()

def run_main(host=None, port=None):                  # ANDROID PATCH: callable entry point (android_entry.py starts it in a thread)
    host = host or os.environ.get("VAULT_HOST", "127.0.0.1")
    port = int(port or os.environ.get("VAULT_PORT", "8080"))
    MAIN_PORT[0] = port
    sec_migrate()                                    # plain personal files -> encrypted
    try:
        if _lock_cfg():                              # restores a deleted lock file from the private copy, and refreshes the copies
            _lock_mirror()
        if LOCK_KEEP.exists():
            _keep_mirror()
    except Exception:
        pass
    _lan_restore(app)                                # LANs / share links that were ON before the restart come back ON
    _ftp_restore()                                   # FTP servers that were ON come back ON
    print("\nTelegram Cloud Vault")
    print(f"  Build {BOOT_HM}  -  running file: {Path(__file__).resolve()}")
    print(f"  Open: http://127.0.0.1:{port}")
    try:
        _ips = lan_ips()
        print("  This phone's network IPs (use with a LAN port):", ", ".join(_ips) if _ips else "none yet - connect to Wi-Fi or turn the hotspot on")
    except Exception:
        pass
    print(f"  Data: {STORAGE}")
    print("  Telegram login/search (Telethon):", "ready" if TL_HAVE else "NOT installed -> pip install telethon")
    print("  Keep this server private: it has no password and stores your bot tokens locally.\n")
    try:
        if os.environ.get("VAULT_WAITRESS", "1") == "0":
            raise ImportError
        from waitress import serve                          # pure-python, fixed thread pool: much lighter than a thread per connection
        print("  Server: waitress (light mode)\n")
        serve(app, host=host, port=port, threads=int(os.environ.get("VAULT_THREADS", "48")), channel_timeout=120,
              connection_limit=200, ident="vault", send_bytes=262144,
              max_request_body_size=int(os.environ.get("VAULT_MAX_UPLOAD_MB", "2048")) * 1024 * 1024)
    except ImportError:
        app.run(host=host, port=port, debug=False, threaded=True)


if __name__ == "__main__":
    run_main()
